// Nom du pays dans la langue courante
function nomPays(code) {
  const p = COUNTRIES.find(c => c.code === code);
  if (!p) return code;
  return (_lang === 'en' && p.en) ? p.en : p.label;
}

function getCurrencySymbol(code) {
  return CURRENCIES.find(c => c.code === code)?.symbol || code;
}

async function doRegister() {
  const name     = S.authName.trim();
  const business = (S.authBiz || '').trim();
  const email    = S.authEmail.trim().toLowerCase();
  const pwd      = S.authPwd;
  if (!email || !pwd || !name) {
    showToast(t('fillAll') || 'Remplissez tous les champs', 'error');
    return;
  }
  if (!EMAIL_RE.test(email)) {
    showToast('E-mail invalide — format attendu : nom@exemple.com', 'error');
    return;
  }
  // Création directe du compte — pas d'étape de vérification email.
  // L'email est un simple identifiant (comme un username) ; validation format uniquement.
  try {
    const data = await api('POST', '/api/auth/register', {
      email,
      password:      pwd,
      name,
      business_name: business || name,
      country:       S.authCountry,
      language:      S.authLang,
      currency:      S.authCurrency,
      profile:       S.authProfile,
      tax_rate:      parseFloat(S.authTax) || 0,
      email_verified: true,
    });
    const u = data.user;
    S.token = u.auth_token;
    // Mapping profile UI → businessType (driver de toute l'UI adaptative)
    const bt = S.authProfile === 'reseller' ? 'reseller' : S.authProfile === 'transformer' ? 'maker' : 'mixed';
    S.session = {
      id: u.id, name: u.name, email: u.email, business: u.business_name,
      profile:         S.authProfile,
      businessType:    bt,
      currency:        S.authCurrency,
      currency_symbol: getCurrencySymbol(S.authCurrency),
      country:         S.authCountry,
      language:        S.authLang,
      tax_rate:        parseFloat(S.authTax) || 0,
      email_verified:  true,
      email_verified_at: new Date().toISOString(),
    };
    localStorage.setItem('stockr_business_type', bt);
    saveSession({ ...S.session, token: S.token });
    // Pas de seed automatique : utilisateur commence vierge, boutons "Charger exemples" disponibles dans l'empty state
    S.articles = S.articles || [];
    S.products = S.products || [];
    S.clients  = S.clients  || [];
    S.sales    = S.sales    || [];
    try {
      _saveArticles();
      localStorage.setItem('stockr_products', JSON.stringify(S.products));
      _saveClients();
      localStorage.setItem('stockr_sales',    JSON.stringify(S.sales));
    } catch(_){}
    if (typeof logAudit === 'function') logAudit('auth', 'register', { email: u.email, bt, verified: true });
    S.authEmail = S.authPwd = S.authPwd2 = S.authName = S.authBiz = '';
    S.authStep = 1;
    // Onboarding 3 écrans pour les nouveaux comptes (une seule fois)
    if (!localStorage.getItem('baro_onboarded')) {
      S.view = 'onboarding';
      S.onboardSlide = 0;
    } else {
      S.view = 'home';
    }
    const btLabel = bt === 'reseller' ? '🏪 Revendeur' : bt === 'maker' ? '🏭 Transformateur' : '🔀 Mixte';
    showToast(`✅ Bienvenue, ${name} ! Mode ${btLabel} activé.`, 'success');
    render();
    await loadData();
  } catch(e) {
    showToast(e.message || 'Erreur lors de la création du compte', 'error');
  }
}

// Stubs pour compat avec anciens onclick localStorage/templates — ne doivent plus être appelés
async function confirmSignupVerification() { S.signupPending = null; S.view = 'home'; S.authView = 'register'; render(); }
async function resendSignupVerification()  { /* no-op : vérification email supprimée */ }
function   cancelSignupVerification()      { S.signupPending = null; S.view = 'home'; S.authView = 'register'; S.authStep = 2; render(); }

function vSignupVerify() {
  const p = S.signupPending;
  if (!p) { S.view = 'home'; S.authView = 'register'; render(); return ''; }
  const maskedEmail = p.data.email.replace(/(.{2}).*(@.*)/, '$1****$2');
  // Fallback : affiche le code en clair si EmailJS non configuré
  const emailConfigured = !!localStorage.getItem('stockr_emailjs_public');
  const showFallbackCode = !emailConfigured && p.code;
  return `
  <div class="auth-wrap">
    <div class="auth-card">
      <div class="auth-logo">${IC.baro}<span>BARO</span></div>
      <div class="auth-title">${t('x1_verifiezEmail')}</div>
      <div class="auth-sub">${t('x1_codeEnvoyeA')}<br><strong>${maskedEmail}</strong></div>

      ${showFallbackCode ? `
      <div style="margin-top:16px;padding:14px;background:linear-gradient(135deg,#FEF3C7,#FDE68A);border-radius:12px;border:2px solid #F59E0B">
        <div style="font-size:11px;color:#92400E;font-weight:700;margin-bottom:6px;text-align:center">${t('x1_emailNonConfig')}</div>
        <div style="font-size:28px;font-weight:900;letter-spacing:6px;text-align:center;font-family:monospace;color:#78350F;user-select:all;cursor:copy" onclick="navigator.clipboard.writeText('${p.code}').then(()=>showToast('Code copié','success'))">${p.code}</div>
        <div style="display:flex;gap:6px;margin-top:8px">
          <button class="btn btn-ghost" style="flex:1;font-size:11px;padding:6px" onclick="_openMailtoVerification('${p.data.email}','${p.code}')">${t('x1_ouvrirEmail')}</button>
          <button class="btn btn-primary" style="flex:1;font-size:11px;padding:6px" onclick="S.signupCodeInput='${p.code}';render()">⚡ Auto-remplir</button>
        </div>
        <div style="font-size:10px;color:#78350F;margin-top:6px;text-align:center">${t('x1_configEmailjs')}</div>
      </div>` : ''}

      <div class="form-group" style="margin-top:20px">
        <label class="form-label">${t('x1_codeVerif')}</label>
        <input class="input" id="signup-code" type="text" inputmode="numeric" maxlength="6" placeholder="000000"
          style="letter-spacing:8px;text-align:center;font-size:24px;font-weight:700;font-family:monospace"
          value="${S.signupCodeInput || ''}"
          oninput="S.signupCodeInput=this.value.replace(/\\D/g,'').slice(0,6);if(this.value.length===6)confirmSignupVerification()">
      </div>

      <button class="btn btn-primary" style="width:100%;margin-top:10px" onclick="confirmSignupVerification()">${t('x1_validerCreer')}</button>

      <div style="text-align:center;margin-top:14px;display:flex;flex-direction:column;gap:8px">
        <button class="btn-link" onclick="resendSignupVerification()" style="background:none;border:none;color:var(--accent);font-size:13px;cursor:pointer">${t('x1_renvoyerCode')}</button>
        <button class="btn-link" onclick="cancelSignupVerification()" style="background:none;border:none;color:var(--text-3);font-size:12px;cursor:pointer">${t('x1_modifierInfos')}</button>
      </div>

      <div style="margin-top:20px;padding:10px;background:var(--accent-light);border-radius:8px;font-size:11px;color:var(--text-2);text-align:center">
        🛡️ Le code expire dans 10 minutes — ne le partagez avec personne.
      </div>
    </div>
  </div>`;
}

