// ── Type d'activité : Revendeur / Transformateur / Mixte ─────
function getBusinessType() {
  return S.session?.businessType || localStorage.getItem('stockr_business_type') || 'maker';
}
function changeBusinessType(type) {
  if (!['reseller','maker','mixed'].includes(type)) return;
  if (!S.session) S.session = {};
  S.session.businessType = type;
  localStorage.setItem('stockr_business_type', type);
  _persistSession();
  const labels = { reseller:'🏪 Revendeur', maker:'🏭 Transformateur', mixed:'🔀 Mixte' };
  showToast(`Mode ${labels[type]} activé`);
  render();
}
// Helpers pour l'UI
function bt_showProducts() { const t = getBusinessType(); return t === 'maker' || t === 'mixed'; }
function bt_showStock()    { const t = getBusinessType(); return t === 'reseller' || t === 'maker' || t === 'mixed'; }

// ── PACKS / BUNDLES ───────────────────────────
function packOriginalPrice(pack) {
  if (!pack?.items?.length) return 0;
  return pack.items.reduce((s, it) => {
    const p = S.products.find(pp => pp.id === it.productId);
    return p ? s + (p.price || 0) * (it.qty || 1) : s;
  }, 0);
}
function packFinalPrice(pack) {
  if (!pack) return 0;
  if (pack.autoPrice) {
    const orig = packOriginalPrice(pack);
    return Math.max(0, Math.round(orig * (100 - (pack.discount||0)) / 100));
  }
  return Math.max(0, pack.price || 0);
}
function packCostPrice(pack) {
  if (!pack?.items?.length) return 0;
  return pack.items.reduce((s, it) => {
    const p = S.products.find(pp => pp.id === it.productId);
    return p ? s + (p.purchasePrice || 0) * (it.qty || 1) : s;
  }, 0);
}
function packMaxAvailable(pack) {
  if (!pack?.items?.length) return 0;
  let min = Infinity;
  for (const it of pack.items) {
    const p = S.products.find(pp => pp.id === it.productId);
    if (!p) return 0;
    const avail = productMaxMake(p);
    const canForThis = Math.floor(avail / (it.qty || 1));
    if (canForThis < min) min = canForThis;
  }
  return min === Infinity ? 0 : min;
}
function packSavings(pack) {
  const orig = packOriginalPrice(pack);
  const fin  = packFinalPrice(pack);
  return Math.max(0, orig - fin);
}
function persistPacks() { localStorage.setItem('stockr_packs', JSON.stringify(S.packs||[])); }
// Pour un revendeur, les ventes se font directement sur les articles
function bt_sellableItems() {
  const t = getBusinessType();
  const bc = S.boutiqueConfig || {};
  const boutiqueArticleIds = new Set(bc.articles || []);
  const boutiqueProductIds = new Set(bc.products || []);
  const boutiquePackIds    = new Set(bc.packs    || []);

  // Packs (uniquement si produits visibles - un pack est fait de produits)
  const packs = (bt_showProducts() && Array.isArray(S.packs)) ? S.packs
    .filter(pk => pk.active !== false && pk.items?.length)
    .map(pk => ({
      id: 'pack_' + pk.id, packId: pk.id, name: '📦 ' + pk.name,
      price: packFinalPrice(pk), purchasePrice: packCostPrice(pk),
      stock: packMaxAvailable(pk), unit: 'pack', kind: 'pack',
      inBoutique: boutiquePackIds.has(pk.id),
    })) : [];

  if (t === 'reseller') {
    // Revendeur : peut vendre
    //  1) les articles stock direct (doivent avoir prix + stock)
    //  2) les produits créés dans l'onglet Boutique (S.products)
    //  3) les packs actifs
    const arts = (Array.isArray(S.articles) ? S.articles : [])
      .filter(a => a && (a.price||0) > 0 && (a.stock||0) > 0)
      .map(a => ({
        id: 'art_' + a.id,
        articleId: a.id,
        name: a.name,
        price: a.price,
        purchasePrice: a.purchasePrice || 0,
        stock: a.stock,
        unit: a.unit || 'pce',
        kind: 'article',
        image: a.image || '',
        inBoutique: boutiqueArticleIds.has(a.id),
      }));
    const prods = (Array.isArray(S.products) ? S.products : [])
      .filter(p => p && (p.price||0) > 0)
      .map(p => ({
        id: 'prod_' + p.id,
        productId: p.id,
        name: '🏪 ' + p.name,
        price: p.price,
        purchasePrice: p.purchasePrice || 0,
        stock: (typeof productMaxMake === 'function') ? productMaxMake(p) : (p.stock||0),
        unit: p.unit || 'u',
        kind: 'product',
        image: p.image || '',
        inBoutique: boutiqueProductIds.has(p.id),
      }));
    return [...packs, ...prods, ...arts];
  }
  // maker / mixed : produits classiques (+ articles si mixte) + packs
  const prods = S.products.map(p => ({
    id:'prod_'+p.id, productId:p.id, name:p.name, price:p.price,
    purchasePrice:p.purchasePrice||0, stock:productMaxMake(p), unit:'u', kind:'product',
    inBoutique: boutiqueProductIds.has(p.id),
  }));
  if (t === 'mixed') {
    const arts = S.articles.filter(a => (a.price||0) > 0 && (a.stock||0) > 0).map(a => ({
      id:'art_'+a.id, articleId:a.id, name:a.name+' (stock direct)', price:a.price,
      purchasePrice:a.purchasePrice||0, stock:a.stock, unit:a.unit, kind:'article',
      inBoutique: boutiqueArticleIds.has(a.id),
    }));
    return [...packs, ...prods, ...arts];
  }
  return [...packs, ...prods];
}

// Envoie au client le lien/instruction de paiement pour le montant de sa vente.
function sendSalePaymentLink(provider, clientId, amount) {
  const method = (S.paymentMethods||[]).find(m => m.provider === provider && m.active);
  if (!method) { showToast('Configurez ' + provider + ' dans Paiements', 'info'); nav('payments-setup'); return; }
  const sh = _payShareable(method, amount);
  const cl = clientId ? (S.clients||[]).find(c => c.id === clientId) : null;
  const biz = S.session?.business || 'notre boutique';
  let msg;
  if (sh.link) msg = `Bonjour 👋\nMerci pour votre achat chez ${biz} ! Voici votre lien de paiement ${method.name} (${fmt(amount)} ${sym()}) :\n${sh.link}`;
  else msg = `Bonjour 👋\nMerci pour votre achat chez ${biz} ! ${sh.instruction}.${sh.ussd?`\nCode : ${sh.ussd}`:''}`;
  const phone = cl?.phone ? cl.phone.replace(/\D/g,'') : '';
  window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  S.paymentHistory = S.paymentHistory || [];
  S.paymentHistory.unshift({ id: Date.now(), provider, amount, description: 'Lien après vente', date: new Date().toISOString(), status: 'requested', clientName: cl?.name || null });
  localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
  const b = document.getElementById('receipt-banner'); if (b) b.remove();
  showToast('Lien de paiement envoyé sur WhatsApp', 'success');
}
// ── Bannière reçu post-vente ──────────────────
function showReceiptBanner(sales, total, payInfo) {
  const existing = document.getElementById('receipt-banner');
  if (existing) existing.remove();
  const sym = S.session?.currency_symbol || 'FCFA';
  const el = document.createElement('div');
  el.id = 'receipt-banner';
  el.className = 'receipt-banner';
  // Stocker les ventes dans un attribut data sérialisé
  const sid = 'rb_' + Date.now();
  window[sid] = sales;
  // Lien de paiement proposé si vente non-cash via une méthode partageable + client
  const _shareableProv = ['wave','paypal','orange','moov','mtn'];
  const _payLinkBtn = (payInfo && payInfo.provider && _shareableProv.includes(payInfo.provider)
      && (S.paymentMethods||[]).some(m => m.provider === payInfo.provider && m.active))
    ? `<button class="rb-btn rb-pay" onclick="sendSalePaymentLink('${payInfo.provider}',${payInfo.clientId||'null'},${Math.round(total)})">${IC.dollar} Lien paiement</button>`
    : '';
  el.innerHTML = `
    <div class="receipt-banner-left">
      <div class="receipt-banner-title">${t('saleConfirmed')}</div>
      <div class="receipt-banner-total">${fmt(total)} ${sym}</div>
    </div>
    <div class="receipt-banner-btns">
      ${_payLinkBtn}
      <button class="rb-btn rb-pdf" onclick="generateInvoicePDF(window['${sid}']);document.getElementById('receipt-banner').remove()">
        ${IC.pdf} PDF
      </button>
      <button class="rb-btn rb-wa" onclick="shareViaWhatsApp(window['${sid}']);document.getElementById('receipt-banner').remove()">
        ${IC.whatsapp} WhatsApp
      </button>
      <button class="rb-close" onclick="document.getElementById('receipt-banner').remove()">✕</button>
    </div>`;
  document.body.appendChild(el);
  setTimeout(() => { const b = document.getElementById('receipt-banner'); if (b) b.remove(); }, 12000);
}

// ── Navigate ──────────────────────────────────
// ── Pull-to-refresh : tirer vers le bas en haut de page → recharge les données ──
function __initPullToRefresh() {
  const viewEl = document.getElementById('view');
  if (!viewEl || viewEl.__ptrInit) return;
  viewEl.__ptrInit = true;

  // Indicateur visuel injecté une fois dans #app
  let ind = document.getElementById('ptr-indicator');
  if (!ind) {
    ind = document.createElement('div');
    ind.id = 'ptr-indicator';
    ind.innerHTML = '<div class="ptr-spinner"></div>';
    document.getElementById('app').prepend(ind);
  }

  let startY = 0, pulling = false, dist = 0, refreshing = false;
  const THRESHOLD = 72;

  viewEl.addEventListener('touchstart', (e) => {
    if (refreshing || viewEl.scrollTop > 0) { pulling = false; return; }
    startY = e.touches[0].clientY;
    pulling = true;
    dist = 0;
  }, { passive: true });

  viewEl.addEventListener('touchmove', (e) => {
    if (!pulling || refreshing) return;
    dist = e.touches[0].clientY - startY;
    if (dist <= 0 || viewEl.scrollTop > 0) { ind.classList.remove('visible', 'armed'); return; }
    const damped = Math.min(THRESHOLD * 1.4, dist * 0.45); // résistance élastique
    ind.style.setProperty('--ptr-pull', damped + 'px');
    ind.classList.add('visible');
    ind.classList.toggle('armed', damped >= THRESHOLD * 0.92);
  }, { passive: true });

  viewEl.addEventListener('touchend', async () => {
    if (!pulling || refreshing) return;
    pulling = false;
    const armed = ind.classList.contains('armed');
    if (!armed) { ind.classList.remove('visible', 'armed'); return; }
    refreshing = true;
    haptic('tap');
    ind.classList.add('refreshing');
    try {
      await loadData();
      showToast('Données actualisées', 'success');
    } catch(_) {
      showToast('Actualisation impossible — données locales conservées', '');
    }
    ind.classList.remove('visible', 'armed', 'refreshing');
    refreshing = false;
  }, { passive: true });
}

// ── Haptics : retour tactile léger (Android Chrome ; silencieux ailleurs) ──
function haptic(kind = 'tap') {
  try {
    if (!navigator.vibrate) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const patterns = { tap: 8, success: [12, 40, 18], error: [40, 60, 40], warn: 25 };
    navigator.vibrate(patterns[kind] || 8);
  } catch(_) {}
}

// Lot 146 : transitions de vue contextuelles (iOS-like)
// Onglets de la barre du bas = transition douce (fondu) ; entrer dans un
// sous-écran = glissé depuis la droite (push) ; revenir = glissé depuis la
// gauche (pop). La direction est déduite d'une pile de navigation légère.
const __TAB_VIEWS = new Set(['home','pantry','products','sales','financial','more','boutique']);
if (typeof window !== 'undefined' && !window.__navStack) window.__navStack = ['home'];
function nav(view, extra={}) {
  // Pose un timestamp pour que le filet de sécurité global sache qu'on a bien été appelé
  try { window.__navLastCallAt = Date.now(); } catch(_){}
  try { Object.assign(S, extra); } catch(_){}
  haptic('tap');
  // ── Direction contextuelle ──
  try {
    const st = window.__navStack;
    if (__TAB_VIEWS.has(view)) { window.__vtDir = 'tab'; window.__navStack = [view]; }
    else {
      const idx = st.indexOf(view);
      if (idx !== -1) { window.__vtDir = 'back'; window.__navStack = st.slice(0, idx + 1); }
      else { window.__vtDir = 'fwd'; st.push(view); if (st.length > 20) st.shift(); }
    }
  } catch(_) { window.__vtDir = 'tab'; }
  S.view = view;
  try {
    const vEl = document.getElementById('view');
    if (vEl) vEl.scrollTop = 0;
  } catch(_){}
  render();
}
// Applique une transition one-shot sur #view, INDÉPENDANTE des re-renders
// (rien ne la retire sauf sa propre fin) → ne casse jamais l'anti-blink.
function __applyViewTransition(viewEl) {
  if (!viewEl) return;
  // Réglage « Réduire les animations » (Apparence) → aucune transition de vue
  if (document.documentElement.getAttribute('data-reduce-motion') === '1') { window.__vtDir = null; return; }
  // Lot 150 : si une photo va se morpher (shared-element), la transition de vue
  // s'efface — le morph porte le mouvement (comme iOS).
  if (window.__sharedPending && (window.__vtDir === 'fwd' || !window.__vtDir)) { window.__vtDir = null; return; }
  const dir = window.__vtDir || 'tab';
  window.__vtDir = null; // consommé
  const cls = dir === 'fwd' ? 'vt-fwd' : dir === 'back' ? 'vt-back' : 'vt-tab';
  viewEl.classList.remove('vt-fwd', 'vt-back', 'vt-tab');
  document.body.classList.add('vt-active'); // fige le stagger des cartes pendant le glissé
  // force un reflow pour redémarrer proprement si transitions rapprochées
  void viewEl.offsetWidth;
  viewEl.classList.add(cls);
  const done = () => {
    viewEl.classList.remove('vt-fwd', 'vt-back', 'vt-tab');
    document.body.classList.remove('vt-active');
    viewEl.removeEventListener('animationend', done);
  };
  viewEl.addEventListener('animationend', done);
  clearTimeout(window.__vtTimer);
  window.__vtTimer = setTimeout(done, 520); // filet de sécurité
}

// ── Lot 149 : Swipe-pour-fermer les feuilles (geste iOS) ──
// Tirez la feuille vers le bas pour la fermer ; ressort si trop court.
// Délégation globale : marche pour TOUTES les feuilles .qs-sheet, présentes
// ou futures. Ne se déclenche que si la feuille est en haut de son scroll
// (sinon on laisse le contenu défiler normalement).
(function initSheetSwipe() {
  if (typeof document === 'undefined' || window.__sheetSwipeInit) return;
  window.__sheetSwipeInit = true;
  let sheet = null, overlay = null, startY = 0, dy = 0, active = false;
  const px = e => (e.touches && e.touches[0] ? e.touches[0].clientY : (e.changedTouches && e.changedTouches[0] ? e.changedTouches[0].clientY : e.clientY));
  const onStart = (e) => {
    const t = e.target;
    if (!t || !t.closest) return;
    const sh = t.closest('.qs-sheet');
    if (!sh || sh.scrollTop > 0) return;
    // Ne pas capturer un geste qui commence sur un champ de saisie / curseur
    if (t.closest('input,textarea,select,[contenteditable="true"]')) return;
    sheet = sh; overlay = sh.closest('.qs-overlay') || sh.parentElement;
    startY = px(e); dy = 0; active = true;
    sheet.style.transition = 'none';
  };
  const onMove = (e) => {
    if (!active || !sheet) return;
    dy = px(e) - startY;
    if (dy <= 0) { sheet.style.transform = 'translateY(0)'; return; }
    if (sheet.scrollTop > 0) { active = false; sheet.style.transform = ''; return; }
    sheet.style.transform = 'translateY(' + dy + 'px)';
    if (overlay) overlay.style.background = 'rgba(8,9,15,' + Math.max(0.12, 0.5 - dy / 700) + ')';
    if (e.cancelable) e.preventDefault(); // empêche le scroll parent pendant le glissé
  };
  const onEnd = () => {
    if (!active || !sheet) return;
    active = false;
    const s = sheet, ov = overlay; sheet = null; overlay = null;
    s.style.transition = 'transform .3s cubic-bezier(.32,.72,0,1)';
    if (dy > 100) {
      // Seuil franchi → fermeture (déclenche le vrai handler de fermeture)
      s.style.transform = 'translateY(100%)';
      if (typeof haptic === 'function') haptic('light');
      const closeBtn = s.querySelector('.qs-x, .ck-close, .qs-close');
      setTimeout(() => {
        if (closeBtn) closeBtn.click();
        else { try { (ov && ov.remove) ? ov.remove() : (s.remove && s.remove()); } catch(_){} }
      }, 260);
    } else {
      // Ressort en place
      s.style.transform = 'translateY(0)';
      if (ov) ov.style.background = '';
    }
  };
  document.addEventListener('touchstart', onStart, { passive: true });
  document.addEventListener('touchmove', onMove, { passive: false });
  document.addEventListener('touchend', onEnd, { passive: true });
  document.addEventListener('touchcancel', onEnd, { passive: true });
})();

// ── Lot 150 : Shared-element — la photo « grandit » de la liste vers la fiche ──
// Technique FLIP : on capture la position de la photo touchée (source), et après
// le rendu de la fiche on morphe un clone jusqu'à la photo du hero (cible).
// Robuste sans RAF (reflow forcé) → marche même quand requestAnimationFrame est
// throttlé. Fallback silencieux si pas de photo (aucune animation, nav normal).
(function initSharedElement() {
  if (typeof document === 'undefined' || window.__sharedInit) return;
  window.__sharedInit = true;
  // Capture (phase capture, avant les onclick inline) : mémorise la photo source
  document.addEventListener('click', (e) => {
    const t = e.target; if (!t || !t.closest) return;
    const navEl = t.closest('[onclick]');
    if (!navEl) return;
    const oc = navEl.getAttribute('onclick') || '';
    if (!/nav\(\s*['"]detail['"]/.test(oc)) return;      // uniquement l'ouverture d'une fiche
    const img = navEl.querySelector('img');
    if (!img || !img.getBoundingClientRect().width) { window.__shared = null; return; }
    const r = img.getBoundingClientRect();
    const cs = getComputedStyle(img);
    window.__shared = { src: img.currentSrc || img.src, left: r.left, top: r.top, width: r.width, height: r.height, radius: cs.borderRadius, at: Date.now() };
    window.__sharedPending = true;
  }, true);
})();
// Exécute le morph vers la photo cible du hero de la fiche
function __runSharedMorph(viewEl) {
  const s = window.__shared;
  window.__shared = null;
  if (!s || Date.now() - s.at > 1200) { window.__sharedPending = false; return; }
  const target = viewEl && viewEl.querySelector('.sub-hero img');
  if (!target) { window.__sharedPending = false; return; }
  const to = target.getBoundingClientRect();
  if (!to.width) { window.__sharedPending = false; return; }
  const clone = document.createElement('img');
  clone.src = s.src;
  clone.style.cssText = 'position:fixed;z-index:12000;margin:0;pointer-events:none;object-fit:cover;'
    + 'left:' + to.left + 'px;top:' + to.top + 'px;width:' + to.width + 'px;height:' + to.height + 'px;'
    + 'border-radius:14px;transform-origin:top left;box-shadow:0 10px 30px -8px rgba(0,0,0,.3)';
  // Inversion : place le clone visuellement à la position source
  const sx = s.width / to.width, sy = s.height / to.height;
  const tx = s.left - to.left, ty = s.top - to.top;
  clone.style.transform = 'translate(' + tx + 'px,' + ty + 'px) scale(' + sx + ',' + sy + ')';
  target.style.opacity = '0';
  document.body.appendChild(clone);
  void clone.offsetWidth; // commit du reflow → point de départ posé
  clone.style.transition = 'transform .44s cubic-bezier(.32,.72,0,1), border-radius .44s';
  clone.style.transform = 'translate(0,0) scale(1,1)';
  clone.style.borderRadius = (s.radius && s.radius !== '0px') ? s.radius : '14px';
  let done = false;
  const finish = () => { if (done) return; done = true; try { target.style.opacity = ''; clone.remove(); } catch(_){} };
  clone.addEventListener('transitionend', finish, { once: true });
  setTimeout(finish, 640); // filet de sécurité
  window.__sharedPending = false;
}

// Expose immédiatement pour que les onclick inline fonctionnent dès le premier clic,
// même avant DOMContentLoaded.
if (typeof window !== 'undefined') window.nav = nav;

// ── Filet de sécurité GLOBAL : click delegation ───────────────────
// Parfois un onclick inline peut échouer silencieusement (script async qui n'a pas
// fini de parser, erreur dans une autre fonction qui casse la pile, etc.). On met
// un listener de délégation sur document qui ré-exécute l'action nav('xxx') en
// dernier recours, pour que les boutons Accueil / Retour / nav bar fonctionnent
// TOUJOURS, quel que soit l'état de l'app.
if (typeof document !== 'undefined') {
  document.addEventListener('click', function(ev) {
    const el = ev.target.closest && ev.target.closest('[onclick]');
    if (!el) return;
    const code = el.getAttribute('onclick') || '';
    // Détection d'un nav('xxx') ou nav("xxx") dans l'onclick
    const m = code.match(/\bnav\(\s*['"]([a-zA-Z0-9_-]+)['"]/);
    if (!m) return;
    // Si on est arrivés ici, le click s'est propagé SANS que nav() ait été appelé :
    // l'onclick inline a échoué. On exécute en secours.
    // NB : le navigateur exécute d'abord l'onclick inline ; si celui-ci a réussi,
    // un flag __navCalled est posé par nav() — on l'utilise pour ne pas re-render.
    try {
      if (typeof window.nav === 'function') {
        // Petit défer pour laisser l'onclick inline tenter d'abord
        setTimeout(() => {
          if (!window.__navLastCallAt || (Date.now() - window.__navLastCallAt) > 100) {
            window.nav(m[1]);
          }
        }, 0);
      }
    } catch(e) { console.warn('[BARO] nav-safety', e); }
  }, false);
}

// ── Render ────────────────────────────────────
let __lastView = null;
function __markViewTransition(newView) {
  // Only trigger CSS animations when the view actually changes.
  // Prevents "blink" on every state update inside the same view.
  const changed = newView !== __lastView;
  __lastView = newView;
  const body = document.body;
  if (!body) return changed;
  if (changed) {
    body.classList.add('view-entering');
    // Fenêtre = plus longue que la fin du stagger le plus tardif (delai max ~0.48s
    // + duree 0.3s ≈ 0.78s) pour que TOUTES les cartes terminent leur fondu avant
    // le retrait de la classe → plus de "snap"/blink des cartes du bas.
    // Aucune re-render normale n'intervient pendant ce laps (render() est debounce
    // RAF, le count-up a son propre RAF), donc l'entree joue une seule fois.
    clearTimeout(window.__viewEnterTimer);
    window.__viewEnterTimer = setTimeout(() => {
      body.classList.remove('view-entering');
      window.__viewEnterTimer = null;
    }, 850);
  } else {
    // Re-render dans la MÊME vue (interaction, maj d'état) : on retire la classe
    // pour que le contenu reste STATIQUE (pas de ré-animation/clignotement à
    // chaque clic). Les règles body:not(.view-entering) figent alors les cartes.
    body.classList.remove('view-entering');
    clearTimeout(window.__viewEnterTimer);
    window.__viewEnterTimer = null;
  }
  return changed;
}

// ── Anti-blink : capture/restaure focus, selection, scroll avant innerHTML ─
function __snapshotUIState() {
  const ae = document.activeElement;
  let focus = null;
  if (ae && ae.id && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.tagName === 'SELECT')) {
    focus = {
      id: ae.id,
      selectionStart: typeof ae.selectionStart === 'number' ? ae.selectionStart : null,
      selectionEnd: typeof ae.selectionEnd === 'number' ? ae.selectionEnd : null,
      scrollTop: ae.scrollTop,
    };
  }
  const vEl = document.getElementById('view');
  const scrollY = window.scrollY || 0;
  const vScroll = vEl ? vEl.scrollTop : 0;
  return { focus, scrollY, vScroll };
}
function __restoreUIState(snap) {
  if (!snap) return;
  requestAnimationFrame(() => {
    if (snap.focus) {
      const el = document.getElementById(snap.focus.id);
      if (el) {
        try { el.focus({ preventScroll: true }); } catch(e) { try { el.focus(); } catch(_){} }
        if (snap.focus.selectionStart !== null && typeof el.setSelectionRange === 'function') {
          try { el.setSelectionRange(snap.focus.selectionStart, snap.focus.selectionEnd); } catch(e){}
        }
      }
    }
    // Ne PAS restaurer scroll si on change de view
  });
}

// ── render() avec débounce RAF + préservation focus ──
let __renderPending = false;
let __renderRAF = null;
function render() {
  // Batch multiples renders dans la même frame
  if (__renderPending) return;
  __renderPending = true;
  if (__renderRAF) cancelAnimationFrame(__renderRAF);
  __renderRAF = requestAnimationFrame(() => {
    __renderPending = false;
    __renderRAF = null;
    _doRender();
  });
}

// ── Count-up : anime les éléments [data-count] de 0 → valeur ──
function __animateCountUps(root) {
  try {
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    (root || document).querySelectorAll('[data-count]').forEach(el => {
      const target = parseFloat(el.getAttribute('data-count'));
      if (!isFinite(target) || target <= 0) return;
      const suffix = el.getAttribute('data-count-suffix') || '';
      const dur = Math.min(900, 400 + Math.log10(target + 1) * 120);
      const start = performance.now();
      const step = (now) => {
        const p = Math.min(1, (now - start) / dur);
        const eased = 1 - Math.pow(1 - p, 3); // ease-out cubic
        el.textContent = fmt(Math.round(target * eased)) + suffix;
        if (p < 1 && el.isConnected) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    });
  } catch(_) {}
}

function _doRender() {
  const viewEl = $('view');
  const navEl  = $('nav');
  const snap = __snapshotUIState();
  const sameView = __lastView === (S.view || 'home') || (!S.session && __lastView === '__auth');

  // 2FA en attente → écran vérification
  if (S.twoFAPending && S.view === '2fa-verify') {
    navEl.style.display = 'none';
    __markViewTransition('2fa-verify');
    viewEl.innerHTML = v2FAVerify();
    if (!sameView) viewEl.scrollTop = 0;
    __restoreUIState(snap);
    return;
  }

  // Pas de session → écran auth
  if (!S.session) {
    navEl.style.display = 'none';
    __markViewTransition('__auth');
    viewEl.innerHTML = vAuth();
    if (!sameView) viewEl.scrollTop = 0;
    __restoreUIState(snap);
    return;
  }

  // Verrou PIN de démarrage : session valide mais app pas encore déverrouillée
  if (localStorage.getItem('stockr_app_pin') && !S.pinUnlocked) {
    navEl.style.display = 'none';
    __markViewTransition('__pinlock');
    viewEl.innerHTML = vPinLock();
    if (!sameView) viewEl.scrollTop = 0;
    return;
  }

  // Redirect si onglet masqué par businessType
  if (S.view === 'products' && !bt_showProducts()) S.view = 'home';
  if (S.view === 'pantry'   && !bt_showStock())    S.view = 'home';
  // Fonction mise en retrait pour le lancement → jamais atteignable, même en lien direct
  if (_isHidden(S.view)) S.view = 'more';

  const map = {
    home: vHome, pantry: vPantry, products: vProducts,
    sales: vSales, financial: vFinancial,
    detail: vDetail, add: vAdd, 'bulk-add': vBulkAdd, 'bulk-photos': vBulkPhotos, 'add-product': vAddProduct,
    'edit-product': vEditProduct, settings: vSettings, 'metier-guide': vMetierGuide, 'multi-store': vMultiStore, 'ai-chat': vAiChat, documents: vDocuments, 'devis-form': vDevisForm,
    peremptions: vExpiry,
    reassort: vReorder,
    caisse: vCashClose,
    credits: vCredits, 'credit-add': vCreditForm,
    today: vToday,
    sova: vSova, spectra: vSpectraEnhanced, clients: vClients, 'add-client': vAddClient,
    'client-detail': vClientDetail, notifications: vNotifications,
    catalog: vCatalog, suppliers: vSuppliers,
    'add-supplier': vAddSupplier, 'supplier-detail': vSupplierDetail,
    'stock-history': vStockHistory, 'purchase-orders': vPurchaseOrdersEnhanced,
    'add-order': vAddOrder, pricing: vPricing, subscription: vSubscription, 'billing-setup': vBillingSetup,
    // ── Nouvelles vues v2 ──
    more: vMore, boutique: vBoutique, marketing: vMarketing,
    'social-media': vSocialMedia, 'social-setup': vSocialSetup, 'payments-setup': vPayments,
    integrations: vIntegrations,
    'delivery-setup': vDeliverySetup,
    'whatsapp-setup': vWhatsAppSetup, 'whatsapp-file': vWhatsappFile, 'automatisations': vAutomatisations, 'automatisation-edit': vAutomatisationEdit,
    'whatsapp-broadcast': vWhatsappBroadcast,
    'sms-setup': vSmsSetup,
    'sms-broadcast': vSmsBroadcast,
    'email-broadcast': vEmailBroadcast,
    'ecommerce-setup': vEcommerceSetup,
    'sheets-setup': vSheetsSetup,
    'pos-setup': vPosSetup,
    'compta-setup': vComptaSetup,
    'promo-form': vPromoForm, 'promo-detail': vPromoDetail,
    'banner-form': vBannerForm, 'popup-form': vPopupForm,
    'review-form': vReviewForm, 'tracking-form': vTrackingForm,
    'boutique-editor': vBoutiqueEditor,
    'boutique-appearance': vBoutiqueAppearance,
    'boutique-domain': vBoutiqueDomain,
    'boutique-pixels': vBoutiquePixels,
    'boutique-code': vBoutiqueCode,
    'boutique-seo': vBoutiqueSEO,
    'boutique-analytics': vBoutiqueAnalytics,
    'boutique-hours': vBoutiqueHours,
    'boutique-policies': vBoutiquePolicies,
    'boutique-faq': vBoutiqueFAQ,
    'api-settings': vApiSettings,
    'loyalty': () => { S.marketingTab = 'loyalty'; S.view = 'marketing'; return vMarketing(); },
    'boutique-orders': () => { S.view = 'boutique'; return vBoutique(); },
    'pack-form': vPackForm,
    'exports': vExports,
    'currency-convert': vCurrencyConvert,
    'previsions': vPrevisions,
    'radar-clients': vRadarClients,
    'reassort-auto': vReassortAuto,
    // ── BATCH 5 : ${t('x_equipe2')}, Audit, Apparence, Sécurité, 2FA ──
    'team':             vTeam,
    'add-team-member':  vAddTeamMember,
    'audit-log':        vAuditLog,
    'appearance':       vAppearance,
    'security':         vSecurity,
    'spectra-ai-setup': vSpectraAISetup,
    'oauth-setup': vOAuthSetup,
    'notifications-setup': vNotificationsSetup,
    'video-library': vVideoLibrary,
    'onboarding': vOnboarding,
    'setup-wizard': vSetupWizard,
    'creator': vCreator,
  };
  const viewChanged = __markViewTransition(S.view);
  const prevScroll = viewEl.scrollTop;
  try {
    viewEl.innerHTML = (map[S.view] || vHome)();
  } catch(e) {
    console.error('[BARO] Crash dans la vue "' + S.view + '":', e);
    const __viewErr = String(e && e.message || e);
    S.view = 'home';
    try {
      viewEl.innerHTML = vHome();
    } catch(e2) {
      console.error('[BARO] vHome a aussi crashé:', e2);
      const __homeErr = String(e2 && e2.message || e2);
      const __stack = (e2 && e2.stack) ? String(e2.stack).split('\n').slice(0,3).join(' | ') : '';
      viewEl.innerHTML = `
        <div class="container" style="padding:32px 20px;text-align:center;color:var(--text)">
          <div style="font-size:18px;font-weight:800;margin-bottom:10px">Erreur d'affichage</div>
          <div style="font-size:13px;color:var(--text-3);margin-bottom:14px;line-height:1.5">${t('x4_pageNonAffichee')}<br>${t('x4_reessaieReinit')}</div>
          <details style="text-align:left;background:var(--card);border:1px solid var(--border);border-radius:10px;padding:10px 12px;margin:0 auto 16px;max-width:440px;font-size:11px;color:var(--text-3)">
            <summary style="cursor:pointer;font-weight:700;color:var(--text);margin-bottom:6px">${t('x4_detailsTech')}</summary>
            <div style="margin-top:8px"><b>Vue :</b> ${String(__viewErr).replace(/[<>&]/g,'')}</div>
            <div style="margin-top:4px"><b>Home :</b> ${String(__homeErr).replace(/[<>&]/g,'')}</div>
            ${__stack ? `<div style="margin-top:4px;font-family:monospace;font-size:10px;opacity:.7">${__stack.replace(/[<>&]/g,'')}</div>` : ''}
          </details>
          <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
            <button class="btn btn-primary" onclick="location.reload()">Recharger</button>
            <button class="btn btn-secondary" onclick="if(confirm('Réinitialiser la session locale ?')){localStorage.removeItem('baro_session');localStorage.removeItem('stockr_session');location.reload();}">Reset session</button>
          </div>
        </div>`;
    }
  }
  // Conserve le scroll si on re-render la MÊME view (évite le "blink" de remontée)
  if (viewChanged) {
    if (!S.globalSearch) viewEl.scrollTop = 0;
    // Lot 146 : transition contextuelle uniquement au vrai changement de vue
    try { __applyViewTransition(viewEl); } catch(_){}
    // Lot 150 : shared-element (photo liste → fiche) prime sur la transition de vue
    if (window.__sharedPending && S.view === 'detail') { try { __runSharedMorph(viewEl); } catch(_){ window.__sharedPending = false; } }
    else if (window.__sharedPending) { window.__sharedPending = false; window.__shared = null; }
  } else {
    viewEl.scrollTop = prevScroll;
  }

  if (S.view === 'financial') requestAnimationFrame(() => { renderRevenueChart(); renderProfitChart(); });
  if (S.view === 'boutique-editor') requestAnimationFrame(() => { try { _refreshBoutiqueLivePreview(); } catch(_){} });

  // Count-up des chiffres clés à l'entrée d'une vue (pas sur les re-renders)
  if (viewChanged) __animateCountUps(viewEl);

  // Restore focus (capture précédente)
  __restoreUIState(snap);
  // Backup : focus spécifique global search
  if (S.view === 'home' && S.globalSearch && !snap.focus) {
    const gs = $('global-search');
    if (gs) { gs.focus({ preventScroll: true }); gs.setSelectionRange(gs.value.length, gs.value.length); }
  }

  const hideNav = ['detail','add','add-product','edit-product','pack-form','add-client','client-detail','notifications','catalog','add-supplier','supplier-detail','stock-history','purchase-orders','add-order','pricing','subscription','billing-setup','boutique','boutique-editor','boutique-appearance','boutique-domain','boutique-pixels','boutique-code','boutique-seo','boutique-analytics','boutique-hours','boutique-policies','boutique-faq','bulk-add','bulk-photos','marketing','social-media','social-setup','payments-setup','integrations','delivery-setup','whatsapp-setup','whatsapp-file','automatisations','automatisation-edit','whatsapp-broadcast','sms-setup','sms-broadcast','email-broadcast','ecommerce-setup','sheets-setup','pos-setup','compta-setup','api-settings','spectra','clients','exports','team','add-team-member','audit-log','appearance','security','2fa-verify','onboarding','setup-wizard','creator'].includes(S.view);
  navEl.style.display = hideNav ? 'none' : '';
  if (!hideNav) navEl.innerHTML = renderNav();
}

function renderNav() {
  const bt = getBusinessType();
  const stockLbl = bt === 'reseller' ? 'Boutique' : bt === 'maker' ? t('zz_navMatieres') : t('stock');
  const tabs = [
    { id:'home',      icon:IC.home,    label:t('home')     },
    bt_showStock() ? { id:'pantry', icon:IC.box, label:stockLbl } : null,
    bt_showProducts() ? { id:'products', icon:IC.tag, label:t('products') } : null,
    { id:'sales',     icon:IC.dollar,  label:t('sales')    },
    { id:'financial', icon:IC.bar,     label:t('bilan')    },
    { id:'more',      icon:IC.grid,    label:t('more')||'Plus' },
  ].filter(Boolean);
  return tabs.map(tb => `
    <button class="nav-tab ${S.view===tb.id?'active':''}" onclick="nav('${tb.id}')">
      ${tb.icon}
      <span class="nav-label">${tb.label}</span>
    </button>`).join('');
}

// ── ONBOARDING — 3 écrans de bienvenue (nouveaux comptes) ──
function vOnboarding() {
  const slide = S.onboardSlide || 0;
  const bt = getBusinessType();
  const slides = [
    {
      icon: '👋',
      accent: '#7C73FF',
      title: `Bienvenue, ${(S.session?.name || '').split(' ')[0] || 'toi'} !`,
      text: t('v_onbReunit'),
      visual: `
        <div class="ob-visual-row">
          <div class="ob-mini-card" style="animation-delay:.1s"><span style="font-size:20px">📦</span><span>Stock</span></div>
          <div class="ob-mini-card" style="animation-delay:.22s"><span style="font-size:20px">💰</span><span>${t('zy_ventes')}</span></div>
          <div class="ob-mini-card" style="animation-delay:.34s"><span style="font-size:20px">👥</span><span>${t('zy_clients')}</span></div>
        </div>`,
    },
    {
      icon: '✨',
      accent: '#c9a96e',
      title: 'Deux agents IA travaillent pour toi',
      text: 'SOVA surveille ton stock et prédit les ruptures avant qu\'elles arrivent. Spectra compte tes produits avec la caméra de ton téléphone.',
      visual: `
        <div class="ob-visual-col">
          <div class="ob-agent-pill" style="animation-delay:.12s;border-color:rgba(201,169,110,.4)"><span style="color:#c9a96e;font-weight:800">SOVA</span><span>${t('x4_previsionsAlertes')}</span></div>
          <div class="ob-agent-pill" style="animation-delay:.26s;border-color:rgba(167,139,250,.4)"><span style="color:#a78bfa;font-weight:800">Spectra</span><span>${t('x4_scanCamera')}</span></div>
        </div>`,
    },
    {
      icon: '🚀',
      accent: '#34d399',
      title: 'Démarre en 30 secondes',
      text: bt === 'reseller'
        ? 'Ajoute ton premier produit à revendre, ou explore l\'app avec des exemples prêts à l\'emploi.'
        : 'Ajoute ta première matière première, ou explore l\'app avec des exemples prêts à l\'emploi.',
      visual: `
        <div class="ob-visual-col">
          <button class="btn btn-primary" style="animation:fadeUp .4s var(--ease-out) .15s both" onclick="finishOnboarding('wizard')">⚡ Configurer ma boutique</button>
          <button class="btn btn-ghost" style="animation:fadeUp .4s var(--ease-out) .28s both" onclick="finishOnboarding('demo')">${t('x4_explorerExemples')}</button>
        </div>`,
    },
  ];
  const s = slides[slide];
  return `
  <div class="ob-wrap" ontouchstart="window.__obX=event.touches[0].clientX" ontouchend="(function(x){if(window.__obX==null)return;const d=x-window.__obX;window.__obX=null;if(d<-50)onboardNext(true);else if(d>50&&S.onboardSlide>0){S.onboardSlide--;haptic('tap');render();}})(event.changedTouches[0].clientX)">
    <button class="ob-skip" onclick="finishOnboarding()">Passer</button>
    <div class="ob-body">
      <div class="ob-icon" style="--ob-accent:${s.accent}">${s.icon}</div>
      <div class="ob-title">${s.title}</div>
      <div class="ob-text">${s.text}</div>
      ${s.visual}
    </div>
    <div class="ob-footer">
      <div class="ob-dots">
        ${slides.map((_, i) => `<span class="ob-dot ${i===slide?'active':''}" onclick="S.onboardSlide=${i};render()"></span>`).join('')}
      </div>
      ${slide < slides.length - 1
        ? `<button class="btn btn-primary ob-next" onclick="onboardNext()">${t('next')}</button>`
        : `<button class="btn btn-primary ob-next" onclick="finishOnboarding()">C'est parti !</button>`}
    </div>
  </div>`;
}

function onboardNext(fromSwipe) {
  if ((S.onboardSlide || 0) < 2) {
    S.onboardSlide = (S.onboardSlide || 0) + 1;
    haptic('tap');
    render();
  } else if (!fromSwipe) {
    finishOnboarding();
  }
}

function finishOnboarding(action) {
  try { localStorage.setItem('baro_onboarded', '1'); } catch(_) {}
  haptic('success');
  if (action === 'demo') {
    loadDemoData();
    S.view = 'home';
  } else if (action === 'add') {
    S.view = 'add';
  } else if (action === 'wizard') {
    S.view = 'setup-wizard';
  } else {
    S.view = 'home';
  }
  render();
}

// ══════════════════════════════════════════════════════════════
// ASSISTANT DE PREMIER DÉMARRAGE — wizard de configuration réel
// ══════════════════════════════════════════════════════════════
function _wizard() {
  if (!S.wizard) S.wizard = {
    step: 0,
    type: getBusinessType() || 'reseller',
    biz: S.session?.business || '',
    city: S.session?.city || '',
    prod: { name:'', price:'', cost:'', stock:'' },
    wa: (S.integrationsConfig||[]).find(c=>c.id==='whatsapp-business')?.detail?.phone || '',
  };
  return S.wizard;
}
function vSetupWizard() {
  const w = _wizard();
  const steps = ['Activité','Boutique','1er produit','WhatsApp','Prêt'];
  const total = steps.length;
  const pct = Math.round((w.step) / (total - 1) * 100);
  const isMaker = w.type === 'maker';
  let body = '';
  if (w.step === 0) {
    const choices = [
      ['reseller','🏪',t('zw_mRevendeur'),t('x_wizRev')],
      ['maker','🏭',t('zw_mFabricant'),t('v_wizFabricant')],
      ['mixed','🔀',t('v_wizLesDeux'),t('v_wizLesDeuxSub')],
    ];
    body = `
      <div class="wiz-h1">${t('w9_quelMetier')}</div>
      <div class="wiz-sub">${t('v_wizAdapte')}</div>
      <div class="wiz-choices">
        ${choices.map(([id,ic,ti,de]) => `
          <button class="wiz-choice ${w.type===id?'sel':''}" onclick="wizardSetType('${id}')">
            <span class="wiz-choice-ic">${ic}</span>
            <span class="wiz-choice-txt"><span class="wiz-choice-t">${ti}</span><span class="wiz-choice-d">${de}</span></span>
            <span class="wiz-choice-check">${w.type===id?'✓':''}</span>
          </button>`).join('')}
      </div>
      <div style="font-size:11.5px;color:var(--text-3);text-align:center;line-height:1.5;margin:2px 4px 0">${t('y1_surtoutServices').replace('{0}','<strong>'+t('y1_services')+'</strong>').replace('{1}','<strong>'+t('y1_prestation')+'</strong>')}</div>
      <button class="btn btn-primary wiz-cta" onclick="wizardNext()">Continuer</button>`;
  } else if (w.step === 1) {
    body = `
      <div class="wiz-h1">${t('w9_votreBoutique')}</div>
      <div class="wiz-sub">${t('x4_apparaitRecus')}</div>
      <label class="wiz-label">${t('w9_nomCommerce')}</label>
      <input id="wiz-biz" class="input" value="${(w.biz||'').replace(/"/g,'&quot;')}" placeholder="Ex : Boutique Awa">
      <label class="wiz-label">Ville</label>
      <input id="wiz-city" class="input" value="${(w.city||'').replace(/"/g,'&quot;')}" placeholder="Ex : Abidjan">
      <button class="btn btn-primary wiz-cta" onclick="wizardNext()">Continuer</button>`;
  } else if (w.step === 2) {
    const p = w.prod || {};
    body = `
      <div class="wiz-h1">${isMaker ? 'Votre première matière' : 'Votre premier produit'}</div>
      <div class="wiz-sub">Optionnel — vous pourrez en ajouter autant que vous voulez ensuite.</div>
      <label class="wiz-label">Nom</label>
      <input id="wiz-prod-name" class="input" value="${(p.name||'').replace(/"/g,'&quot;')}" placeholder="${isMaker?'Ex : Farine':'Ex : Riz 25kg'}">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
        <div><label class="wiz-label">${t('zz8_prixVente')} (${sym()})</label><input id="wiz-prod-price" class="input" type="number" inputmode="numeric" value="${p.price||''}" placeholder="15000"></div>
        <div><label class="wiz-label">${t('zz9_prixAchat')} (${sym()})</label><input id="wiz-prod-cost" class="input" type="number" inputmode="numeric" value="${p.cost||''}" placeholder="12000"></div>
      </div>
      <label class="wiz-label">${t('w9_quantiteStock')}</label>
      <input id="wiz-prod-stock" class="input" type="number" inputmode="numeric" value="${p.stock||''}" placeholder="10">
      <button class="btn btn-primary wiz-cta" onclick="wizardNext()">Continuer</button>
      <button class="btn btn-ghost wiz-skip2" onclick="wizardSkipStep()">${t('w9_ignorerEtape')}</button>`;
  } else if (w.step === 3) {
    body = `
      <div class="wiz-h1">${IC.whatsapp} WhatsApp Business</div>
      <div class="wiz-sub">Pour envoyer reçus &amp; relances et recevoir les commandes de votre boutique en ligne.</div>
      <label class="wiz-label">${t('w9_numWhatsappIntl')}</label>
      <input id="wiz-wa" class="input" value="${(w.wa||'').replace(/"/g,'&quot;')}" placeholder="+225 07 XX XX XX XX">
      <button class="btn btn-primary wiz-cta" onclick="wizardNext()">Continuer</button>
      <button class="btn btn-ghost wiz-skip2" onclick="wizardSkipStep()">Ignorer</button>`;
  } else {
    const recap = [
      ['🏪', { reseller:'Revendeur', maker:'Transformateur', mixed:'Mixte' }[w.type] || 'Activité'],
      ['🏷️', w.biz || '—'],
      w.city ? ['📍', w.city] : null,
      (w.prod && w.prod.name) ? ['📦', `${w.prod.name}${w.prod.price?` · ${fmt(parseFloat(w.prod.price)||0)} ${sym()}`:''}`] : null,
      w.wa ? [' ', `WhatsApp ${w.wa}`] : null,
    ].filter(Boolean);
    body = `
      <div class="wiz-done-ic">🎉</div>
      <div class="wiz-h1" style="text-align:center">${t('w9_toutEstPret')}</div>
      <div class="wiz-sub" style="text-align:center">Votre BARO est configuré. Vous pouvez tout modifier plus tard dans les Paramètres.</div>
      <div class="wiz-recap">
        ${recap.map(([ic,txt]) => `<div class="wiz-recap-row"><span class="wiz-recap-ic">${ic}</span><span>${String(txt).replace(/</g,'&lt;')}</span><span class="wiz-recap-ok">✓</span></div>`).join('')}
      </div>
      <button class="btn btn-primary wiz-cta" onclick="wizardFinish()">Ouvrir mon tableau de bord →</button>`;
  }
  return `
  <div class="wiz-wrap">
    <div class="wiz-top">
      ${(w.step>0 && w.step<total-1) ? `<button class="wiz-nav-btn" onclick="wizardBack()">${IC.left}</button>` : `<span style="width:36px"></span>`}
      <div class="wiz-progress"><div class="wiz-progress-bar" style="width:${pct}%"></div></div>
      ${w.step<total-1 ? `<button class="wiz-skip" onclick="wizardSkipAll()">Passer</button>` : `<span style="width:52px"></span>`}
    </div>
    <div class="wiz-steplabel">${t('u_etape').replace('{0}', Math.min(w.step+1,total)).replace('{1}', total)}</div>
    <div class="wiz-body" key="wiz-${w.step}">${body}</div>
  </div>`;
}
function wizardSetType(tp) { _wizard().type = tp; if (typeof haptic==='function') haptic('tap'); render(); }
function _wizardReadStep() {
  const w = _wizard();
  if (w.step === 1) { w.biz = ($('wiz-biz')?.value||'').trim(); w.city = ($('wiz-city')?.value||'').trim(); }
  else if (w.step === 2) { w.prod = { name:($('wiz-prod-name')?.value||'').trim(), price:($('wiz-prod-price')?.value||'').trim(), cost:($('wiz-prod-cost')?.value||'').trim(), stock:($('wiz-prod-stock')?.value||'').trim() }; }
  else if (w.step === 3) { w.wa = ($('wiz-wa')?.value||'').trim(); }
}
function wizardNext() {
  const w = _wizard();
  _wizardReadStep();
  if (w.step === 1 && !w.biz) { showToast('Indiquez le nom de votre commerce', 'error'); return; }
  if (w.step === 3) { _wizardCommit(); }
  w.step = Math.min(4, w.step + 1);
  if (typeof haptic==='function') haptic('tap');
  render();
}
function wizardSkipStep() {
  const w = _wizard();
  if (w.step === 3) { _wizardReadStep(); _wizardCommit(); }
  w.step = Math.min(4, w.step + 1);
  render();
}
function wizardBack() { const w = _wizard(); _wizardReadStep(); w.step = Math.max(0, w.step - 1); render(); }
function wizardSkipAll() { try { localStorage.setItem('baro_onboarded','1'); } catch(_){} S.wizard = null; S.view = 'home'; render(); }
function _wizardCommit() {
  const w = _wizard();
  S.session = S.session || {};
  if (['reseller','maker','mixed'].includes(w.type)) {
    S.session.businessType = w.type;
    try { localStorage.setItem('stockr_business_type', w.type); } catch(_){}
  }
  if (w.biz) S.session.business = w.biz;
  if (w.city) S.session.city = w.city;
  try { _persistSession(); } catch(_){}
  // Premier produit / article
  const p = w.prod || {};
  if (p.name) {
    const price = parseFloat(p.price)||0, cost = parseFloat(p.cost)||0, stock = parseFloat(p.stock)||0;
    const art = { id: Date.now(), name: p.name, price, purchasePrice: cost, stock, min: 0, unit: 'pce', category: '' };
    if (!Array.isArray(S.articles)) S.articles = [];
    S.articles.push(art);
    try { _saveArticles(); } catch(_){}
    try { _saveArticles(); } catch(_){}
    try { api('POST', '/api/articles/', { name: art.name, quantity: stock, unit: 'pce', price, purchase_price: cost }); } catch(_){}
  }
  // WhatsApp Business (mode rapide)
  if (w.wa) {
    if (!Array.isArray(S.integrationsConfig)) S.integrationsConfig = [];
    const tpls = (typeof WHATSAPP_DEFAULT_TEMPLATES_ === 'function') ? WHATSAPP_DEFAULT_TEMPLATES_() : [];
    const entry = { id:'whatsapp-business', name:'WhatsApp Business', connected:true, value:w.wa, date:new Date().toISOString(), detail:{ mode:'quick', phone:w.wa, signature:(w.biz||S.session?.business||''), templates: tpls } };
    const i = S.integrationsConfig.findIndex(c => c.id === 'whatsapp-business');
    if (i >= 0) S.integrationsConfig[i] = entry; else S.integrationsConfig.push(entry);
    _sauveIntegrations();
  }
  try { logActivity('setup', 'Configuration guidée terminée'); } catch(_){}
}
function wizardFinish() {
  try { localStorage.setItem('baro_onboarded','1'); } catch(_){}
  S.wizard = null;
  if (typeof haptic==='function') haptic('success');
  S.view = 'home';
  render();
  showToast('Bienvenue sur BARO 🎉', 'success');
}

// ── AUTH ──────────────────────────────────────
function vAuth() {
  const isLogin = S.authView === 'login';
  if (!isLogin && S.authStep === 2) return vAuthStep2();

  return `
  <div class="auth-wrap">
    <div class="auth-card">
      <div class="auth-logo">${IC.baro || IC.box}<span>BARO</span></div>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px">
        <button onclick="setLang('fr')" style="padding:4px 10px;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;border:1px solid ${_lang==='fr'?'var(--accent)':'var(--border)'};background:${_lang==='fr'?'var(--accent-light)':'transparent'};color:${_lang==='fr'?'var(--accent)':'var(--text-3)'}">FR</button>
        <button onclick="setLang('en')" style="padding:4px 10px;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;border:1px solid ${_lang==='en'?'var(--accent)':'var(--border)'};background:${_lang==='en'?'var(--accent-light)':'transparent'};color:${_lang==='en'?'var(--accent)':'var(--text-3)'}">EN</button>
      </div>
      <div class="auth-title">${isLogin ? t('login') : t('register')}</div>
      <div class="auth-sub">${isLogin ? t('loginSub') : t('u_etape12')}</div>

      ${!isLogin ? `
      <div class="form-group">
        <label class="form-label">${t('x1_prenomNom')}</label>
        <input class="input" id="auth-name" type="text" placeholder="ex: Fatou Diallo" autocomplete="name" value="${S.authName}" oninput="S.authName=this.value">
      </div>
      <div class="form-group">
        <label class="form-label">${t('x1_nomCommerce2')}</label>
        <input class="input" id="auth-biz" type="text" placeholder="ex: Boutique Wax de Fatou" value="${S.authBiz||''}" oninput="S.authBiz=this.value">
      </div>` : ''}

      <div class="form-group">
        <label class="form-label">${t('x1_email')}</label>
        <input class="input" id="auth-email" type="email" placeholder="ton@email.com" autocomplete="email" value="${S.authEmail}" oninput="S.authEmail=this.value">
      </div>
      <div class="form-group">
        <label class="form-label">${t('x1_motDePasse')}</label>
        <div class="pwd-wrap">
          <input class="input ${S.authShowPwd?'':'pwd-masked'}" id="auth-pwd" type="text" placeholder="••••••••" autocomplete="${isLogin?'current-password':'new-password'}" value="${S.authPwd}" oninput="S.authPwd=this.value">
          <button class="pwd-eye" onclick="toggleAuthPwd(event)" type="button">${S.authShowPwd?IC.eyeOff:IC.eye}</button>
        </div>
      </div>
      ${!isLogin ? `
      <div class="form-group">
        <label class="form-label">${t('x1_confirmerMdp')}</label>
        <div class="pwd-wrap">
          <input class="input ${S.authShowPwd?'':'pwd-masked'}" id="auth-pwd2" type="text" placeholder="••••••••" autocomplete="new-password" value="${S.authPwd2}" oninput="S.authPwd2=this.value">
        </div>
      </div>` : ''}

      <button class="btn btn-primary" style="margin-top:8px" onclick="${isLogin ? 'doLogin()' : 'authNextStep()'}">
        ${isLogin ? t('loginBtn') : t('next') + ' →'}
      </button>

      ${isLogin && window.PublicKeyCredential ? `
      <!-- Separator -->
      <div style="display:flex;align-items:center;gap:10px;margin:18px 0 12px">
        <div style="flex:1;height:1px;background:var(--border)"></div>
        <div style="font-size:11px;color:var(--text-3);font-weight:600">OU</div>
        <div style="flex:1;height:1px;background:var(--border)"></div>
      </div>

      <!-- Connexion biométrique (WebAuthn natif navigateur — 100% fonctionnel) -->
      <button class="btn" onclick="loginBiometric()" style="background:var(--card-bg);color:var(--accent);border:2px solid var(--accent);display:flex;align-items:center;justify-content:center;gap:10px;font-weight:700;padding:12px;width:100%">
        <span style="font-size:18px">👆</span>
        Connexion biométrique
      </button>
      ` : ''}
      ${isLogin ? `
      <div style="margin-top:12px;text-align:center;display:flex;align-items:center;justify-content:center;gap:6px;font-size:10px;color:var(--text-3)">
        <span>🔒</span><span>${t('x1_connexionSsl')}</span>
      </div>
      <!-- Rejoindre une équipe avec un code (vendeur) -->
      ${S.authJoinOpen ? `
      <div style="margin-top:14px;padding:14px;border:1.5px solid var(--accent);border-radius:12px;background:var(--accent-light)">
        <div style="font-weight:800;font-size:13.5px;color:var(--text-1);margin-bottom:8px">${t('y1_rejoindreEquipe')}</div>
        <input class="input" id="join-code" type="text" placeholder="Code (ex : BARO-XXXXXX)" style="text-transform:uppercase;margin-bottom:8px" value="${(S.joinCode||'').replace(/"/g,'&quot;')}" oninput="S.joinCode=this.value">
        <input class="input" id="join-name" type="text" placeholder="Votre nom (vendeur)" style="margin-bottom:10px" value="${(S.joinName||'').replace(/"/g,'&quot;')}" oninput="S.joinName=this.value">
        <button class="btn btn-primary" style="width:100%" onclick="joinTeamWithCode()">${t('x1_rejoindreBoutique')}</button>
        <div style="font-size:11px;color:var(--text-3);margin-top:6px;line-height:1.5">Le patron vous donne ce code. Vos ventes seront enregistrées à son compte, à votre nom. Nécessite une connexion internet.</div>
      </div>
      ` : `
      <button class="btn btn-ghost" style="width:100%;margin-top:10px;font-size:13px" onclick="S.authJoinOpen=true;render()">${t('x1_jeSuisVendeur')}</button>
      `}
      ` : ''}

      <div class="auth-switch">
        ${isLogin ? t('noAccount') : t('hasAccount')}
        <button onclick="S.authView='${isLogin?'register':'login'}';S.authStep=1;S.authShowPwd=false;render()">
          ${isLogin ? t('register') : t('loginBtn')}
        </button>
      </div>
    </div>
  </div>`;
}

// ── Social / biometric login : flux fonctionnels ────────────────
// Google Identity Services et Apple Sign-In doivent être chargés via index.html en prod.
// En absence : modal interne propre (pas de prompt() natif) qui crée une vraie session.
function __socialLoginCreate(provider, email, name, avatar) {
  const token = 'social_' + provider + '_' + Math.random().toString(36).slice(2, 12);
  const session = {
    token,
    id: 'u_' + provider + '_' + Date.now(),
    email: email,
    name: name,
    business: (name || t('zz_maBoutique')),
    provider,
    avatar: avatar || (provider === 'google' ? '🟢' : provider === 'apple' ? '🍎' : '👤'),
    profile:         S.authProfile || 'reseller',
    businessType:    S.authProfile === 'transformer' ? 'maker' : S.authProfile === 'reseller' ? 'reseller' : 'mixed',
    country:         S.authCountry || 'CI',
    currency:        S.authCurrency || 'XOF',
    currency_symbol: getCurrencySymbol(S.authCurrency || 'XOF'),
    language:        S.authLang || 'fr',
    tax_rate:        0,
    createdAt: Date.now(),
  };
  try {
    localStorage.setItem('stockr_session', JSON.stringify(session));
    localStorage.setItem('stockr_token', token);
    localStorage.setItem('stockr_business_type', session.businessType);
  } catch(e){}
  S.token = token;
  S.session = session;
  // Session vierge (pas de seed auto pour éviter faux produits)
  S.articles = []; S.products = []; S.clients = []; S.sales = [];
  if (typeof logAudit === 'function') logAudit('auth', 'login_success', { provider, email });
  S.view = 'home';
  render();
  try { loadData(); } catch(e){}
  showToast('✅ Connecté avec ' + provider.charAt(0).toUpperCase() + provider.slice(1) + ' — ' + name, 'success');
  // Proposer biométrie après login social
  setTimeout(() => {
    if (window.PublicKeyCredential && !localStorage.getItem('stockr_webauthn_cred')) {
      if (confirm('🔐 Activer la biométrie pour sécuriser ce compte ?\n(Empreinte / FaceID / PIN)')) {
        loginBiometric();
      }
    }
  }, 1500);
}

function __showSocialModal(provider) {
  const existing = document.getElementById('social-login-modal');
  if (existing) existing.remove();
  const brand = provider === 'google'
    ? { title: 'Connexion Google', color: '#4285F4', icon: '🟢', logo: '<svg width="20" height="20" viewBox="0 0 48 48"><path fill="#FFC107" d="M43.6 20.1H42V20H24v8h11.3c-1.6 4.7-6.1 8-11.3 8-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34.1 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20c11 0 20-8 20-20 0-1.3-.1-2.6-.4-3.9z"/><path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.6 15.1 18.9 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34.1 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z"/><path fill="#4CAF50" d="M24 44c5.2 0 9.9-2 13.5-5.3l-6.2-5.2c-2 1.5-4.6 2.5-7.3 2.5-5.2 0-9.6-3.3-11.2-8l-6.5 5C9.6 39.7 16.2 44 24 44z"/><path fill="#1976D2" d="M43.6 20.1H42V20H24v8h11.3c-.8 2.3-2.3 4.3-4.2 5.6l6.2 5.2c-.4.4 6.7-4.9 6.7-14.8 0-1.3-.1-2.6-.4-3.9z"/></svg>', placeholder: 'ex: monadresse@gmail.com' }
    : { title: 'Connexion Apple', color: '#000', icon: '🍎', logo: '<svg width="20" height="20" viewBox="0 0 170 170" fill="#fff"><path d="M150.37 130.25c-2.45 5.66-5.35 10.87-8.71 15.66-4.58 6.53-8.33 11.05-11.22 13.56-4.48 4.12-9.28 6.23-14.42 6.35-3.69 0-8.14-1.05-13.32-3.18-5.197-2.12-9.973-3.17-14.34-3.17-4.58 0-9.492 1.05-14.746 3.17-5.262 2.13-9.501 3.24-12.742 3.35-4.929.21-9.842-1.96-14.746-6.52-3.13-2.73-7.045-7.41-11.735-14.04-5.032-7.08-9.169-15.29-12.41-24.65-3.471-10.11-5.211-19.9-5.211-29.38 0-10.86 2.346-20.228 7.045-28.088 3.693-6.31 8.606-11.29 14.755-14.95 6.149-3.66 12.793-5.53 19.948-5.65 3.916 0 9.045 1.21 15.417 3.59 6.354 2.39 10.428 3.6 12.205 3.6 1.33 0 5.857-1.415 13.533-4.23 7.258-2.62 13.382-3.71 18.397-3.28 13.59 1.1 23.81 6.45 30.63 16.09-12.15 7.37-18.16 17.68-18.04 30.92.11 10.31 3.85 18.89 11.2 25.71 3.33 3.16 7.05 5.6 11.19 7.34-.9 2.61-1.85 5.11-2.86 7.51zM119.11 7.24c0 8.102-2.96 15.667-8.86 22.669-7.12 8.324-15.732 13.134-25.071 12.375a25.222 25.222 0 0 1-.188-3.07c0-7.778 3.386-16.102 9.399-22.908 3.002-3.446 6.82-6.311 11.45-8.597 4.62-2.252 8.99-3.497 13.1-3.71.12 1.083.17 2.166.17 3.24z"/></svg>', placeholder: 'ex: monadresse@icloud.com' };
  const modal = document.createElement('div');
  modal.id = 'social-login-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(6px);animation:fadeIn .2s ease';
  modal.onclick = (e) => { if (e.target === modal) modal.remove(); };
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:16px;max-width:400px;width:100%;box-shadow:0 25px 60px rgba(0,0,0,.35);animation:slideUp .25s ease;overflow:hidden">
      <div style="background:${brand.color};padding:22px 24px;color:#fff;display:flex;align-items:center;gap:12px">
        <div style="width:40px;height:40px;background:rgba(255,255,255,${provider==='apple'?0.15:0.95});border-radius:50%;display:flex;align-items:center;justify-content:center">${brand.logo}</div>
        <div style="flex:1">
          <div style="font-size:17px;font-weight:800">${brand.title}</div>
          <div style="font-size:12px;opacity:.85;margin-top:2px">${t('x1_baroIdentite')}</div>
        </div>
        <button style="width:32px;height:32px;border-radius:50%;border:none;background:rgba(255,255,255,.2);color:#fff;font-size:18px;cursor:pointer" onclick="document.getElementById('social-login-modal').remove()">×</button>
      </div>
      <div style="padding:20px 24px">
        <div class="form-group">
          <label class="form-label">Email ${provider === 'google' ? 'Google' : 'Apple'}</label>
          <input class="input" id="social-email-inp" type="email" autocomplete="email" placeholder="${brand.placeholder}" style="font-size:16px">
        </div>
        <div class="form-group">
          <label class="form-label">Nom complet</label>
          <input class="input" id="social-name-inp" type="text" autocomplete="name" placeholder="Prénom Nom" style="font-size:16px">
        </div>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="btn btn-ghost" style="flex:1" onclick="document.getElementById('social-login-modal').remove()">${t('cancel')}</button>
          <button class="btn btn-primary" style="flex:2;background:${brand.color};border-color:${brand.color}" onclick="__submitSocialLogin('${provider}')">${brand.icon} Se connecter</button>
        </div>
        <div style="text-align:center;margin-top:12px;font-size:11px;color:var(--text-3)">${t('x1_donneesLocales')}</div>
      </div>
    </div>`;
  document.body.appendChild(modal);
  setTimeout(() => document.getElementById('social-email-inp')?.focus(), 150);
}

function __submitSocialLogin(provider) {
  const emailEl = document.getElementById('social-email-inp');
  const nameEl = document.getElementById('social-name-inp');
  const email = (emailEl?.value || '').trim();
  const name  = (nameEl?.value || '').trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { emailEl?.focus(); showToast('Email invalide', 'error'); return; }
  if (name.length < 2) { nameEl?.focus(); showToast('Entrez votre nom', 'error'); return; }
  document.getElementById('social-login-modal')?.remove();
  __socialLoginCreate(provider, email, name);
}

// ── OAuth réel : Google Identity Services (accounts.google.com) ────
function _loadGoogleGSI() {
  return new Promise((resolve, reject) => {
    if (window.google?.accounts?.id) return resolve();
    const existing = document.getElementById('gsi-script');
    if (existing) { existing.addEventListener('load', resolve); existing.addEventListener('error', reject); return; }
    const script = document.createElement('script');
    script.id = 'gsi-script';
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.defer = true;
    script.onload = resolve;
    script.onerror = reject;
    document.head.appendChild(script);
  });
}

function _loadAppleJS() {
  return new Promise((resolve, reject) => {
    if (window.AppleID?.auth) return resolve();
    const existing = document.getElementById('apple-script');
    if (existing) { existing.addEventListener('load', resolve); existing.addEventListener('error', reject); return; }
    const script = document.createElement('script');
    script.id = 'apple-script';
    script.src = 'https://appleid.cdn-apple.com/appleauth/static/jsapi/appleid/1/en_US/appleid.auth.js';
    script.async = true;
    script.defer = true;
    script.onload = resolve;
    script.onerror = reject;
    document.head.appendChild(script);
  });
}

async function loginGoogle() {
  if (typeof logAudit === 'function') logAudit('auth', 'google_attempt', {});
  const clientId = (localStorage.getItem('stockr_google_client_id') || '').trim();

  // Pas de Client ID configuré → ouverture directe de accounts.google.com (page de choix de compte)
  // + modal de saisie manuelle avec auto-détection de l'email Google depuis le presse-papiers
  if (!clientId) {
    // Ouvre le vrai accounts.google.com dans un nouvel onglet pour se connecter
    try {
      window.open('https://accounts.google.com/ServiceLogin?continue=' + encodeURIComponent(window.location.href), '_blank', 'noopener');
    } catch(_){}
    showToast('🔐 Connectez-vous à Google dans l\'onglet ouvert, puis revenez ici.', 'info');
    // Affiche la modale BARO pour saisie de l'email Google une fois connecté
    setTimeout(() => __showSocialModal('google'), 600);
    return;
  }

  // Avec Client ID → vrai flow OAuth 2.0 redirection accounts.google.com
  try {
    await _loadGoogleGSI();
    if (!window.google?.accounts?.oauth2) throw new Error('GSI not loaded');

    // Flow 1 : Implicit flow (token direct) — redirige réellement sur accounts.google.com
    const tokenClient = window.google.accounts.oauth2.initTokenClient({
      client_id: clientId,
      scope: 'openid email profile',
      callback: async (tokenResponse) => {
        if (!tokenResponse.access_token) {
          showToast('Connexion Google annulée', 'error');
          return;
        }
        // Récupérer les infos utilisateur avec le token
        try {
          const userInfo = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
            headers: { 'Authorization': 'Bearer ' + tokenResponse.access_token }
          }).then(r => r.json());
          __socialLoginCreate('google', userInfo.email, userInfo.name || userInfo.given_name, userInfo.picture);
        } catch (e) {
          showToast('Erreur récupération infos Google', 'error');
          __showSocialModal('google');
        }
      },
      error_callback: (err) => {
        showToast('Connexion Google échouée : ' + (err?.message || 'erreur inconnue'), 'error');
      }
    });

    // Ouvre réellement accounts.google.com dans une popup/redirect
    tokenClient.requestAccessToken({ prompt: 'select_account' });
  } catch(e) {
    console.warn('Google OAuth error', e);
    // Dernier fallback : redirection directe vers accounts.google.com
    const redirectUri = window.location.origin + window.location.pathname;
    const state = Math.random().toString(36).slice(2) + Date.now().toString(36);
    const nonce = Math.random().toString(36).slice(2) + Date.now().toString(36);
    localStorage.setItem('stockr_oauth_state', state);
    localStorage.setItem('stockr_oauth_nonce', nonce);
    localStorage.setItem('stockr_oauth_provider', 'google');
    const authUrl = 'https://accounts.google.com/o/oauth2/v2/auth?' +
      'client_id=' + encodeURIComponent(clientId) +
      '&redirect_uri=' + encodeURIComponent(redirectUri) +
      '&response_type=' + encodeURIComponent('id_token token') +
      '&scope=' + encodeURIComponent('openid email profile') +
      '&state=' + encodeURIComponent(state) +
      '&nonce=' + encodeURIComponent(nonce) +
      '&prompt=select_account';
    window.location.href = authUrl;
  }
}

async function loginApple() {
  if (typeof logAudit === 'function') logAudit('auth', 'apple_attempt', {});
  const serviceId = (localStorage.getItem('stockr_apple_service_id') || '').trim();

  if (!serviceId) {
    // Ouvre le vrai appleid.apple.com pour connexion
    try {
      window.open('https://appleid.apple.com/sign-in', '_blank', 'noopener');
    } catch(_){}
    showToast("🔐 Connectez-vous à Apple dans l'onglet ouvert, puis revenez ici.", 'info');
    setTimeout(() => __showSocialModal('apple'), 600);
    return;
  }

  try {
    await _loadAppleJS();
    if (!window.AppleID?.auth) throw new Error('AppleID.auth not loaded');

    const redirectUri = window.location.origin + window.location.pathname;
    window.AppleID.auth.init({
      clientId: serviceId,
      scope: 'name email',
      redirectURI: redirectUri,
      state: Math.random().toString(36).slice(2),
      nonce: Math.random().toString(36).slice(2),
      usePopup: true,
    });

    const res = await window.AppleID.auth.signIn();
    // res.authorization.id_token : JWT
    // res.user : { name: { firstName, lastName }, email } (seulement à la 1re connexion)
    let email = '', name = '';
    try {
      const idToken = res?.authorization?.id_token;
      if (idToken) {
        const payload = JSON.parse(atob(idToken.split('.')[1]));
        email = payload.email || '';
      }
    } catch(e){}
    email = email || res?.user?.email || 'apple_user@' + serviceId;
    const fn = res?.user?.name?.firstName || '';
    const ln = res?.user?.name?.lastName || '';
    name = (fn + ' ' + ln).trim() || email.split('@')[0] || 'Utilisateur Apple';
    __socialLoginCreate('apple', email, name);
  } catch(e) {
    console.warn('Apple Sign-In error', e);
    if (e?.error === 'popup_closed_by_user') {
      showToast('Connexion Apple annulée', 'info');
    } else {
      showToast('Erreur Apple Sign-In : ' + (e?.message || e?.error || 'inconnue'), 'error');
      __showSocialModal('apple');
    }
  }
}

// ── OAuth callback handler : détecte id_token/access_token après redirection ──
function _handleOAuthCallback() {
  if (!window.location.hash || window.location.hash.length < 2) return false;
  const hashParams = new URLSearchParams(window.location.hash.slice(1));
  const idToken = hashParams.get('id_token');
  const accessToken = hashParams.get('access_token');
  const state = hashParams.get('state');
  const error = hashParams.get('error');
  const expectedState = localStorage.getItem('stockr_oauth_state');
  const provider = localStorage.getItem('stockr_oauth_provider') || 'google';

  if (error) {
    showToast('OAuth error : ' + error, 'error');
    history.replaceState(null, '', window.location.pathname);
    localStorage.removeItem('stockr_oauth_state');
    localStorage.removeItem('stockr_oauth_provider');
    return true;
  }
  if (!idToken && !accessToken) return false;
  if (state && expectedState && state !== expectedState) {
    showToast('OAuth state mismatch — possible attaque CSRF, annulé', 'error');
    history.replaceState(null, '', window.location.pathname);
    return true;
  }

  // Nettoie l'URL
  history.replaceState(null, '', window.location.pathname);
  localStorage.removeItem('stockr_oauth_state');
  localStorage.removeItem('stockr_oauth_provider');
  localStorage.removeItem('stockr_oauth_nonce');

  (async () => {
    try {
      let email = '', name = '', picture = '';
      if (idToken) {
        const payload = JSON.parse(atob(idToken.split('.')[1]));
        email = payload.email || '';
        name = payload.name || payload.given_name || '';
        picture = payload.picture || '';
      }
      if (!email && accessToken && provider === 'google') {
        const userInfo = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
          headers: { 'Authorization': 'Bearer ' + accessToken }
        }).then(r => r.json());
        email = userInfo.email;
        name = userInfo.name || userInfo.given_name;
        picture = userInfo.picture;
      }
      if (email) {
        __socialLoginCreate(provider, email, name || email.split('@')[0], picture);
      } else {
        showToast('OAuth : email non obtenu', 'error');
      }
    } catch (e) {
      console.warn('OAuth callback parse error', e);
      showToast('Erreur traitement OAuth', 'error');
    }
  })();
  return true;
}

// Convertit une base64url string en ArrayBuffer (nécessaire pour WebAuthn)
function _b64uToBuf(b64u) {
  const pad = '='.repeat((4 - (b64u.length % 4)) % 4);
  const b64 = (b64u + pad).replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(b64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}
// Convertit ArrayBuffer → base64url pour storage
function _bufToB64u(buf) {
  const bin = String.fromCharCode(...new Uint8Array(buf));
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}

// Vérifie si un authenticator biométrique est disponible (TouchID/FaceID/Windows Hello/Android)
async function isBiometricAvailable() {
  if (!window.PublicKeyCredential) return false;
  try {
    if (typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function') {
      return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
    }
  } catch(_){}
  return false;
}

// Enrôle la biométrie (appelé depuis Paramètres → Sécurité)
async function enrollBiometric() {
  if (!window.PublicKeyCredential) {
    showToast('WebAuthn non disponible sur cet appareil', 'error');
    return false;
  }
  const avail = await isBiometricAvailable();
  if (!avail) {
    showToast('Aucun capteur biométrique détecté (TouchID / FaceID / empreinte)', 'error');
    return false;
  }
  const savedSession = getSession();
  if (!savedSession) {
    showToast('Connectez-vous d\'abord puis activez la biométrie', 'info');
    return false;
  }
  try {
    const userEmail = savedSession.user?.email || savedSession.email || 'user';
    const userName  = savedSession.user?.name  || savedSession.name  || 'BARO User';
    const cred = await navigator.credentials.create({
      publicKey: {
        challenge: crypto.getRandomValues(new Uint8Array(32)),
        rp: { name: 'BARO', id: window.location.hostname },
        user: {
          id: new TextEncoder().encode(userEmail),
          name: userEmail,
          displayName: userName,
        },
        pubKeyCredParams: [{ alg: -7, type: 'public-key' }, { alg: -257, type: 'public-key' }],
        authenticatorSelection: {
          authenticatorAttachment: 'platform',
          userVerification: 'required',
          residentKey: 'preferred',
        },
        timeout: 60000,
        attestation: 'none',
      }
    });
    if (cred && cred.id) {
      // Stocke l'ID (base64url) + rawId en base64url pour allowCredentials
      localStorage.setItem('stockr_webauthn_cred', cred.id);
      localStorage.setItem('stockr_webauthn_rawid', _bufToB64u(cred.rawId));
      showToast('✅ Biométrie enrôlée avec succès', 'success');
      logAudit('auth', 'biometric_enrolled', { device: navigator.userAgent.split(' ').slice(-1)[0] });
      return true;
    }
    return false;
  } catch(e) {
    logAudit('auth', 'biometric_failed', { error: e.message, stage: 'enroll' });
    const msg = e.name === 'NotAllowedError' ? 'Enrôlement annulé' :
                e.name === 'SecurityError' ? 'HTTPS requis pour la biométrie' :
                `Erreur biométrie : ${e.message}`;
    showToast(msg, 'error');
    return false;
  }
}

async function loginBiometric() {
  if (!window.PublicKeyCredential) {
    showToast('WebAuthn non disponible sur cet appareil', 'error');
    return;
  }
  try {
    const savedCredId = localStorage.getItem('stockr_webauthn_cred');
    const savedRawId  = localStorage.getItem('stockr_webauthn_rawid');
    const savedSession = getSession();

    // Si pas encore enrôlé : déléguer à enrollBiometric()
    if (!savedCredId) {
      if (!savedSession) {
        showToast('Connectez-vous d\'abord (email/mot de passe), puis activez la biométrie dans Paramètres > Sécurité', 'info');
        return;
      }
      await enrollBiometric();
      return;
    }

    // Vérification : passer allowCredentials pour restreindre au credential enrôlé
    const publicKey = {
      challenge: crypto.getRandomValues(new Uint8Array(32)),
      rpId: window.location.hostname,
      timeout: 60000,
      userVerification: 'required',
    };
    if (savedRawId) {
      try {
        publicKey.allowCredentials = [{
          type: 'public-key',
          id: _b64uToBuf(savedRawId),
          transports: ['internal'],
        }];
      } catch(_){}
    }
    await navigator.credentials.get({ publicKey });
    logAudit('auth', 'biometric_success', {});
    showToast('✅ Biométrie validée', 'success');
    if (savedSession) {
      S.token = savedSession.token;
      S.session = savedSession;
      S.view = 'home';
      render();
      try { loadData(); } catch(e){}
    } else {
      showToast('Session absente — connectez-vous', 'warning');
    }
  } catch(e) {
    logAudit('auth', 'biometric_failed', { error: e.message, stage: 'verify' });
    const msg = e.name === 'NotAllowedError' ? 'Authentification biométrique annulée' :
                e.name === 'InvalidStateError' ? 'Cet appareil n\'est pas enrôlé — réenrôlez' :
                e.name === 'SecurityError' ? 'HTTPS requis pour la biométrie' :
                `Erreur : ${e.message || 'Authentification échouée'}`;
    showToast(msg, 'error');
  }
}

