// Classification MobileNet sur l'IMAGE ENTIÈRE → reconnaît n'importe quel produit
// même quand COCO-SSD ne trouve aucune boîte (objet hors des 80 classes COCO).
async function _classifyFullImage(img){
  let mn;
  try { mn = await loadMobileNet(); } catch(e){ return null; }
  try {
    const preds = await mn.classify(img, 5);
    if (!preds || !preds.length) return null;
    const top = preds[0];
    const conf = Math.round((top.probability || 0) * 100);
    if (conf < 18) return null; // trop incertain
    const rawCls = (top.className || '').split(',')[0].trim().toLowerCase();
    const frName = MOBILENET_FR[rawCls] || (rawCls ? rawCls.charAt(0).toUpperCase() + rawCls.slice(1) : 'Produit');
    const imgW = img.width || img.naturalWidth || img.videoWidth || 300;
    const imgH = img.height || img.naturalHeight || img.videoHeight || 300;
    let quality = {};
    try { quality = _analyzeImageQuality(img, [0, 0, imgW, imgH]); } catch(_){}
    // Alternatives lisibles (2e et 3e hypothèses) pour aider l'utilisateur à corriger
    const alts = preds.slice(1, 3).map(p => {
      const c = (p.className || '').split(',')[0].trim().toLowerCase();
      return MOBILENET_FR[c] || (c ? c.charAt(0).toUpperCase() + c.slice(1) : '');
    }).filter(Boolean);
    return {
      detected_name: frName,
      matched_name:  frName,
      matched_id:    null,
      quantity:      1,
      confidence:    conf,
      fine_class:    rawCls,
      fine_confidence: conf,
      refined_by:    'MobileNet',
      alternatives:  alts,
      boxes:         [[0, 0, imgW, imgH]],
      quality_score: quality.score,
      damage_flags:  quality.flags || [],
      _fullframe:    true,
    };
  } catch(e){ return null; }
}

// Affine les détections génériques avec MobileNet (classification fine sur le crop)
async function _refineWithMobileNet(detections, img){
  if (!detections || !detections.length) return detections;
  let mn;
  try { mn = await loadMobileNet(); } catch(e) { return detections; }
  const genericNames = new Set([...Object.values(COCO_TRANSLATE), 'Objet', 'Smartphone', 'Téléphone']);
  for (const d of detections.slice(0, 8)) {
    try {
      if (!d.boxes || !d.boxes.length) continue;
      const [x, y, w, h] = d.boxes[0];
      if (w < 32 || h < 32) continue;
      const canvas = document.createElement('canvas');
      canvas.width = 224; canvas.height = 224;
      canvas.getContext('2d').drawImage(img, x, y, w, h, 0, 0, 224, 224);
      const preds = await mn.classify(canvas, 3);
      if (!preds || !preds.length) continue;
      const top = preds[0];
      const cls = (top.className || '').split(',')[0].trim().toLowerCase();
      d.fine_class = cls;
      d.fine_confidence = Math.round((top.probability || 0) * 100);
      const fr = MOBILENET_FR[cls];
      // On ne remplace que les noms génériques COCO, jamais un match local/mémoire/OCR
      const isGeneric = !d.matched_id && genericNames.has(d.detected_name);
      if (fr && isGeneric && top.probability >= 0.40) {
        d.detected_name = fr;
        d.refined_by = 'MobileNet';
      }
    } catch(e){ /* crop suivant */ }
  }
  return detections;
}

// ── Regrouper les prédictions par classe (fallback rapide, sans OCR) ──
function _groupPredictionsByClass(predictions){
  const groups = {};
  for (const p of predictions){
    const cls = p.class || 'objet';
    if (!groups[cls]) groups[cls] = { count: 0, sum: 0, boxes: [] };
    groups[cls].count++;
    groups[cls].sum += (p.score || 0);
    groups[cls].boxes.push(p.bbox);
  }
  const detections = [];
  for (const cls in groups) {
    const g = groups[cls];
    const name = _translateCocoClass(cls);
    const match = (S.articles || []).find(a =>
      a.name && a.name.toLowerCase().includes(cls.toLowerCase()) ||
      a.name && name.toLowerCase().includes(a.name.toLowerCase()) ||
      a.name && a.name.toLowerCase() === name.toLowerCase()
    );
    detections.push({
      detected_name: name,
      matched_id:    match ? match.id : null,
      matched_name:  match ? match.name : name,
      matched_unit:  match ? (match.unit || 'pce') : 'pce',
      quantity:      g.count,
      confidence:    Math.round((g.sum / g.count) * 100),
      boxes:         g.boxes,
      coco_class:    cls,
      ocr_text:      '',
    });
  }
  return detections;
}

// ── Scoring de similarité texte (pour matching OCR → article) ──
function _textSimilarity(a, b){
  if (!a || !b) return 0;
  const la = a.toLowerCase(); const lb = b.toLowerCase();
  if (la === lb) return 1;
  if (la.includes(lb) || lb.includes(la)) return 0.85;
  const wa = la.split(/\s+/).filter(w => w.length >= 3);
  const wb = lb.split(/\s+/).filter(w => w.length >= 3);
  if (!wa.length || !wb.length) return 0;
  let hits = 0;
  for (const w of wa) if (wb.some(x => x.includes(w) || w.includes(x))) hits++;
  return hits / Math.max(wa.length, wb.length);
}

