// Mots-clés "primary" (nom produit spécifique) qui doivent gagner sur
// les "secondary" (ingrédients : tomato, orange, pomme…).
// Ex: "TOMATO KETCHUP" → ketchup (primary) gagne sur tomato (secondary).
const SPECTRA_SECONDARY_KW = new Set([
  'tomato','tomate','orange','pomme','ananas','mangue','citron','pamplemousse'
]);

// ── Normalise une chaîne : lowercase, sans accents, sans espaces/ponctuation ──
// Permet de matcher "iPhone 17 Pro Max" → "iphone17promax"
function _normalizeKey(s) {
  if (!s) return '';
  return String(s)
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');
}

// Index squeezed (clé sans espaces) calculé une seule fois
let __SPECTRA_SQUEEZED = null;
function _spectraSqueezedIndex() {
  if (__SPECTRA_SQUEEZED) return __SPECTRA_SQUEEZED;
  __SPECTRA_SQUEEZED = {};
  for (const key in SPECTRA_KEYWORDS) {
    const sq = _normalizeKey(key);
    if (sq && !__SPECTRA_SQUEEZED[sq]) __SPECTRA_SQUEEZED[sq] = SPECTRA_KEYWORDS[key];
  }
  return __SPECTRA_SQUEEZED;
}

// Extrait {type, brand, name} depuis un texte OCR (français/anglais)
function _resolveFromOCR(ocrText){
  if (!ocrText) return null;
  // Tokens en lowercase (sans accents, ponctuation)
  const lo = ocrText.toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const words = lo
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length >= 3);
  // Garder aussi les tokens originaux (pour détecter les marques en MAJUSCULES)
  const rawTokens = (ocrText || '')
    .replace(/[^\p{L}\p{N}\s'\-]/gu, ' ')
    .split(/\s+/)
    .filter(w => w.length >= 3);

  // Marquer les mots qui matchent un keyword (évite de les traiter comme marque)
  const matchedWords = new Set();

  // Pass -1: squeezed (concat sans espaces) pour détecter modèles précis
  // Ex: "iPhone 17 Pro Max" → "iphone17promax"
  const squeezed = _spectraSqueezedIndex();
  const fullSqueezed = _normalizeKey(ocrText);
  let foundType = null;
  let foundBrand = null;

  // Essaie d'abord le match complet squeezed (le plus précis)
  if (fullSqueezed && squeezed[fullSqueezed]) {
    const hit = squeezed[fullSqueezed];
    if (hit.type) foundType = hit.type;
    if (hit.brand) foundBrand = hit.brand;
  }

  // Puis recherche sous-chaînes longues (≥ 7 chars) dans la concat squeezed
  if (!foundType && fullSqueezed.length >= 7) {
    // Trie les clés par longueur décroissante — les plus spécifiques gagnent
    const sortedKeys = Object.keys(squeezed).filter(k => k.length >= 7).sort((a,b)=>b.length-a.length);
    for (const k of sortedKeys) {
      if (fullSqueezed.includes(k)) {
        const hit = squeezed[k];
        if (hit.type && !foundType) foundType = hit.type;
        if (hit.brand && !foundBrand) foundBrand = hit.brand;
        if (foundType) break; // un match suffit
      }
    }
  }

  // Pass 0: paires de mots (ex: "uncle ben", "lait infantile")
  for (let i = 0; i < words.length - 1; i++) {
    const pair = words[i] + ' ' + words[i+1];
    const hit = SPECTRA_KEYWORDS[pair];
    if (hit) {
      if (hit.type && !foundType) foundType = hit.type;
      if (hit.brand && !foundBrand) foundBrand = hit.brand;
      matchedWords.add(words[i]); matchedWords.add(words[i+1]);
    }
  }

  // Pass 1 : primary (produits spécifiques). "ketchup" gagne sur "tomato".
  if (!foundType) {
    for (const w of words) {
      const hit = SPECTRA_KEYWORDS[w];
      if (hit && hit.type && !SPECTRA_SECONDARY_KW.has(w)) {
        foundType = hit.type;
        matchedWords.add(w);
        break;
      }
    }
  }
  // Pass 2 : marques pures (heinz, nestle, danone…)
  for (const w of words) {
    const hit = SPECTRA_KEYWORDS[w];
    if (hit && hit.brand && !foundBrand) {
      foundBrand = hit.brand;
      matchedWords.add(w);
    }
  }
  // Pass 3 : secondary (ingrédients) si rien de mieux trouvé
  if (!foundType) {
    for (const w of words) {
      const hit = SPECTRA_KEYWORDS[w];
      if (hit && hit.type) {
        foundType = hit.type;
        matchedWords.add(w);
        break;
      }
    }
  }

  // Extraction brand "raw" : tokens en MAJUSCULES qui ne matchent pas un keyword
  // et qui ne sont pas des unités (ML, KG, LT, G, CL, L) ni des mots génériques
  const UNITS = /^(?:ML|CL|DL|L|G|KG|MG|LT|OZ|LB)$/i;
  const IGNORE_BRAND = new Set([
    'original','taste','baby','dry','matic','classic','eau','water','biere','beer',
    'huile','oil','lait','milk','juice','jus','sugar','sucre','pain','bread',
    'tomato','tomate','orange','pomme','mangue','citron','cola'
  ]);
  const rawBrand = [];
  for (const tok of rawTokens) {
    const lo = tok.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    if (matchedWords.has(lo)) continue;
    if (SPECTRA_SECONDARY_KW.has(lo)) continue;
    if (IGNORE_BRAND.has(lo)) continue;
    if (UNITS.test(tok)) continue;
    if (/^\d+$/.test(tok)) continue;
    if (tok.length < 4 || tok.length > 15) continue;
    // MAJUSCULES seulement (au moins 80% de lettres majuscules)
    const letters = tok.replace(/[^\p{L}]/gu, '');
    if (!letters) continue;
    const upper = letters.replace(/[^\p{Lu}]/gu, '');
    if (upper.length / letters.length < 0.7) continue;
    rawBrand.push(tok.toUpperCase());
  }

  if (!foundType && !foundBrand && rawBrand.length === 0) return null;

  // Construire le nom final : "Type Marque" (ex: "Bouteille de Ketchup Heinz")
  const finalBrand = foundBrand || (rawBrand[0] || null);
  let name = foundType || '';
  if (finalBrand) {
    // Évite d'ajouter la marque si elle est déjà dans le type (ex: "Bouteille de Coca-Cola")
    const lowName = name.toLowerCase();
    const lowBrand = finalBrand.toLowerCase();
    if (!lowName.includes(lowBrand) && !lowBrand.includes(lowName.split(' ').pop()||'')) {
      name = name ? (name + ' ' + finalBrand) : finalBrand;
    }
  }
  return { type: foundType, brand: finalBrand, name: (name || foundType || '').trim() };
}

// ── OpenFoodFacts lookup : produit par code-barres ──
// API gratuite, 2M+ produits. Cache local pour minimiser les appels.
async function lookupProductByEAN(ean){
  if (!ean) return null;
  // Cache localStorage
  let cache = {};
  try { cache = JSON.parse(localStorage.getItem('stockr_eanDB') || '{}'); } catch(e){}
  if (cache[ean] !== undefined) return cache[ean]; // null aussi mémorisé (pour éviter retry)
  try {
    const r = await fetch('https://world.openfoodfacts.org/api/v2/product/' + encodeURIComponent(ean) + '.json', { cache:'force-cache' });
    if (!r.ok) { cache[ean] = null; localStorage.setItem('stockr_eanDB', JSON.stringify(cache)); return null; }
    const d = await r.json();
    if (d.status === 1 && d.product) {
      const prod = d.product;
      const name = prod.product_name_fr || prod.product_name || '';
      const brand = (prod.brands || '').split(',')[0].trim();
      const cat = (prod.categories_tags?.[0] || '').replace(/^fr:|^en:/, '').replace(/-/g,' ');
      const result = { ean, name, brand, category: cat, quantity: prod.quantity || '', image: prod.image_front_small_url || '' };
      cache[ean] = result;
      try { localStorage.setItem('stockr_eanDB', JSON.stringify(cache)); } catch(e){}
      return result;
    }
    cache[ean] = null;
    try { localStorage.setItem('stockr_eanDB', JSON.stringify(cache)); } catch(e){}
    return null;
  } catch(e){ return null; }
}

// ── Nettoyage OCR façon Google Lens ─────────────
// Objectif : extraire uniquement les tokens qui ressemblent à un nom/marque réel
//   • Rejette les lettres seules, symboles, "bruit" OCR (« Ae », « J À tans »…)
//   • Garde les mots ≥ 3 lettres + les quantités (500g, 1L, 250ml)
//   • Limite à 3 tokens + 30 caractères pour rester lisible
function _cleanOcrTail(ocr) {
  if (!ocr) return '';
  // Remplace les ligatures/accents OCR foireux puis tokenise
  const raw = String(ocr)
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')       // garde lettres/chiffres/espaces
    .replace(/\s+/g, ' ')
    .trim();
  if (!raw) return '';
  const tokens = raw.split(' ');
  const kept = [];
  const seen = new Set();
  // Mots très courants OCR bruit à ignorer même s'ils font 3 lettres
  const NOISE = new Set(['aaa','bbb','ccc','xxx','abc','arcs','les','des','dun','une','qui','que','ses','son','sur','ses']);
  for (const tok of tokens) {
    const t = tok.trim();
    if (!t) continue;
    const low = t.toLowerCase();
    // Quantité (500g, 1L, 25cl, 250ml, 1kg) — toujours gardée
    const isQty = /^\d+([.,]\d+)?\s*(g|kg|mg|l|ml|cl|dl|oz|lb|pc|pcs|x)?$/i.test(t);
    // Mot réel : ≥ 4 lettres ET contient ≥ 1 voyelle (filtre "RR", "FA", "Ae")
    const hasVowel = /[aeiouyàâäéèêëîïôöùûü]/i.test(t);
    const isWord = /^[\p{L}]{4,}$/u.test(t) && hasVowel && !NOISE.has(low);
    // Acronyme marque (≥ 3 majuscules consécutives) : UHT, BIC, MAX
    const isAcronym = /^[A-Z]{3,}$/.test(t);
    if (!(isQty || isWord || isAcronym)) continue;
    if (seen.has(low)) continue;
    seen.add(low);
    kept.push(t);
    if (kept.length >= 3) break;  // max 3 tokens pour rester lisible
  }
  // Exiger ≥ 2 tokens pour éviter les bribes "— FA" ou "— arcs"
  if (kept.length < 2) return '';
  const joined = kept.join(' ');
  return joined.length > 30 ? joined.slice(0, 30).trim() : joined;
}

// ── Grouping SMART avec OCR + mémoire produit ──
// Résultat : "Bouteille — HEINZ KETCHUP 500g" au lieu de juste "Bouteille"
async function _groupPredictionsSmart(predictions, imgOrCanvas){
  // 1. OCR sur chaque boîte détectée
  const enriched = [];
  for (const p of predictions) {
    let ocrResult = { text: '', confidence: 0 };
    // OCR uniquement si la boîte est suffisamment grande (évite bruit)
    const [, , w, h] = p.bbox || [0,0,0,0];
    if (w > 40 && h > 40) {
      try { ocrResult = await _ocrRegion(imgOrCanvas, p.bbox); } catch(e){}
    }
    enriched.push({ ...p, ocr: ocrResult });
  }

  // 2. Grouper par signature (coco_class + 1ʳᵉ ligne OCR)
  const groups = {};
  for (const p of enriched) {
    const cls = p.class || 'objet';
    const ocrLine = (p.ocr.text || '').split(/\n/)[0].trim();
    const firstWord = ocrLine.split(/\s+/)[0].toLowerCase();
    const sig = cls + '|' + firstWord;
    if (!groups[sig]) {
      groups[sig] = { cocoClass: cls, ocrText: ocrLine, count: 0, sum: 0, boxes: [], ocrConf: 0 };
    }
    groups[sig].count++;
    groups[sig].sum += (p.score || 0);
    groups[sig].boxes.push(p.bbox);
    // Garder l'OCR le plus long (plus d'info)
    if ((p.ocr.text || '').length > (groups[sig].ocrText || '').length) {
      groups[sig].ocrText = p.ocr.text;
      groups[sig].ocrConf = p.ocr.confidence;
    }
  }

  // 3. Résolution du nom final (priorité : mémoire > article match OCR > COCO class + OCR)
  const detections = [];
  for (const sig in groups) {
    const g = groups[sig];
    const cocoName = _translateCocoClass(g.cocoClass);
    const ocr = (g.ocrText || '').trim();

    // a. Chercher dans la mémoire produit
    const remembered = recallProduct(g.cocoClass, ocr);

    // b. Chercher article par EAN / ref / nom / OCR
    let match = null;
    if (remembered && remembered.articleId) {
      match = (S.articles || []).find(a => a.id === remembered.articleId);
    }
    if (!match && ocr) {
      // Matching article par similarité nom ↔ OCR
      let best = null, bestScore = 0;
      for (const a of (S.articles || [])) {
        const s = _textSimilarity(a.name || '', ocr);
        if (s > bestScore) { bestScore = s; best = a; }
      }
      if (bestScore >= 0.5) match = best;
    }
    if (!match) {
      // Fallback : matching par COCO class dans nom
      match = (S.articles || []).find(a =>
        a.name && (a.name.toLowerCase().includes(g.cocoClass.toLowerCase()) || a.name.toLowerCase().includes(cocoName.toLowerCase()))
      );
    }

    // c. Résolution par dictionnaire mots-clés (ketchup → "Bouteille de Ketchup")
    const resolved = _resolveFromOCR(ocr);

    // d. Construire le nom affiché (priorité : mémoire > dict mots-clés > article match > COCO+OCR)
    let detectedName;
    let resolvedType = null, resolvedBrand = null;
    if (remembered && remembered.finalName) {
      detectedName = remembered.finalName;
    } else if (resolved && resolved.name) {
      // "Bouteille de Ketchup Heinz" (type reconnu) ou juste la marque si pas de type
      detectedName = resolved.name;
      resolvedType = resolved.type;
      resolvedBrand = resolved.brand;
    } else if (ocr) {
      // Nettoyage intelligent façon Google Lens :
      // • tokens = mots ≥ 3 lettres OU chiffres+unité (500g, 1L, 250ml…)
      // • rejette les jetons "bruit" (< 3 lettres, symboles isolés, lettres seules)
      // • n'ajoute la queue OCR que si ≥ 2 tokens ET confiance OCR ≥ 55
      const cleanTail = _cleanOcrTail(ocr);
      const ocrOk = (g.ocrConf || 0) >= 55;
      if (cleanTail && ocrOk) {
        detectedName = `${cocoName} — ${cleanTail}`;
      } else {
        detectedName = cocoName;
      }
    } else {
      detectedName = cocoName;
    }

    detections.push({
      detected_name: detectedName,
      matched_id:    match ? match.id : null,
      matched_name:  match ? match.name : detectedName,
      matched_unit:  match ? (match.unit || 'pce') : 'pce',
      quantity:      g.count,
      confidence:    Math.round((g.sum / g.count) * 100),
      boxes:         g.boxes,
      coco_class:    g.cocoClass,
      ocr_text:      ocr,
      ocr_confidence: Math.round(g.ocrConf || 0),
      from_memory:   !!(remembered && remembered.finalName),
      from_keyword:  !!(resolved && resolved.name && !(remembered && remembered.finalName)),
      resolved_type:  resolvedType,
      resolved_brand: resolvedBrand,
    });
  }
  return detections;
}

// ── IA Gemini Vision (Google AI Studio) ─────────
// Reconnaissance précise de produits (iPhone 17 Pro Max, Nescafé 200g, etc.)
// Utilise la clé API stockée dans localStorage (stockr_gemini_key).
// Plan gratuit : https://aistudio.google.com/app/apikey
let _spectraLastAiError = null; // dernière raison d'échec IA (affichée à l'utilisateur)
// Interroge l'API Google pour la liste des modèles vraiment disponibles sur CETTE clé.
// Bien plus fiable que de deviner les noms (qui varient selon clé/région/version).
let _geminiModelsCache = null;
async function _geminiListModels(apiKey) {
  if (_geminiModelsCache) return _geminiModelsCache;
  const out = [];
  try {
    const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}&pageSize=100`);
    if (!resp.ok) {
      let msg = 'Erreur ' + resp.status;
      try { const e = await resp.json(); msg = e?.error?.message || msg; } catch(_){}
      out.__error = msg;
      return out;
    }
    const data = await resp.json();
    const usable = (data.models || [])
      .filter(m => (m.supportedGenerationMethods || []).includes('generateContent'))
      .map(m => (m.name || '').replace('models/', ''))
      // Exclure non-vision/spéciaux ET les modèles qui exigent la FACTURATION
      // (pro, preview, exp, thinking → souvent hors palier gratuit → erreur billing)
      .filter(n => n && !/embedding|aqa|tts|imagen|image-generation|thinking|pro|preview|exp|vision-latest|ultra/i.test(n));
    // Priorité aux modèles flash GRATUITS et stables
    const score = n =>
      (/^gemini-2\.0-flash$/.test(n) ? 100 : 0) +   // le plus fiable en gratuit
      (/^gemini-2\.5-flash$/.test(n) ? 95 : 0) +
      (/2\.0-flash-lite/.test(n) ? 80 : 0) +
      (/flash-latest/.test(n) ? 75 : 0) +
      (/flash/.test(n) ? 60 : 0) - (n.length * 0.1);
    usable.sort((a, b) => score(b) - score(a));
    _geminiModelsCache = usable;
    return usable;
  } catch (e) {
    out.__error = 'Réseau : ' + (e.message || e);
    return out;
  }
}
// ── Prompt partagé par tous les fournisseurs IA vision ──
const _SPECTRA_PROMPT = `You are Spectra, an elite product recognition AI for African retail SMBs (BARO app).
Analyze this image like Google Lens and identify EVERY commercial product.

CRITICAL RULES:
- Use PRECISE commercial names, brand + model + variant + size/capacity.
- Smartphones: "Apple iPhone 17 Pro Max", "Samsung Galaxy S26 Ultra", "Google Pixel 9 Pro".
- Gaming: "Sony PlayStation 5", "Xbox Series X", "Nintendo Switch OLED", "Manette DualSense".
- Laptops: "HP EliteBook 840 G11", "Apple MacBook Air M4", "Dell XPS 15".
- Food/Drink: "Nescafé Classic 200g", "Coca-Cola 33cl", "Huile Dinor 1L", "Riz Maman 5kg".
- Hygiene: "Colgate Total 75ml", "Omo Matic 2kg", "Savon Fanico".
- Clothing/shoes: "Nike Air Force 1 Low", "Levi's 501".
- NEVER say "remote/Télécommande" for a smartphone. A device with a screen = smartphone.
- Local African brands: Fanico, Candia, Kirène, Awa, SOSUCO, Maggi, Dinor, Riz Maman.

For EACH product return:
1. exact_name (brand+model+variant+capacity)
2. brand
3. category: one of [smartphone, laptop, tablet, watch, audio, photo, tv, appliance, gaming, drink, food, hygiene, household, beauty, clothing, shoes, bag, tool, stationery, health, toy, auto, other]
4. quantity (integer visible)
5. bbox [x,y,width,height] as % 0-100
6. confidence 0-100

Return STRICTLY a valid JSON array only, no markdown:
[{"exact_name":"...","brand":"...","category":"gaming","quantity":1,"bbox":[5,10,40,80],"confidence":92}]`;

// Convertit une image/canvas/vidéo en base64 JPEG + dimensions
function _spectraImgToBase64(imgOrCanvas) {
  const canvas = imgOrCanvas instanceof HTMLCanvasElement
    ? imgOrCanvas
    : (() => {
        const c = document.createElement('canvas');
        c.width = imgOrCanvas.naturalWidth || imgOrCanvas.videoWidth || imgOrCanvas.width;
        c.height = imgOrCanvas.naturalHeight || imgOrCanvas.videoHeight || imgOrCanvas.height;
        c.getContext('2d').drawImage(imgOrCanvas, 0, 0);
        return c;
      })();
  return { base64: canvas.toDataURL('image/jpeg', 0.85).split(',')[1], w: canvas.width, h: canvas.height };
}

// Normalise la sortie JSON de n'importe quelle IA → format détection Spectra
function _normalizeAIProducts(products, imgW, imgH, providerLabel) {
  const norm = s => (s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  return products.map((p, i) => {
    const name = p.exact_name || p.name || 'Produit';
    const nn = norm(name);
    const match = (S.articles||[]).find(a => norm(a.name) === nn)
               || (S.articles||[]).find(a => nn.includes(norm(a.name)) || norm(a.name).includes(nn.split(' ')[0]));
    return {
      id: `ai_${Date.now()}_${i}`,
      cocoClass: p.category || 'object',
      detected_name: name,
      matched_name: match ? match.name : name,
      matched_id: match ? match.id : null,
      brand: p.brand || '',
      category: p.category || 'other',
      quantity: p.quantity || 1,
      confidence: p.confidence || 88,
      refined_by: providerLabel || 'Spectra AI',
      ai_powered: true,
      boxes: [[ (p.bbox?.[0]||0)*imgW/100, (p.bbox?.[1]||0)*imgH/100, (p.bbox?.[2]||50)*imgW/100, (p.bbox?.[3]||50)*imgH/100 ]],
    };
  });
}

// Extrait un tableau JSON d'un texte de réponse LLM (gère ```json ... ```)
function _extractJSONArray(text) {
  if (!text) return null;
  const m = text.match(/\[[\s\S]*\]/);
  if (!m) return null;
  try { const a = JSON.parse(m[0]); return Array.isArray(a) ? a : null; } catch(_) { return null; }
}

// ── Fournisseurs OpenAI-compatibles (Groq, OpenRouter) ──
const _AI_PROVIDERS = {
  groq: {
    label: 'Groq (Llama Vision)',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    models: ['meta-llama/llama-4-scout-17b-16e-instruct', 'meta-llama/llama-4-maverick-17b-128e-instruct'],
    detect: k => /^gsk_/.test(k),
  },
  openrouter: {
    label: 'OpenRouter',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    models: ['meta-llama/llama-3.2-11b-vision-instruct:free', 'qwen/qwen2.5-vl-72b-instruct:free', 'google/gemini-2.0-flash-exp:free'],
    detect: k => /^sk-or-/.test(k),
  },
};

async function _visionOpenAICompat(providerId, apiKey, imgOrCanvas) {
  const prov = _AI_PROVIDERS[providerId];
  if (!prov) return null;
  const { base64, w, h } = _spectraImgToBase64(imgOrCanvas);
  const payloadBase = {
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: _SPECTRA_PROMPT },
        { type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + base64 } },
      ],
    }],
    temperature: 0.2, max_tokens: 1500,
  };
  let lastErr = '';
  for (const model of prov.models) {
    try {
      const resp = await fetch(prov.url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
        body: JSON.stringify({ ...payloadBase, model }),
      });
      if (resp.ok) {
        const data = await resp.json();
        const text = data?.choices?.[0]?.message?.content || '';
        const products = _extractJSONArray(text);
        if (products && products.length) return _normalizeAIProducts(products, w, h, prov.label);
        lastErr = 'Aucun produit détecté.';
        continue;
      }
      let msg = 'Erreur ' + resp.status;
      try { const e = await resp.json(); msg = e?.error?.message || msg; } catch(_){}
      lastErr = msg;
      if (resp.status === 401) { lastErr = 'Clé ' + prov.label + ' invalide.'; break; }
    } catch(e) { lastErr = 'Réseau : ' + (e.message || e); }
  }
  _spectraLastAiError = lastErr || (prov.label + ' n\'a pas répondu.');
  return null;
}

// ── IA vision GRATUITE SANS CLÉ (Pollinations) — moteur par défaut ──
// Endpoint OpenAI-compatible, libre d'accès, CORS navigateur, mondial.
// Permet de reconnaître n'importe quel produit SANS aucune configuration.
async function _visionPollinations(imgOrCanvas) {
  try {
    const { base64, w, h } = _spectraImgToBase64(imgOrCanvas);
    const resp = await fetch('https://text.pollinations.ai/openai', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'openai',
        messages: [{
          role: 'user',
          content: [
            { type: 'text', text: _SPECTRA_PROMPT },
            { type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + base64 } },
          ],
        }],
        temperature: 0.2,
        referrer: 'baro-app',
      }),
    });
    if (!resp.ok) {
      _spectraLastAiError = 'IA gratuite saturée — réessaie dans 1 min, ou ajoute une clé Groq pour la fiabilité.';
      return null;
    }
    const data = await resp.json().catch(() => null);
    const text = data?.choices?.[0]?.message?.content || (typeof data === 'string' ? data : '');
    const products = _extractJSONArray(text);
    if (products && products.length) return _normalizeAIProducts(products, w, h, 'Spectra AI (gratuit)');
    _spectraLastAiError = 'Produit non identifié — réessaie avec une photo plus nette.';
    return null;
  } catch(e) {
    _spectraLastAiError = 'IA gratuite indisponible (vérifie ta connexion).';
    return null;
  }
}

// ── Orchestrateur : clés configurées d'abord (fiables), puis IA gratuite sans clé ──
function _spectraConfiguredProviders() {
  const out = [];
  const groq = (localStorage.getItem('stockr_groq_key')||'').trim();
  const or   = (localStorage.getItem('stockr_openrouter_key')||'').trim();
  const gem  = (localStorage.getItem('stockr_gemini_key')||'').trim();
  if (groq) out.push('groq');
  if (or)   out.push('openrouter');
  if (gem)  out.push('gemini');
  return out;
}
// hasAI = une clé fournisseur est configurée (l'IA keyless n'est plus garantie)
function _spectraHasOwnKey() { return _spectraConfiguredProviders().length > 0; }
function _spectraHasAI() { return _spectraHasOwnKey(); }

async function _spectraVisionAI(imgOrCanvas) {
  _spectraLastAiError = null;
  // 1) Fournisseurs avec clé (plus fiables / précis) en priorité
  for (const p of _spectraConfiguredProviders()) {
    try {
      let res = null;
      if (p === 'gemini') res = await _spectraGeminiVision(imgOrCanvas);
      else res = await _visionOpenAICompat(p, localStorage.getItem('stockr_' + p + '_key').trim(), imgOrCanvas);
      if (res && res.length) { _spectraLastAiError = null; return res; }
    } catch(e) { _spectraLastAiError = e.message || String(e); }
  }
  // 2) IA GRATUITE SANS CLÉ (toujours tentée) → reconnaît n'importe quel produit
  try {
    const free = await _visionPollinations(imgOrCanvas);
    if (free && free.length) { _spectraLastAiError = null; return free; }
  } catch(e) { _spectraLastAiError = e.message || String(e); }
  return null;
}

async function _spectraGeminiVision(imgOrCanvas) {
  const apiKey = localStorage.getItem('stockr_gemini_key');
  if (!apiKey) return null;
  try {
    const _img = _spectraImgToBase64(imgOrCanvas);
    const base64 = _img.base64;
    const canvas = { width: _img.w, height: _img.h };
    const prompt = _SPECTRA_PROMPT;

    _spectraLastAiError = null;
    const body = JSON.stringify({
      contents: [{
        parts: [
          { text: prompt },
          { inline_data: { mime_type: 'image/jpeg', data: base64 } }
        ]
      }],
      generationConfig: { temperature: 0.2, topK: 32, topP: 1, maxOutputTokens: 2048 }
    });
    // Liste de modèles à essayer : d'abord ceux RÉELLEMENT dispo sur cette clé
    // (interrogés via ListModels), puis le choisi, puis des fallbacks connus.
    const chosen = localStorage.getItem('stockr_gemini_model') || 'gemini-2.0-flash';
    const discovered = await _geminiListModels(apiKey);
    const models = [...new Set([
      ...discovered,                          // modèles confirmés dispo (priorité)
      'gemini-2.0-flash', 'gemini-2.5-flash', 'gemini-2.0-flash-001',
      'gemini-flash-latest', 'gemini-2.0-flash-lite'
    ])].filter(Boolean);
    let data = null, lastErr = discovered.__error || '';
    for (const m of models) {
      try {
        const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${m}:generateContent?key=${apiKey}`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body
        });
        if (resp.ok) { data = await resp.json(); if (m !== chosen) { try { localStorage.setItem('stockr_gemini_model', m); } catch(_){} } break; }
        // Erreur HTTP : extraire le message précis de l'API
        let apiMsg = 'Erreur ' + resp.status;
        try { const err = await resp.json(); apiMsg = err?.error?.message || apiMsg; } catch(_){}
        lastErr = apiMsg;
        // 404 = modèle inexistant → essayer le suivant. 400/403 = clé/quota → inutile d'insister
        if (resp.status === 400 || resp.status === 403) break;
      } catch(netErr) { lastErr = 'Réseau : ' + (netErr.message || netErr); }
    }
    if (!data) {
      // Message clair pour l'utilisateur (clé invalide, quota, API non activée…)
      let friendly = lastErr;
      if (/API key not valid|API_KEY_INVALID/i.test(lastErr)) friendly = 'Clé API invalide — vérifiez-la dans Spectra AI.';
      else if (/location is not supported|user location|not available in your|country/i.test(lastErr)) friendly = 'Gemini gratuit indisponible dans ton pays. Solutions : active la facturation Google (carte requise, quota gratuit conservé), ou utilise le scan code-barres/local de Spectra.';
      else if (/billing|prepay|free_tier|free tier|FAILED_PRECONDITION/i.test(lastErr)) friendly = 'Le palier gratuit Gemini exige d\'activer la facturation Google (carte). Sinon, utilise le scan code-barres + dictionnaire local de Spectra.';
      else if (/quota|RESOURCE_EXHAUSTED|rate.?limit|429|exceeded/i.test(lastErr)) friendly = 'Trop de requêtes — attends 1 minute puis réessaie (limite gratuite par minute).';
      else if (/not found|is not found|NOT_FOUND/i.test(lastErr)) friendly = 'Aucun modèle IA compatible sur cette clé — recrée une clé sur Google AI Studio.';
      else if (/PERMISSION_DENIED|SERVICE_DISABLED|has not been used|disabled/i.test(lastErr)) friendly = 'Active l\'API « Generative Language » sur ta clé Google (ou crée la clé sur aistudio.google.com).';
      else if (/Réseau/i.test(lastErr)) friendly = 'Pas de connexion internet — l\'IA vision nécessite internet.';
      _spectraLastAiError = friendly || 'Spectra AI n\'a pas répondu.';
      console.warn('[Spectra AI] échec:', lastErr);
      return null;
    }
    const text = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    // Extract JSON array (strip markdown code fences if any)
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (!jsonMatch) {
      _spectraLastAiError = 'L\'IA n\'a détecté aucun produit sur cette image.';
      return null;
    }
    const products = JSON.parse(jsonMatch[0]);
    if (!Array.isArray(products) || products.length === 0) {
      _spectraLastAiError = 'L\'IA n\'a reconnu aucun produit — réessaie avec une photo plus nette.';
      return null;
    }
    // Convert to spectra detection format (champs attendus par l'écran de confirmation)
    const imgW = canvas.width;
    const imgH = canvas.height;
    return products.map((p, i) => {
      const name = p.exact_name || p.name || 'Produit';
      // Match auto avec un article/produit existant (par nom approximatif)
      const norm = s => (s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
      const nn = norm(name);
      let match = (S.articles||[]).find(a => norm(a.name) === nn)
               || (S.articles||[]).find(a => nn.includes(norm(a.name)) || norm(a.name).includes(nn.split(' ')[0]));
      return {
        id: `ai_${Date.now()}_${i}`,
        cocoClass: p.category || 'object',
        detected_name: name,
        matched_name: match ? match.name : name,
        matched_id: match ? match.id : null,
        brand: p.brand || '',
        category: p.category || 'other',
        quantity: p.quantity || 1,
        confidence: p.confidence || 85,
        refined_by: 'Spectra AI (Gemini)',
        ai_powered: true,
        source: 'gemini',
        boxes: [[
          (p.bbox?.[0] || 0) * imgW / 100,
          (p.bbox?.[1] || 0) * imgH / 100,
          (p.bbox?.[2] || 50) * imgW / 100,
          (p.bbox?.[3] || 50) * imgH / 100
        ]],
      };
    });
  } catch (e) {
    _spectraLastAiError = 'Erreur Spectra AI : ' + (e.message || e);
    console.warn('[Spectra AI] error:', e.message);
    return null;
  }
}

// ── Full-image OCR + dictionary match (fonctionne sans clé API) ──
// Idéal pour produits dont le nom/marque est visible sur l'emballage :
// iPhone (coque arrière), Nescafé, Coca-Cola, Levi's, Omo, etc.
async function _spectraFullImageOCR(img){
  try {
    const worker = await loadOCR();
    const w = img.naturalWidth || img.videoWidth || img.width;
    const h = img.naturalHeight || img.videoHeight || img.height;
    if (!w || !h) return null;
    // Upscale pour meilleure lecture, max 2400px sur le plus grand côté
    const scale = Math.min(2, 2400 / Math.max(w, h));
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(w * scale);
    canvas.height = Math.round(h * scale);
    const ctx = canvas.getContext('2d');
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    // Légère amélioration contraste
    try {
      const d = ctx.getImageData(0,0,canvas.width,canvas.height);
      const arr = d.data;
      for (let i=0;i<arr.length;i+=4){
        const y = arr[i]*0.299 + arr[i+1]*0.587 + arr[i+2]*0.114;
        const v = Math.max(0, Math.min(255, Math.round((y - 50) * 1.5)));
        arr[i]=arr[i+1]=arr[i+2]=v;
      }
      ctx.putImageData(d,0,0);
    } catch(_){}
    const { data: { text, confidence } } = await worker.recognize(canvas);
    const ocrText = (text || '').trim();
    if (!ocrText || ocrText.length < 2) return null;
    const resolved = _resolveFromOCR(ocrText);
    if (!resolved || !resolved.name) return null;
    return {
      detected_name: resolved.name,
      matched_name: resolved.name,
      matched_unit: 'pce',
      quantity: 1,
      confidence: Math.max(60, Math.round(confidence || 75)),
      boxes: [[0, 0, w, h]],
      coco_class: resolved.type ? 'product' : 'object',
      ocr_text: ocrText.slice(0, 200),
      ocr_confidence: Math.round(confidence || 0),
      resolved_type: resolved.type,
      resolved_brand: resolved.brand,
      source: 'full_ocr',
      from_keyword: true,
    };
  } catch(e) {
    return null;
  }
}

// ── Nettoyage COCO : corrige les faux positifs classiques du modèle ─────────
// COCO-SSD n'a que 80 classes très générales → beaucoup d'ambiguïtés sur du stock PME.
// Faux positifs connus et traités ici :
//  • 'remote' → 95% du temps = smartphone (les vraies télécommandes TV sont rares en stock)
//  • 'book'   → souvent emballage carton / sachet plat
//  • 'tie'    → souvent écharpe / étoffe longue
// Stratégie : si OCR lit une marque tech OU si le ratio correspond, rebaptise.
const TECH_BRANDS_RX = /\b(apple|iphone|ipad|macbook|samsung|galaxy|note|pixel|google|xiaomi|redmi|poco|oppo|reno|vivo|oneplus|nothing|realme|tecno|camon|spark|pova|phantom|infinix|hot|smart|note|itel|huawei|mate|nova|honor|magic|nokia|sony|xperia|lg|motorola|moto|asus|rog|zenfone|zte|meizu|alcatel|blackview|doogee|ulefone|wiko|lenovo|gionee)\b/i;
const REMOTE_BRANDS_RX = /\b(samsung\s*tv|sony\s*tv|lg\s*tv|tcl|philips\s*tv|panasonic|bravia|vu|mi\s*tv|xiaomi\s*tv|chromecast|firetv|apple\s*tv|roku|bose|shield|nvidia)\b/i;
const REMOTE_KEYWORDS_RX = /\b(remote|télécommande|telecommande|zapper|controller|air\s*mouse|media\s*center)\b/i;

function _sanitizeCocoDetection(d){
  try {
    if (!d) return d;
    const cls = (d.coco_class || '').toLowerCase();
    const ocr = (d.ocr_text || '').toLowerCase();
    const box = d.boxes && d.boxes[0];
    let bw = 0, bh = 0, ratio = 0;
    if (box) {
      bw = box[2] || 0; bh = box[3] || 0;
      if (bw > 0 && bh > 0) ratio = Math.max(bw, bh) / Math.min(bw, bh);
    }

    // ── Règle 1 : 'remote' COCO = presque toujours un smartphone ──
    // Les vraies télécommandes sont rares en stock PME. On inverse la logique :
    // par défaut "remote" devient "Téléphone", SAUF si preuve explicite de télécommande.
    if (cls === 'remote') {
      const isTechOCR       = TECH_BRANDS_RX.test(ocr);
      const isRemoteOCR     = REMOTE_KEYWORDS_RX.test(ocr);
      const isRemoteBrand   = REMOTE_BRANDS_RX.test(ocr);
      // ratio phone moderne : iPhone 15 Pro Max ≈ 2.16, iPhone 13 ≈ 2.17, Galaxy S24 ≈ 2.22
      const isPhoneShape    = ratio >= 1.5 && ratio <= 2.5;
      // ratio télécommande classique : très allongée (3:1+) ou presque carrée
      const isRemoteShape   = ratio > 3.0 || (ratio > 0 && ratio < 1.3);

      // Garde "Télécommande" SEULEMENT si preuve forte
      const keepRemote = isRemoteOCR || isRemoteBrand || isRemoteShape;
      if (!keepRemote) {
        const labelBase = isTechOCR ? 'Smartphone' : 'Téléphone';
        // Si OCR capte une marque, enrichis le nom : "iPhone", "Samsung Galaxy"…
        let refined = labelBase;
        if (isTechOCR) {
          const m = ocr.match(TECH_BRANDS_RX);
          if (m && m[0]) refined = m[0].charAt(0).toUpperCase() + m[0].slice(1).toLowerCase();
        }
        if (!d.detected_name || d.detected_name === 'Télécommande') d.detected_name = refined;
        if (d.matched_name === 'Télécommande') d.matched_name = refined;
        d.coco_class = 'cell phone';
        d._sanitized_from = 'remote';
      }
    }

    // ── Règle 2 : 'book' sur un objet carré → probablement une boîte/carton ──
    if (cls === 'book' && ratio > 0 && ratio < 1.3) {
      // Livre classique a un ratio ≈ 1.4-1.6. Carré = plus probable boîte/emballage.
      if (!ocr || (!/book|livre|cahier|magazine/.test(ocr))) {
        if (d.detected_name === 'Livre') d.detected_name = 'Boîte / Emballage';
        if (d.matched_name === 'Livre') d.matched_name = d.detected_name;
        d._sanitized_from = 'book';
      }
    }

    // ── Règle 3 : 'cell phone' sans OCR tech + ratio carré → peut-être powerbank/accessoire ──
    // (ne change pas, juste on baisse la confidence quand ambigu)
    if (cls === 'cell phone' && ratio > 0 && ratio < 1.3 && !TECH_BRANDS_RX.test(ocr)) {
      if (typeof d.confidence === 'number') d.confidence = Math.max(40, d.confidence - 15);
      d._ambiguous = true;
    }

    // ── Règle 4 : confidence floor pour les détections sanitized ──
    if (d._sanitized_from && typeof d.confidence === 'number') {
      // On vient de corriger → confidence un peu plus basse pour signaler incertitude
      d.confidence = Math.max(50, Math.min(d.confidence, 85));
    }
  } catch(_){}
  return d;
}

// ── Détection à partir d'une image HTMLImageElement (avec OCR) ──
async function spectraDetectFromImage(img, opts){
  // PRIORITÉ 1 : IA Vision (Groq / OpenRouter / Gemini) si une clé est configurée
  const aiResults = await _spectraVisionAI(img);
  if (aiResults && aiResults.length > 0) {
    showToast(`🤖 Spectra AI : ${aiResults.length} produit(s) reconnu(s)`, 'success');
    return aiResults;
  }

  // PRIORITÉ 2 : Full-image OCR + SPECTRA_KEYWORDS match (pas de clé requise)
  // Attrape les produits avec marque/nom visible (iPhone, Nescafé, Coca, Fanico, etc.)
  try {
    const fullOcrHit = await _spectraFullImageOCR(img);
    if (fullOcrHit) {
      showToast(`📖 Spectra : "${fullOcrHit.matched_name}" reconnu`, 'success');
      return [fullOcrHit];
    }
  } catch(e){}

  const model = await loadCocoSSD();
  const predictions = await model.detect(img, 20);
  const filtered = predictions.filter(p => (p.score || 0) >= 0.4);
  if (opts && opts.fast) {
    const fastDet = _groupPredictionsByClass(filtered).map(_sanitizeCocoDetection);
    // Même en mode rapide : si COCO ne voit rien, on classe l'image entière
    if (fastDet.length === 0) {
      const ff = await _classifyFullImage(img);
      if (ff) return [ff];
    }
    return fastDet;
  }
  // Mode précision maximale : OCR + mémoire + détection dommages
  let detections;
  try {
    detections = await _groupPredictionsSmart(filtered, img);
  } catch(e) {
    detections = _groupPredictionsByClass(filtered);
  }
  // Nettoyer les faux positifs "Télécommande" pour des téléphones
  detections = detections.map(_sanitizeCocoDetection);
  // Couche 2 : classification fine MobileNet (1000 classes) sur chaque objet
  try { detections = await _refineWithMobileNet(detections, img); } catch(e){}
  // ── FALLBACK UNIVERSEL : COCO n'a rien détecté → MobileNet sur l'image entière ──
  // Garantit que Spectra reconnaît n'importe quel produit photographié (1000 classes).
  if (detections.length === 0) {
    const ff = await _classifyFullImage(img);
    if (ff) {
      showToast(`🔍 Spectra : "${ff.detected_name}" reconnu`, 'success');
      return [ff];
    }
  }
  // Ajouter analyse qualité/dommages pour chaque détection
  try {
    for (const d of detections) {
      if (!d.boxes || d.boxes.length === 0) continue;
      const damage = _analyzeImageQuality(img, d.boxes[0]);
      d.quality_score = damage.score;
      d.damage_flags = damage.flags;
    }
  } catch(e){}
  return detections;
}

// ── Heuristique qualité/dommages basée sur l'image ──
// Détecte : flou (variance faible), contrastes extrêmes, taches sombres (moisissure ?)
function _analyzeImageQuality(img, bbox){
  try {
    const [x, y, w, h] = bbox;
    const canvas = document.createElement('canvas');
    canvas.width = Math.min(200, w); canvas.height = Math.min(200, h);
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, x, y, w, h, 0, 0, canvas.width, canvas.height);
    const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imgData.data;
    // 1. Variance du Laplacien (approximation flou)
    let sum = 0, sumSq = 0, n = 0;
    for (let i = 0; i < data.length; i += 16) {
      const gray = 0.299*data[i] + 0.587*data[i+1] + 0.114*data[i+2];
      sum += gray; sumSq += gray*gray; n++;
    }
    const mean = sum / n;
    const variance = (sumSq / n) - (mean * mean);

    // 2. Détecter taches sombres (pourcentage pixels très sombres)
    let darkPixels = 0;
    for (let i = 0; i < data.length; i += 4) {
      const gray = 0.299*data[i] + 0.587*data[i+1] + 0.114*data[i+2];
      if (gray < 30) darkPixels++;
    }
    const darkRatio = darkPixels / (data.length / 4);

    // 3. Flags
    const flags = [];
    if (variance < 200) flags.push('flou');
    if (darkRatio > 0.35) flags.push('zones sombres');
    if (mean < 40) flags.push('sous-exposé');
    if (mean > 220) flags.push('surexposé');

    // 4. Score qualité (0-100)
    let score = 100;
    if (variance < 200) score -= 30;
    if (variance < 80)  score -= 20;
    if (darkRatio > 0.35) score -= 15;
    if (mean < 40 || mean > 220) score -= 10;
    score = Math.max(0, Math.min(100, score));

    return { score, flags, variance: Math.round(variance), mean: Math.round(mean), darkRatio: +darkRatio.toFixed(2) };
  } catch(e) {
    return { score: 100, flags: [] };
  }
}

// ── Lecteur code-barres universel par PHOTO (ZXing, marche sur TOUS les navigateurs) ──
let _zxingPromise = null;
function _ensureZXing() {
  if (window.ZXing && window.ZXing.BrowserMultiFormatReader) return Promise.resolve(window.ZXing);
  if (_zxingPromise) return _zxingPromise;
  _zxingPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/@zxing/library@0.21.3/umd/index.min.js';
    s.async = true;
    s.onload = () => resolve(window.ZXing);
    s.onerror = () => { _zxingPromise = null; reject(new Error('Lecteur code-barres indisponible (hors-ligne ?)')); };
    document.head.appendChild(s);
  });
  return _zxingPromise;
}
async function _decodeBarcodeFromFile(file) {
  const ZX = await _ensureZXing();
  const url = URL.createObjectURL(file);
  try {
    const reader = new ZX.BrowserMultiFormatReader();
    const result = await reader.decodeFromImageUrl(url);
    return (result && (result.text || (result.getText && result.getText()))) || null;
  } finally { try { URL.revokeObjectURL(url); } catch(_){} }
}
// Prendre/choisir une photo d'un code-barres -> décode -> recherche produit -> fiche pré-remplie
function spectraPhotoBarcode() {
  const inp = document.createElement('input');
  inp.type = 'file'; inp.accept = 'image/*'; inp.capture = 'environment';
  inp.onchange = async () => {
    const f = inp.files && inp.files[0]; if (!f) return;
    showToast('🔎 Lecture du code-barres…', '');
    let code = null;
    try { code = await _decodeBarcodeFromFile(f); } catch(e) { showToast(e.message || 'Lecture impossible', 'error'); }
    if (code) { _spectraBarcodeManual(String(code).trim()); }
    else {
      const m = prompt('Code-barres non lisible sur la photo (essayez plus net / plus proche).\n\nVous pouvez le saisir à la main (EAN) :');
      if (m && m.trim()) _spectraBarcodeManual(m.trim());
    }
  };
  inp.click();
}
// ── Scan code-barres depuis image (natif BarcodeDetector, sinon ZXing) ──
async function spectraDetectBarcodeFromImage(img){
  if (!('BarcodeDetector' in window)) {
    throw new Error('BarcodeDetector non supporté sur ce navigateur');
  }
  const detector = new window.BarcodeDetector({
    formats: ['ean_13','ean_8','upc_a','upc_e','code_128','code_39','qr_code']
  });
  const barcodes = await detector.detect(img);
  const detections = [];
  for (const b of barcodes) {
    const code = b.rawValue;
    // Chercher article par EAN / barcode / ref (ref sert aussi de code-barres)
    const match = (S.articles || []).find(a =>
      a.ean === code || a.barcode === code || a.ref === code
    );
    // Si pas d'article local, tenter OpenFoodFacts pour nom précis (2M+ produits)
    let offName = null, offBrand = null, offCategory = null, offImage = null;
    if (!match) {
      try {
        const off = await lookupProductByEAN(code);
        if (off && off.name) {
          offName = off.name;
          offBrand = off.brand || null;
          offCategory = off.category || null;
          offImage = off.image || null;
        }
      } catch(e){}
    }
    const displayName = match ? match.name
                      : (offName ? (offBrand ? `${offName} — ${offBrand}` : offName)
                                 : ('Code ' + code));
    detections.push({
      detected_name: displayName,
      matched_id:    match ? match.id : null,
      matched_name:  match ? match.name : displayName,
      matched_unit:  match ? (match.unit || 'pce') : 'pce',
      quantity:      1,
      confidence:    99,
      barcode:       code,
      format:        b.format,
      off_name:      offName,
      off_brand:     offBrand,
      off_category:  offCategory,
      off_image:     offImage,
    });
  }
  return detections;
}

// ── Scan continu : camera live + detection RAF loop ──
let _spectraStream = null;
let _spectraLoopId = null;
let _spectraLastBarcode = null;
let _spectraCameras = [];
let _spectraCameraIdx = 0;

// ── Multi-caméras : énumère les caméras disponibles ──
async function spectraListCameras(){
  try {
    if (!navigator.mediaDevices?.enumerateDevices) return [];
    // Workaround : sur certains navigateurs il faut d'abord demander la permission
    // pour que les labels soient retournés. On ne force pas ici.
    const devices = await navigator.mediaDevices.enumerateDevices();
    _spectraCameras = devices.filter(d => d.kind === 'videoinput');
    return _spectraCameras;
  } catch(e) { return []; }
}

// Bascule vers la caméra suivante (ou précédente si désactivée)
async function spectraSwitchCamera(){
  const cams = await spectraListCameras();
  if (cams.length < 2) {
    showToast('Une seule caméra disponible', 'info');
    return;
  }
  _spectraCameraIdx = (_spectraCameraIdx + 1) % cams.length;
  const camLabel = cams[_spectraCameraIdx].label || `Caméra ${_spectraCameraIdx + 1}`;
  showToast('Caméra : ' + camLabel, 'info');
  // Redémarrer avec la nouvelle caméra (garde le step actuel)
  const currentStep = S.spectra.step;
  spectraStopContinuous();
  if (currentStep === 'continuous') await spectraStartContinuous();
  else if (currentStep === 'barcode') await spectraStartBarcode();
}

// Construit les contraintes getUserMedia avec la caméra choisie
function _spectraVideoConstraints(highRes){
  const cam = _spectraCameras[_spectraCameraIdx];
  const base = highRes
    ? { width: { ideal: 1280 }, height: { ideal: 720 } }
    : { width: { ideal: 640 }, height: { ideal: 480 } };
  if (cam && cam.deviceId) {
    return { ...base, deviceId: { exact: cam.deviceId } };
  }
  return { ...base, facingMode: { ideal: 'environment' } };
}

// ── Quota de scans Spectra (incitation Premium) ──────────────
// Gratuit : 10/jour · Starter : 50/jour · Pro & Enterprise : illimité
function _spectraDailyLimit() {
  return (typeof _planLimit === 'function') ? _planLimit('spectraPerDay') : 10;
}
function _spectraScansToday() {
  try {
    const raw = JSON.parse(localStorage.getItem('baro_spectra_scans') || '{}');
    return raw.date === new Date().toDateString() ? (raw.count || 0) : 0;
  } catch(_) { return 0; }
}
function _spectraRecordScan() {
  try {
    const today = new Date().toDateString();
    const raw = JSON.parse(localStorage.getItem('baro_spectra_scans') || '{}');
    const count = (raw.date === today ? (raw.count || 0) : 0) + 1;
    localStorage.setItem('baro_spectra_scans', JSON.stringify({ date: today, count }));
  } catch(_) {}
}
// Renvoie true si le scan est autorisé ; sinon affiche l'écran de limite et renvoie false
function _spectraGuard() {
  const limit = _spectraDailyLimit();
  if (_spectraScansToday() >= limit) {
    S.spectra = S.spectra || {};
    S.spectra.step = 'limit';
    S.view = 'spectra';
    haptic('warn');
    render();
    return false;
  }
  _spectraRecordScan();
  return true;
}

async function spectraStartContinuous(){
  if (!_spectraGuard()) return;
  S.spectra.step = 'continuous';
  S.spectra.queue = [];
  S.spectra.confirmed = [];
  S.spectra._videoVotes = {};   // votes MobileNet accumulés sur plusieurs frames
  S.spectra._videoFrameN = 0;
  S.spectra._videoBusy = false;
  render();
  try {
    await loadCocoSSD();
    loadMobileNet().catch(()=>{}); // précharge le 2e cerveau en arrière-plan
  } catch(err) {
    showToast('IA indisponible : ' + err.message, 'error');
    S.spectra.step = 'camera';
    render();
    return;
  }
  const video = await _spectraWaitFor('spectra-video', 40);
  const canvas = await _spectraWaitFor('spectra-canvas', 40);
  if (!video || !canvas) { showToast('Caméra introuvable', 'error'); return; }
  try {
    _spectraStream = await navigator.mediaDevices.getUserMedia({
      video: _spectraVideoConstraints(true),
      audio: false,
    });
    video.srcObject = _spectraStream;
    await video.play();
    // Après premier accès, enumerateDevices donne les labels réels
    await spectraListCameras();
    canvas.width = video.videoWidth || 640;
    canvas.height = video.videoHeight || 480;
    _spectraLoop(video, canvas);
  } catch(err) {
    showToast('Caméra refusée : ' + (err.message || err), 'error');
    S.spectra.step = 'camera';
    render();
  }
}

async function _spectraLoop(video, canvas){
  if (S.spectra.step !== 'continuous') return;
  if (!_cocoModel) { _spectraLoopId = requestAnimationFrame(() => _spectraLoop(video, canvas)); return; }
  try {
    const predictions = await _cocoModel.detect(video, 10);
    const filtered = predictions.filter(p => (p.score || 0) >= 0.5);
    _drawBoundingBoxes(canvas, filtered);
    // Mettre à jour l'overlay (compteur + liste + nom mémoire si connu)
    const overlay = document.getElementById('spectra-overlay');
    if (overlay) {
      const groups = {};
      for (const p of filtered) {
        const k = p.class; if (!groups[k]) groups[k] = { count:0, score:0 };
        groups[k].count++;
        groups[k].score = Math.max(groups[k].score, p.score || 0);
      }
      const lines = Object.keys(groups).map(c => {
        const g = groups[c];
        // Tenter de retrouver en mémoire (sans OCR, par coco class seule)
        const mem = getSpectraMemory().find(m => m.cocoClass === c && m.count >= 2);
        const label = mem ? mem.finalName : _translateCocoClass(c);
        const conf = Math.round(g.score * 100);
        return `<div style="display:flex;justify-content:space-between;gap:10px"><span>${label}</span><b>×${g.count} <span style="opacity:.6;font-size:11px">${conf}%</span></b></div>`;
      }).join('');
      // ── Vote vidéo MobileNet : reconnaît le produit même si COCO ne voit aucune boîte ──
      const topVote = _spectraTopVideoVote();
      const voteLine = topVote
        ? `<div style="display:flex;justify-content:space-between;gap:10px;${lines?'margin-top:6px;padding-top:6px;border-top:1px solid rgba(167,139,250,.25)':''}"><span>🔍 ${topVote.name}</span><b><span style="opacity:.6;font-size:11px">${topVote.votes} vue${topVote.votes>1?'s':''}</span></b></div>`
        : '';
      overlay.innerHTML = (lines + voteLine) || `<div style="opacity:.6">${t('y1_pointezCamera')}</div>`;
    }
    // Stocker les dernières détections pour capture
    S.spectra._liveDetections = filtered;
    // ── Toutes les ~12 frames : classification plein champ MobileNet (vote) ──
    S.spectra._videoFrameN = (S.spectra._videoFrameN || 0) + 1;
    if (S.spectra._videoFrameN % 12 === 0 && !S.spectra._videoBusy && _mobilenetModel) {
      S.spectra._videoBusy = true;
      _mobilenetModel.classify(video, 2).then(preds => {
        if (preds && preds[0] && preds[0].probability >= 0.30) {
          const cls = (preds[0].className || '').split(',')[0].trim().toLowerCase();
          const name = MOBILENET_FR[cls] || (cls ? cls.charAt(0).toUpperCase() + cls.slice(1) : '');
          if (name) {
            S.spectra._videoVotes[name] = (S.spectra._videoVotes[name] || 0) + 1;
          }
        }
      }).catch(()=>{}).finally(() => { S.spectra._videoBusy = false; });
    }
  } catch(e) { /* swallow */ }
  _spectraLoopId = requestAnimationFrame(() => _spectraLoop(video, canvas));
}

// Renvoie le produit le plus voté par MobileNet sur le flux vidéo (≥2 votes)
function _spectraTopVideoVote(){
  const v = S.spectra._videoVotes || {};
  let best = null;
  for (const name in v) { if (!best || v[name] > best.votes) best = { name, votes: v[name] }; }
  return (best && best.votes >= 2) ? best : null;
}

function _drawBoundingBoxes(canvas, predictions){
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.lineWidth = 3;
  ctx.font = 'bold 14px Inter, sans-serif';
  for (const p of predictions) {
    const [x, y, w, h] = p.bbox;
    const color = (p.score >= 0.7) ? '#10B981' : (p.score >= 0.5 ? '#F59E0B' : '#EF4444');
    ctx.strokeStyle = color;
    ctx.strokeRect(x, y, w, h);
    const label = `${_translateCocoClass(p.class)} ${Math.round(p.score*100)}%`;
    const tw = ctx.measureText(label).width + 10;
    ctx.fillStyle = color;
    ctx.fillRect(x, y - 22, tw, 22);
    ctx.fillStyle = '#fff';
    ctx.fillText(label, x + 5, y - 6);
  }
}

function spectraStopContinuous(){
  if (_spectraLoopId) { cancelAnimationFrame(_spectraLoopId); _spectraLoopId = null; }
  if (_spectraStream) {
    try { _spectraStream.getTracks().forEach(tr => tr.stop()); } catch(e){}
    _spectraStream = null;
  }
}

async function spectraCaptureFromContinuous(){
  const live = S.spectra._liveDetections || [];
  const topVote = _spectraTopVideoVote();
  // On accepte la capture s'il y a soit des boîtes COCO, soit un vote vidéo MobileNet
  if (live.length === 0 && !topVote) { showToast('Aucune détection — rapprochez le produit', 'error'); return; }

  // Capture la frame actuelle pour OCR (meilleure précision nommage)
  const video = document.getElementById('spectra-video');
  let captureSource = video;
  if (video && video.videoWidth) {
    try {
      const cap = document.createElement('canvas');
      cap.width = video.videoWidth; cap.height = video.videoHeight;
      const cx = cap.getContext('2d');
      cx.drawImage(video, 0, 0, cap.width, cap.height);
      captureSource = cap;
    } catch(e){}
  }

  spectraStopContinuous();
  S.spectra.step = 'loading';
  if (captureSource && captureSource.toDataURL) { try { S.spectra.capturedImage = captureSource.toDataURL('image/jpeg', 0.7); } catch(_){} }
  render();

  try {
    if (live.length === 0 && topVote) {
      // Aucune boîte COCO mais un produit reconnu par vote vidéo MobileNet
      S.spectra.queue = [{
        detected_name: topVote.name, matched_name: topVote.name, matched_id: null,
        quantity: 1, confidence: Math.min(95, 55 + topVote.votes * 8), refined_by: 'MobileNet vidéo',
      }];
    } else {
      // OCR-enhanced grouping depuis la frame capturée
      const detections = await _groupPredictionsSmart(live, captureSource);
      // Enrichit avec MobileNet (noms fins) puis fallback plein champ si vide
      try { await _refineWithMobileNet(detections, captureSource); } catch(_){}
      S.spectra.queue = detections.length ? detections : (topVote ? [{ detected_name: topVote.name, matched_name: topVote.name, matched_id:null, quantity:1, confidence: Math.min(95, 55 + topVote.votes*8), refined_by:'MobileNet vidéo' }] : []);
    }
  } catch(e) {
    // Dégrade en groupement rapide si OCR indispo
    S.spectra.queue = _groupPredictionsByClass(live);
  }
  S.spectra.current = 0;
  S.spectra.confirmed = [];
  S.spectra.naming = false;
  // Rien reconnu → écran guidé (proposer l'IA vision plutôt qu'un échec sec)
  S.spectra.step = (S.spectra.queue && S.spectra.queue.length) ? 'confirm' : 'noresult';
  render();
}

// ── Scan code-barres continu (caméra live) ─────
async function spectraStartBarcode(){
  if (!_spectraGuard()) return;
  if (!('BarcodeDetector' in window)) {
    // Pas de scan caméra live sur ce navigateur (ordinateur, Firefox, Safari) :
    // on prend/charge une PHOTO du code-barres et on la décode via ZXing (universel).
    spectraPhotoBarcode();
    return;
  }
  S.spectra.step = 'barcode';
  render();
  const video = await _spectraWaitFor('spectra-video', 40);
  if (!video) { showToast('Caméra introuvable', 'error'); return; }
  try {
    _spectraStream = await navigator.mediaDevices.getUserMedia({
      video: _spectraVideoConstraints(false), audio: false,
    });
    video.srcObject = _spectraStream;
    await video.play();
    await spectraListCameras();
    _spectraLastBarcode = null;
    _spectraBarcodeLoop(video);
  } catch(err) {
    showToast('Caméra refusée : ' + (err.message || err), 'error');
    S.spectra.step = 'camera';
    render();
  }
}

// Saisie manuelle d'un code-barres (navigateurs sans BarcodeDetector) :
// recherche OpenFoodFacts puis ouvre le formulaire article pré-rempli.
async function _spectraBarcodeManual(code){
  showToast('🔎 Recherche ' + code + '…', '');
  let off = null;
  try { off = await lookupProductByEAN(code); } catch(_){}
  let name = '';
  if (off && off.name) { const b = (off.brand||'').trim(); name = (b && !off.name.toLowerCase().includes(b.toLowerCase())) ? (off.name + ' — ' + b) : off.name; }
  S.form = { name, stock: 0, min: 0, unit: '', lead: 7, ref: code, price: 0, purchasePrice: 0, sellPrice: 0, expiry: '', perishable: false, category: (off && off.category) || '', image: (off && off.image) || '', ean: code };
  try { spectraStopContinuous(); } catch(e){}
  S.spectra = { step: 'camera', queue: [], current: 0, confirmed: [], naming: false, results: [], compareResults: [] };
  nav('add');
  showToast(off && off.name ? ('✓ ' + off.name) : ('Code ' + code + ' — produit non trouvé, complétez le nom'), off && off.name ? 'success' : '');
}
async function _spectraBarcodeLoop(video){
  if (S.spectra.step !== 'barcode') return;
  try {
    const detector = new window.BarcodeDetector({
      formats: ['ean_13','ean_8','upc_a','upc_e','code_128','code_39','qr_code']
    });
    const barcodes = await detector.detect(video);
    if (barcodes.length > 0) {
      const code = barcodes[0].rawValue;
      if (code && code !== _spectraLastBarcode) {
        _spectraLastBarcode = code;
        _onBarcodeDetected(code, barcodes[0].format);
        return;
      }
    }
  } catch(e) { /* swallow */ }
  _spectraLoopId = requestAnimationFrame(() => _spectraBarcodeLoop(video));
}

async function _onBarcodeDetected(code, format){
  spectraStopContinuous();
  const match = (S.articles || []).find(a =>
    a.ean === code || a.barcode === code || a.ref === code
  );
  // Lookup OpenFoodFacts si article local introuvable
  let offName = null, offBrand = null, offCategory = null, offImage = null;
  if (!match) {
    try {
      showToast('Recherche produit (OpenFoodFacts)…', 'info');
      const off = await lookupProductByEAN(code);
      if (off && off.name) {
        offName = off.name;
        offBrand = off.brand || null;
        offCategory = off.category || null;
        offImage = off.image || null;
      }
    } catch(e){}
  }
  const displayName = match ? match.name
                    : (offName ? (offBrand ? `${offName} — ${offBrand}` : offName)
                               : ('Code ' + code));
  const detection = {
    detected_name: displayName,
    matched_id:    match ? match.id : null,
    matched_name:  match ? match.name : displayName,
    matched_unit:  match ? (match.unit || 'pce') : 'pce',
    quantity:      1,
    confidence:    99,
    barcode:       code,
    format:        format,
    off_name:      offName,
    off_brand:     offBrand,
    off_category:  offCategory,
    off_image:     offImage,
  };
  S.spectra.queue = [detection];
  S.spectra.current = 0;
  S.spectra.confirmed = [];
  S.spectra.naming = false;
  S.spectra.step = 'confirm';
  render();
}

// ── spectraOnFile : détection réelle ───────────
async function spectraOnFile(input) {
  const file = input.files[0];
  if (!file) return;
  if (!_spectraGuard()) return;

  // Capture une miniature pour l'écran d'analyse cinématique (scan-line sur la vraie photo)
  try {
    const dataUrl = await new Promise((res) => { const r = new FileReader(); r.onload = e => res(e.target.result); r.onerror = () => res(''); r.readAsDataURL(file); });
    S.spectra.capturedImage = dataUrl;
  } catch(_) { S.spectra.capturedImage = ''; }

  S.spectra.step = 'loading';
  render();

  try {
    const img = new Image();
    const url = URL.createObjectURL(file);
    await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = reject;
      img.src = url;
    });

    let detections = [];
    if (S.spectraMode === 'barcode') {
      try {
        detections = await spectraDetectBarcodeFromImage(img);
      } catch(err) {
        showToast(err.message, 'error');
        URL.revokeObjectURL(url);
        S.spectra.step = 'camera';
        render();
        return;
      }
    } else {
      // photo / yolo → COCO-SSD + tentative code-barres en parallèle pour enrichir
      detections = await spectraDetectFromImage(img);
      // Essayer de détecter aussi les codes-barres visibles dans l'image
      try {
        if ('BarcodeDetector' in window && detections.length > 0) {
          const barcodes = await spectraDetectBarcodeFromImage(img);
          if (barcodes.length > 0) {
            // Associe chaque code-barres à la détection la plus proche
            // (ou à la première si pas de position)
            for (const b of barcodes) {
              const target = detections[0];
              target.barcode = b.barcode;
              // Si OFF a donné un nom précis, le promouvoir en detected_name
              if (b.off_name) {
                target.off_name = b.off_name;
                target.off_brand = b.off_brand;
                target.off_category = b.off_category;
                target.off_image = b.off_image;
                // Override du nom détecté avec celui d'OFF (source fiable)
                target.detected_name = b.off_brand
                  ? `${b.off_name} — ${b.off_brand}`
                  : b.off_name;
                if (!target.matched_id) target.matched_name = target.detected_name;
                target.from_off = true;
              }
            }
          }
        }
      } catch(e){}
    }
    URL.revokeObjectURL(url);

    // Passerelle /api/spectra/scan (conserve la compat offline-first)
    try { await api('POST', '/api/spectra/scan', { detections }); } catch(e){}

    if (!detections || detections.length === 0) {
      // Rien reconnu → écran guidé (propose l'IA vision) plutôt qu'un échec sec
      S.spectra.queue = [];
      S.spectra.step = 'noresult';
      render();
      return;
    }
    S.spectra.queue   = detections;
    S.spectra.current = 0;
    S.spectra.confirmed = [];
    S.spectra.naming  = false;
    S.spectra.step    = 'confirm';
    render();
  } catch (err) {
    showToast(err.message || 'Spectra error', 'error');
    S.spectra.step = 'noresult';
    render();
  }
}

