// ── Signature électronique (SHA-256 des détections + timestamp) ──
async function _spectraAuditSignature(data){
  try {
    const text = JSON.stringify(data) + '|' + Date.now();
    const buf = new TextEncoder().encode(text);
    const hash = await crypto.subtle.digest('SHA-256', buf);
    return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2,'0')).join('');
  } catch(e) { return 'sig-offline-' + Date.now(); }
}

// ── GPS (timeout 3s, optionnel) ──
function _spectraGetGPS(){
  return new Promise(resolve => {
    if (!navigator.geolocation) return resolve(null);
    const timer = setTimeout(() => resolve(null), 3000);
    navigator.geolocation.getCurrentPosition(
      p => { clearTimeout(timer); resolve({ lat: p.coords.latitude, lon: p.coords.longitude, acc: p.coords.accuracy }); },
      () => { clearTimeout(timer); resolve(null); },
      { enableHighAccuracy: false, timeout: 3000, maximumAge: 60000 }
    );
  });
}

// ── Rapport PDF d'audit Spectra (GPS + signature SHA-256 + détections) ──
async function generateSpectraAuditPDF(){
  if (typeof window.jspdf === 'undefined') { showToast('jsPDF indisponible', 'error'); return; }
  if (!S.spectra.results || S.spectra.results.length === 0) {
    showToast('Aucune détection à signer', 'error'); return;
  }
  showToast('Génération du rapport…', 'info');
  const { jsPDF } = window.jspdf;
  const pdf = new jsPDF({ unit: 'mm', format: 'a4' });
  const now = new Date();
  const user = S.session?.name || S.session?.email || 'Opérateur';
  const biz = S.session?.business || '';
  const gps = await _spectraGetGPS();
  const signature = await _spectraAuditSignature({
    results: S.spectra.results,
    confirmed: S.spectra.confirmed,
    mode: S.spectraMode,
    user, biz, gps, date: now.toISOString()
  });

  // En-tête
  pdf.setFillColor(79, 70, 229); pdf.rect(0, 0, 210, 30, 'F');
  pdf.setTextColor(255,255,255); pdf.setFontSize(20); pdf.setFont('helvetica','bold');
  pdf.text('RAPPORT AUDIT SPECTRA', 15, 20);
  pdf.setFontSize(9); pdf.setFont('helvetica','normal');
  pdf.text(biz || 'BARO', 180, 20, { align: 'right' });

  // Métadonnées
  pdf.setTextColor(30,30,30); pdf.setFontSize(10);
  let y = 45;
  pdf.setFont('helvetica','bold'); pdf.text('Métadonnées', 15, y); y += 7;
  pdf.setFont('helvetica','normal');
  pdf.text(`Date : ${now.toLocaleDateString(_loc())} ${now.toLocaleTimeString(_loc())}`, 15, y); y += 6;
  pdf.text(`Opérateur : ${user}`, 15, y); y += 6;
  pdf.text(`Mode : ${S.spectraMode || 'photo'}`, 15, y); y += 6;
  if (gps) {
    pdf.text(`GPS : ${gps.lat.toFixed(5)}, ${gps.lon.toFixed(5)} (±${Math.round(gps.acc)}m)`, 15, y); y += 6;
  } else {
    pdf.text(`GPS : non disponible`, 15, y); y += 6;
  }
  y += 4;

  // Détections
  pdf.setFont('helvetica','bold'); pdf.setFontSize(12);
  pdf.text('Articles détectés & mis à jour', 15, y); y += 8;
  pdf.setFont('helvetica','normal'); pdf.setFontSize(10);
  pdf.setFillColor(245, 245, 250);
  for (const r of S.spectra.results) {
    if (y > 260) { pdf.addPage(); y = 20; }
    pdf.rect(12, y - 5, 186, 9, 'F');
    pdf.text(`• ${r.name}`, 15, y);
    pdf.text(`${r.new_qty} ${r.unit || 'pce'}`, 195, y, { align: 'right' });
    y += 10;
  }

  // Contexte détaillé (items confirmés avec OCR / barcode / coco class)
  y += 6;
  if (S.spectra.confirmed && S.spectra.confirmed.length) {
    pdf.setFont('helvetica','bold'); pdf.setFontSize(11);
    pdf.text('Détails détection', 15, y); y += 7;
    pdf.setFont('helvetica','normal'); pdf.setFontSize(8);
    for (const c of S.spectra.confirmed) {
      if (y > 270) { pdf.addPage(); y = 20; }
      const line = [
        c.name,
        c.coco_class ? `classe=${c.coco_class}` : '',
        c.ocr_text ? `OCR="${c.ocr_text.slice(0,30)}"` : '',
        c.barcode ? `EAN=${c.barcode}` : ''
      ].filter(Boolean).join(' · ');
      pdf.text('› ' + line, 15, y); y += 5;
    }
  }

  // Signature (pied de page dernière page)
  const pageCount = pdf.internal.getNumberOfPages();
  pdf.setPage(pageCount);
  pdf.setFont('helvetica','bold'); pdf.setFontSize(9);
  pdf.setTextColor(100,100,100);
  pdf.text('SIGNATURE ÉLECTRONIQUE (SHA-256)', 15, 280);
  pdf.setFont('courier','normal'); pdf.setFontSize(7);
  pdf.text(signature.slice(0, 64), 15, 285);
  pdf.text(signature.slice(64), 15, 289);
  pdf.setFont('helvetica','italic'); pdf.setFontSize(7);
  pdf.text('Ce rapport constitue une preuve horodatée infalsifiable — BARO Spectra AI', 15, 294);

  const filename = `audit-spectra-${now.toISOString().slice(0,19).replace(/[:T]/g,'-')}.pdf`;
  pdf.save(filename);

  // Sauvegarder dans historique local
  try {
    const history = JSON.parse(localStorage.getItem('stockr_spectra_audits') || '[]');
    history.unshift({
      id: Date.now(),
      date: now.toISOString(),
      user, biz, mode: S.spectraMode,
      count: S.spectra.results.length,
      signature,
      gps,
      filename
    });
    if (history.length > 100) history.length = 100;
    localStorage.setItem('stockr_spectra_audits', JSON.stringify(history));
  } catch(e){}

  showToast(t('zz6_pdfSigne'), 'success');
}

// ── Scanner un code-barres pour remplir le champ "ref" d'un article ──
// Applique un code-barres au formulaire article : remplit ref/ean puis
// pré-remplit nom/photo/catégorie via OpenFoodFacts (si trouvé). Honnête : si
// le produit n'est pas dans la base, le code est gardé et on le signale.
async function _applyEanLookup(code){
  if (!code) return;
  S.form = S.form || {};
  S.form.ref = code; S.form.ean = code;
  const el = document.getElementById('art-ref-input'); if (el) el.value = code;
  showToast('🔎 Code ' + code + ' — recherche du produit…', '');
  let off = null;
  try { off = await lookupProductByEAN(code); } catch(_){}
  if (off && (off.name || off.image)) {
    if (off.name && !((S.form.name||'').trim())) {
      const b = (off.brand||'').trim();
      S.form.name = (b && !off.name.toLowerCase().includes(b.toLowerCase())) ? (off.name + ' — ' + b) : off.name;
    }
    if (off.image && !(S.form.image||'')) S.form.image = off.image;
    if (off.category && !((S.form.category||'').trim())) S.form.category = off.category;
    showToast('✓ Produit reconnu : ' + (off.name || code), 'success');
  } else {
    showToast('Code ' + code + ' enregistré — produit non trouvé dans la base (remplissez le nom)', '');
  }
  try { if (typeof render === 'function') render(); } catch(_){}
}
async function scanBarcodeForArticle(){
  return _grabBarcode(code => _applyEanLookup(String(code).trim()));
}
// ── Scanner générique : caméra live (BarcodeDetector) ou photo (ZXing) ──
// Appelle onCode(code) une fois le code lu — réutilisé par le formulaire
// article ET par l'Entrée/Sortie en série (Lot 137).
async function _grabBarcode(onCode){
  if (!('BarcodeDetector' in window)) {
    // Fallback universel : photo du code-barres décodée via ZXing (tous navigateurs)
    const inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*'; inp.capture = 'environment';
    inp.onchange = async () => {
      const file = inp.files[0]; if (!file) return;
      showToast('🔎 Lecture du code-barres…', '');
      let code = null;
      try { code = await _decodeBarcodeFromFile(file); } catch(err) { showToast(err.message || 'Lecture impossible', 'error'); }
      if (code) { await onCode(String(code).trim()); }
      else {
        const m = prompt('Code-barres non lisible sur la photo.\nSaisissez-le à la main (EAN) :');
        if (m && m.trim()) await onCode(m.trim());
      }
    };
    inp.click();
    return;
  }
  // Caméra live pour scanner
  const modal = document.createElement('div');
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.9);z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML = `
    <div style="color:#fff;font-weight:700;margin-bottom:12px">${t('x4_scannerCodeBarres')}</div>
    <div style="position:relative;width:100%;max-width:420px;background:#000;border-radius:12px;overflow:hidden;aspect-ratio:4/3">
      <video id="_bcscan-video" playsinline muted autoplay style="width:100%;height:100%;object-fit:cover"></video>
      <div style="position:absolute;inset:25% 10%;border:3px solid #E11D48;border-radius:8px"></div>
    </div>
    <button id="_bcscan-close" style="margin-top:16px;padding:12px 24px;background:#fff;border:0;border-radius:8px;font-weight:700">${t('cancel')}</button>
  `;
  document.body.appendChild(modal);
  const video = modal.querySelector('#_bcscan-video');
  let stream = null, rafId = null, finished = false;
  const cleanup = () => {
    finished = true;
    if (rafId) cancelAnimationFrame(rafId);
    if (stream) { try { stream.getTracks().forEach(t=>t.stop()); } catch(e){} }
    try { modal.remove(); } catch(e){}
  };
  modal.querySelector('#_bcscan-close').onclick = cleanup;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: 'environment' } }, audio: false });
    video.srcObject = stream;
    await video.play();
    const detector = new window.BarcodeDetector({
      formats: ['ean_13','ean_8','upc_a','upc_e','code_128','code_39','qr_code']
    });
    const loop = async () => {
      if (finished) return;
      try {
        const codes = await detector.detect(video);
        if (codes.length > 0) {
          cleanup();
          await onCode(String(codes[0].rawValue).trim());
          return;
        }
      } catch(e){}
      rafId = requestAnimationFrame(loop);
    };
    loop();
  } catch(err) {
    showToast('Caméra refusée : ' + (err.message || err), 'error');
    cleanup();
  }
}

function spectraStartCompare() {
  if (!_spectraGuard()) return;
  // Create file input for compare mode
  const input = document.createElement('input');
  input.type = 'file'; input.accept = 'image/*'; input.capture = 'environment';
  input.onchange = () => {
    const file = input.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      S.spectra.step = 'loading'; render();
      try {
        const data = await api('POST', '/api/spectra/scan', { image: e.target.result });
        if (!data.detections || data.detections.length === 0) {
          showToast(t('spectraNoDetection'), 'error');
          S.spectra.step = 'camera'; render(); return;
        }
        S.spectra.compareResults = data.detections;
        S.spectra.step = 'compare';
        render();
      } catch (err) {
        showToast(err.message || 'Error', 'error');
        S.spectra.step = 'camera'; render();
      }
    };
    reader.readAsDataURL(file);
  };
  input.click();
}

// ── Spectra : Réception Magique ──────────────
function spectraStartReception() {
  if (!_spectraGuard()) return;
  const input = document.createElement('input');
  input.type = 'file'; input.accept = 'image/*'; input.capture = 'environment';
  input.onchange = () => {
    const file = input.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      S.spectra.step = 'loading'; render();
      try {
        const data = await api('POST', '/api/spectra/scan', { image: e.target.result });
        if (!data.detections || data.detections.length === 0) {
          showToast(t('spectraNoDetection'), 'error');
          S.spectra.step = 'camera'; render(); return;
        }
        S.spectra.receptionItems = data.detections;
        S.spectra.step = 'reception';
        render();
      } catch (err) {
        showToast(err.message || 'Error', 'error');
        S.spectra.step = 'camera'; render();
      }
    };
    reader.readAsDataURL(file);
  };
  input.click();
}

async function spectraConfirmReception() {
  const items = S.spectra.receptionItems || [];
  if (items.length === 0) return;
  S.spectra.step = 'loading'; render();
  try {
    const confirmed = items.map(it => ({
      article_id: it.matched_id || null,
      name: it.matched_name || it.detected_name,
      quantity: it.quantity,
      unit: it.matched_unit || 'pce',
    }));
    const data = await api('POST', '/api/spectra/confirm', { items: confirmed });
    S.spectra.results = data.results || [];
    S.spectra.step = 'done';
    showToast(t('spectraReceptionDone'), 'success');
    await loadData();
    render();
  } catch (err) {
    // Offline mode: update local stock directly
    items.forEach(it => {
      const art = S.articles.find(a => a.name.toLowerCase() === (it.matched_name || it.detected_name).toLowerCase());
      if (art) {
        if (art.qty !== undefined) art.qty += it.quantity;
        else art.stock = (art.stock || 0) + it.quantity;
      }
    });
    _saveArticles();
    S.spectra.results = items.map(it => ({ name: it.matched_name || it.detected_name, new_qty: it.quantity, unit: it.matched_unit || 'pce' }));
    S.spectra.step = 'done';
    showToast(t('spectraReceptionDone'), 'success');
    render();
  }
}

function spectraAdjustStock() {
  // Adjust local stock to match scanned quantities
  const detected = S.spectra.compareResults || [];
  let adjusted = 0;
  detected.forEach(d => {
    const art = S.articles.find(a => a.name.toLowerCase() === (d.matched_name || d.detected_name).toLowerCase());
    if (art) {
      if (art.qty !== undefined) art.qty = d.quantity;
      else art.stock = d.quantity;
      adjusted++;
    }
  });
  _saveArticles();
  showToast(`${t('spectraAdjust')}: ${adjusted} ${t('articles').toLowerCase()}`, 'success');
  spectraReset();
  nav('pantry');
}

function spectraSignalLoss() {
  const detected = S.spectra.compareResults || [];
  const artMap = {};
  S.articles.forEach(a => { artMap[a.name.toLowerCase()] = a; });
  const losses = [];
  detected.forEach(d => {
    const art = artMap[(d.matched_name || d.detected_name).toLowerCase()];
    if (art) {
      const stk = art.qty !== undefined ? art.qty : art.stock;
      if (d.quantity < stk) losses.push({ name: art.name, diff: stk - d.quantity });
    }
  });
  S.articles.forEach(a => {
    const stk = a.qty !== undefined ? a.qty : a.stock;
    if (!detected.some(d => (d.matched_name || d.detected_name).toLowerCase() === a.name.toLowerCase()) && stk > 0) {
      losses.push({ name: a.name, diff: stk });
    }
  });
  const totalLoss = losses.reduce((s,l) => s + l.diff, 0);
  const msg = losses.map(l => `${l.name}: -${l.diff}`).join('\n');
  const date = new Date().toLocaleString();
  const report = `${t('spectraSignalLoss')} — ${date}\n${t('spectraGap')}: ${totalLoss} ${t('spectraGapMsg')}\n\n${msg}`;
  // Save to localStorage as loss report
  const reports = JSON.parse(localStorage.getItem('baro_loss_reports') || '[]');
  reports.unshift({ date, items: losses, total: totalLoss });
  localStorage.setItem('baro_loss_reports', JSON.stringify(reports.slice(0, 50)));
  showToast(`${t('spectraSignalLoss')}: ${totalLoss} ${t('articles').toLowerCase()}`, 'error');
  // Try to share the report
  if (navigator.share) {
    navigator.share({ title: t('spectraSignalLoss'), text: report }).catch(() => {});
  }
  spectraReset();
}

// ── PURCHASE ORDERS ──────────────────────────
function vPurchaseOrders() {
  const orders = S.purchaseOrders;
  const sym = S.session?.currency_symbol || 'FCFA';
  return `
  <div class="sub-hero">
    <button class="back-btn-dark" style="margin-bottom:14px" onclick="nav('more')">${IC.left}</button>
    <div class="sub-hero-title">${t('purchaseOrders')}</div>
    <div class="sub-hero-sub">${orders.length} ${t('articles').toLowerCase()}</div>
  </div>
  <div class="container">
    <button class="btn btn-primary" style="margin-bottom:12px" onclick="nav('add-order')">
      ${IC.plus} &nbsp; ${t('newOrder')}
    </button>
    ${orders.length === 0 ? `
    <div class="empty-state">
      ${IC.truck}
      <div class="empty-title">${t('noOrders')}</div>
    </div>` : orders.map((o, i) => {
      const stColor = o.status === 'received' ? 'var(--success)' : o.status === 'cancelled' ? 'var(--danger)' : 'var(--warning)';
      const stLabel = o.status === 'received' ? t('orderReceived') : o.status === 'cancelled' ? t('orderCancelled') : t('orderPending');
      return `
    <div class="card anim" style="margin-bottom:6px;border-left:3px solid ${stColor};animation-delay:${i*0.03}s">
      <div style="display:flex;justify-content:space-between;align-items:flex-start">
        <div>
          <div style="font-weight:700;font-size:14px">${o.articleName}</div>
          <div style="font-size:11px;color:var(--text-3)">${o.supplierName || '—'} · ${fmtDate(o.date)}</div>
          <div style="display:inline-block;margin-top:4px;padding:2px 8px;border-radius:6px;background:${stColor}20;color:${stColor};font-size:10px;font-weight:700">${stLabel}</div>
        </div>
        <div style="text-align:right">
          <div style="font-weight:800;font-size:14px">${o.qty} ${o.unit||'pce'}</div>
          ${o.total ? `<div style="font-size:11px;color:var(--text-3)">${fmt(o.total)} ${sym}</div>` : ''}
        </div>
      </div>
      ${o.status === 'pending' ? `
      <div style="display:flex;gap:6px;margin-top:8px">
        <button class="btn btn-primary" style="flex:1;font-size:11px;padding:8px" onclick="receiveOrder(${o.id})">${IC.check} &nbsp; ${t('markReceived')}</button>
        <button class="btn btn-ghost" style="font-size:11px;padding:8px;color:var(--danger)" onclick="cancelOrder(${o.id})">${IC.xmark}</button>
      </div>` : ''}
    </div>`;
    }).join('')}
  </div>`;
}

function vAddOrder() {
  const sym = S.session?.currency_symbol || 'FCFA';
  return `
  <div class="sub-hero">
    <button class="back-btn-dark" style="margin-bottom:14px" onclick="nav('purchase-orders')">${IC.left}</button>
    <div class="sub-hero-title">${t('newOrder')}</div>
  </div>
  <div class="container">
    <div class="card" style="padding:16px">
      <div class="form-group">
        <label class="form-label">${t('orderArticle')} *</label>
        <select class="input" id="ord-article">
          <option value="">${t('select')}</option>
          ${S.articles.map(a => `<option value="${a.id}">${a.name} (${a.qty !== undefined ? a.qty : a.stock} ${a.unit||'pce'})</option>`).join('')}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label">${t('orderSupplier')}</label>
        <select class="input" id="ord-supplier">
          <option value="">—</option>
          ${S.suppliers.map(s => `<option value="${s.id}">${s.name}</option>`).join('')}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label">${t('orderQty')} *</label>
        <input class="input" id="ord-qty" type="number" min="1" value="1">
      </div>
      <div class="form-group">
        <label class="form-label">${t('orderTotal')} (${sym})</label>
        <input class="input" id="ord-total" type="number" min="0" placeholder="0">
      </div>
      <div class="form-group">
        <label class="form-label">${t('deliveryDays')||'Delai de livraison (jours)'}</label>
        <input class="input" id="ord-lead" type="number" min="1" value="7" placeholder="7">
      </div>
      <div class="form-group">
        <label class="form-label">${t('zza_dateLivEstim')}</label>
        <input class="input" id="ord-delivery-date" type="date" value="${new Date(Date.now()+7*86400000).toISOString().slice(0,10)}">
      </div>
      <div class="form-group">
        <label class="form-label">Notes / Remarques</label>
        <textarea class="input" id="ord-notes" rows="2" placeholder="Informations supplementaires..." style="resize:vertical"></textarea>
      </div>
      <button class="btn btn-primary" style="width:100%;margin-top:8px" onclick="saveOrder()">
        ${IC.check} &nbsp; ${t('newOrder')}
      </button>
    </div>
  </div>`;
}

function saveOrder() {
  const artEl = document.getElementById('ord-article');
  const artId = artEl?.value;
  if (!artId) { showToast(t('chooseProduct'), 'error'); return; }
  const art = S.articles.find(a => a.id === parseInt(artId));
  const supEl = document.getElementById('ord-supplier');
  const sup = S.suppliers.find(s => s.id === parseInt(supEl?.value));
  const qty = parseInt(document.getElementById('ord-qty')?.value) || 1;
  const total = parseFloat(document.getElementById('ord-total')?.value) || 0;
  const leadDays = parseInt(document.getElementById('ord-lead')?.value) || 7;
  const deliveryDate = document.getElementById('ord-delivery-date')?.value || new Date(Date.now()+leadDays*86400000).toISOString().slice(0,10);
  const notes = document.getElementById('ord-notes')?.value?.trim() || '';
  const order = {
    id: Date.now(),
    articleId: art?.id, articleName: art?.name || '?', unit: art?.unit || 'pce',
    supplierId: sup?.id || null, supplierName: sup?.name || '',
    qty, total, status: 'pending',
    leadDays, deliveryDate, notes,
    date: new Date().toISOString(),
  };
  S.purchaseOrders.unshift(order);
  localStorage.setItem('baro_orders', JSON.stringify(S.purchaseOrders));
  showToast(t('newOrder') + ' OK');
  nav('purchase-orders');
}

function receiveOrder(id) {
  const order = S.purchaseOrders.find(o => o.id === id);
  if (!order) return;
  order.status = 'received';
  order.receivedDate = new Date().toISOString();
  // Add stock
  const art = S.articles.find(a => a.id === order.articleId);
  if (art) {
    if (art.qty !== undefined) art.qty += order.qty;
    else art.stock = (art.stock || 0) + order.qty;
    _saveArticles();
    logMovement(art.name, 'entry', order.qty, t('purchaseOrders') + ': ' + (order.supplierName || ''));
  }
  localStorage.setItem('baro_orders', JSON.stringify(S.purchaseOrders));
  showToast(t('orderReceived') + ': +' + order.qty + ' ' + order.articleName, 'success');
  render();
}

function cancelOrder(id) {
  const order = S.purchaseOrders.find(o => o.id === id);
  if (order) { order.status = 'cancelled'; }
  localStorage.setItem('baro_orders', JSON.stringify(S.purchaseOrders));
  render();
}

