function saveBillingLinks() {
  const get = id => (document.getElementById(id)?.value || '').trim();
  const data = {};
  for (const p of ['starter','pro','enterprise']) {
    data[p] = { monthly: get('bl-'+p+'-monthly'), yearly: get('bl-'+p+'-yearly') };
  }
  localStorage.setItem('baro_billing_links', JSON.stringify(data));
  showToast('✅ Liens de paiement enregistrés', 'success');
  haptic('success');
  nav('pricing');
}

// Le tarif d'un forfait est un montant en francs CFA. Il ne passe donc
// pas par fmt(), qui suit la devise d'affichage du commercant et
// changerait le nombre de decimales sans changer le montant.
function _prixPlan(n) {
  return Math.round(n).toLocaleString(_loc());
}

// L'equivalent approximatif, seulement quand le commercant ne travaille
// pas en francs CFA. « Environ », parce que le taux bouge et que le
// prelevement, lui, se fera bien en francs CFA.
function _equivalentPlan(prixFcfa, billing) {
  const dev = S.session?.currency || 'XOF';
  if (dev === 'XOF' || dev === 'XAF') return '';
  const info = (typeof _tauxEntre === 'function') ? _tauxEntre('XOF', dev) : null;
  if (!info || !info.valeur) return '';
  const v = prixFcfa / info.valeur;
  const dec = _decimalesDe(dev);
  const txt = v.toLocaleString(_loc(), { minimumFractionDigits: dec, maximumFractionDigits: dec });
  return `<div style="font-size:11.5px;color:var(--text-3);margin:-8px 0 12px">
    ${t('zt_environ').replace('{0}', txt + ' ' + getCurrencySymbol(dev))
      .replace('{1}', billing === 'yearly' ? t('zs_an') : t('zs_mois'))}
  </div>`;
}

function _planFeatures(plan) {
  // Les chiffres restent des chiffres ; seuls les mots passent par les
  // traductions. « {0} » recoit la quantite pour que l'ordre des mots
  // reste naturel dans les deux langues.
  const q = (cle, n) => t(cle).replace('{0}', n);
  if (plan === 'free') return [
    q('zs_articlesN', 50), q('zs_ventesMoisN', 100),
    q('zs_emplacementN', 1), q('zs_spectraJour', 10),
    t('zs_facturesPdf'), t('zs_horsLigne'),
    t('zs_supportWa'),
  ];
  if (plan === 'starter') return [
    q('zs_articlesN', 500), q('zs_ventesMoisN', 2000),
    q('zs_emplacementsN', 2), q('zs_spectraJour', 50),
    t('zs_facturesPerso'), t('exportCSV'),
    t('zs_waCatalogue'), q('zs_fournisseursN', 10),
    q('zs_paiementsN', 3),
    t('zs_sauvegarde'),
  ];
  if (plan === 'pro') return [
    t('unlimited')+' '+t('zs_articles'), t('unlimited')+' '+t('zs_ventes'),
    q('zs_emplacementsN', 5), t('zs_spectraIllimite'),
    'WhatsApp '+t('catalog'), t('purchaseOrders'), t('zs_fournisseursIll'),
    t('exportCSV')+' + Excel', t('zs_boutiqueEnLigne'),
    t('zs_marketing'), q('zs_integrationsN', 10),
    t('zs_rapportsAvances'), t('zs_tousPaiements'),
    t('zs_fidelite'),
  ];
  if (plan === 'enterprise') return [
    t('unlimited')+' '+t('zs_articles'), t('unlimited')+' '+t('zs_ventes'),
    t('unlimited')+' '+t('zs_emplacements'), 'Spectra '+t('unlimited')+' + '+t('zs_iaAvancee'),
    t('zs_apiRest'), t('zs_multiUtilisateurs'),
    t('zs_support247'), t('zs_accountManager'),
    t('zs_roles'), t('zs_integrationsIll'),
    t('zs_boutiqueDomaine'), t('zs_fideliteAvancee'),
    t('zs_exportOhada'), 'SLA 99.9%',
    t('zs_formation'),
  ];
  return _planFeatures('free');
}

