function saveEmailJSConfig() {
  const svc = document.getElementById('emailjs-service')?.value?.trim();
  const tpl = document.getElementById('emailjs-template')?.value?.trim();
  const pub = document.getElementById('emailjs-public')?.value?.trim();
  if (!svc || !tpl || !pub) { showToast('Renseignez les 3 champs', 'error'); return; }
  localStorage.setItem('stockr_emailjs_service', svc);
  localStorage.setItem('stockr_emailjs_template', tpl);
  localStorage.setItem('stockr_emailjs_public', pub);
  showToast('✅ EmailJS configuré — envoi email réel activé', 'success');
  render();
}

function saveSMSConfig() {
  const url = document.getElementById('sms-webhook')?.value?.trim();
  const key = document.getElementById('sms-apikey')?.value?.trim();
  if (!url) { showToast('Entrez une URL webhook', 'error'); return; }
  if (!/^https?:\/\//.test(url)) { showToast('URL invalide (doit commencer par http/https)', 'error'); return; }
  localStorage.setItem('stockr_sms_webhook', url);
  if (key) localStorage.setItem('stockr_sms_apikey', key); else localStorage.removeItem('stockr_sms_apikey');
  showToast('✅ SMS webhook configuré', 'success');
  render();
}

async function testVerificationEmail() {
  const email = (S.security?.twoFactorEmail || S.session?.email || '').trim();
  if (!email) { showToast('Configurez d\'abord votre email', 'error'); return; }
  const code = String(Math.floor(100000 + Math.random() * 900000));
  showToast('🧪 Envoi en cours...', 'info');
  const r = await _sendVerificationEmail(email, code, 'Test BARO');
  if (r.ok) showToast('✅ Email envoyé à ' + email + ' — code : ' + code, 'success');
  else if (r.reason === 'emailjs_not_configured') {
    if (confirm('EmailJS non configuré.\n\nOuvrir votre app mail avec le code pré-rempli ?')) {
      _openMailtoVerification(email, code);
    }
  } else {
    showToast('❌ Erreur : ' + (r.reason || 'inconnue'), 'error');
  }
}

async function testVerificationSMS() {
  const phone = (S.security?.twoFactorPhone || '').trim();
  if (!phone) { showToast('Entrez un numéro', 'error'); return; }
  const code = String(Math.floor(100000 + Math.random() * 900000));
  showToast('🧪 Envoi en cours...', 'info');
  const r = await _sendVerificationSMS(phone, code, 'Test BARO');
  if (r.ok) showToast('✅ SMS envoyé à ' + phone + ' — code : ' + code, 'success');
  else if (r.reason === 'sms_not_configured') {
    if (confirm('Aucun webhook SMS configuré.\n\nOuvrir l\'app SMS avec le code pré-rempli ?')) {
      _openSmsVerification(phone, code);
    }
  } else {
    showToast('❌ Erreur : ' + (r.reason || 'inconnue'), 'error');
  }
}

function vAuditLog() {
  if (!hasPermission('audit') && !hasPermission('all')) {
    return `
    <div class="page-header"><div class="page-header-row">
      <button class="back-btn" onclick="nav('more')">${IC.left}</button>
      <div class="page-title">${t('auditLogTitle')}</div>
    </div></div>
    <div class="container"><div class="card" style="text-align:center;padding:40px 20px">${t('auditAccessDenied')}</div></div>`;
  }

  const filter = S.auditFilter || 'all';
  const period = S.auditPeriod || 'all';
  const now = Date.now();
  const periodStart = period === 'today' ? now - 24*3600*1000
                    : period === 'week'  ? now - 7*24*3600*1000
                    : period === 'month' ? now - 30*24*3600*1000
                    : 0;

  const filtered = (S.auditLog || []).filter(e => {
    if (filter !== 'all' && e.category !== filter) return false;
    if (periodStart > 0 && new Date(e.ts).getTime() < periodStart) return false;
    return true;
  });

  const catColors = {
    sale: '#10B981', stock: '#F59E0B', member: '#7C73FF', auth: '#EF4444',
    settings: '#64748B', product: '#0EA5E9', client: '#EC4899'
  };
  const catIcons = {
    sale: '💰', stock: '📦', member: '👤', auth: '🔐',
    settings: '⚙️', product: '🏷️', client: '👥'
  };
  const locale = _lang === 'en' ? 'en-US' : 'fr-FR';

  return `
  <div class="sub-hero" style="background:linear-gradient(135deg,#1E293B,#0F172A)">
    <button class="back-btn-dark" style="margin-bottom:14px" onclick="nav('more')">${IC.left}</button>
    <div class="sub-hero-title">📋 ${t('auditLogTitle')}</div>
    <div class="sub-hero-sub">${filtered.length} ${t('auditEventCount')} · ${t('auditLogSub')}</div>
  </div>
  <div class="container">

    <!-- Filtres période -->
    <div style="display:flex;gap:6px;margin-bottom:10px;overflow-x:auto">
      ${[['all',t('auditAll')],['today',t('auditToday')],['week',t('auditWeek')],['month',t('auditMonth')]].map(([v,lbl]) => `
        <button class="filter-chip ${period===v?'active':''}" onclick="S.auditPeriod='${v}';render()" style="white-space:nowrap;font-size:12px">${lbl}</button>
      `).join('')}
    </div>

    <!-- Filtres catégorie -->
    <div style="display:flex;gap:6px;margin-bottom:14px;overflow-x:auto">
      ${[['all',t('auditCatAll')],['sale',t('auditCatSale')],['stock',t('auditCatStock')],['member',t('auditCatMember')],['auth',t('auditCatAuth')],['settings',t('auditCatSettings')]].map(([v,lbl]) => `
        <button class="filter-chip ${filter===v?'active':''}" onclick="S.auditFilter='${v}';render()" style="white-space:nowrap;font-size:11px">${lbl}</button>
      `).join('')}
    </div>

    ${filtered.length === 0 ? `
      <div class="card" style="text-align:center;padding:40px 20px">
        <div style="font-size:48px;margin-bottom:10px">📭</div>
        <div style="font-size:14px;font-weight:700;color:var(--text-1)">${t('auditNoEvents')}</div>
        <div style="font-size:12px;color:var(--text-3);margin-top:6px">${t('auditNoEventsSub')}</div>
      </div>
    ` : `
      <div class="card" style="padding:0;overflow:hidden">
        ${filtered.slice(0, 200).map(e => {
          const color = catColors[e.category] || '#64748B';
          const icon = catIcons[e.category] || '•';
          const dt = new Date(e.ts);
          const dateStr = dt.toLocaleDateString(locale, { day:'2-digit', month:'short' });
          const timeStr = dt.toLocaleTimeString(locale, { hour:'2-digit', minute:'2-digit' });
          const detailsStr = Object.entries(e.details || {})
            .map(([k, v]) => `<strong>${_translateAuditDetailKey(k)}</strong>: ${v}`)
            .join(' · ');
          return `
          <div style="display:flex;gap:10px;padding:12px 14px;border-bottom:1px solid var(--border)">
            <div style="width:36px;height:36px;border-radius:18px;background:${color}15;color:${color};display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0">${icon}</div>
            <div style="flex:1;min-width:0">
              <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
                <span style="font-weight:700;font-size:13px;color:var(--text-1)">${e.memberName || 'Admin'}</span>
                <span style="font-size:10px;padding:1px 6px;background:${color}15;color:${color};border-radius:4px;font-weight:700;text-transform:uppercase">${_translateAuditAction(e.action)}</span>
                <span style="font-size:11px;color:var(--text-3)">${_translateAuditCategory(e.category)}</span>
              </div>
              ${detailsStr ? `<div style="font-size:11px;color:var(--text-2);margin-top:2px;word-break:break-word">${detailsStr}</div>` : ''}
              <div style="font-size:10px;color:var(--text-3);margin-top:3px">${dateStr} · ${timeStr}</div>
            </div>
          </div>`;
        }).join('')}
      </div>
      ${filtered.length > 200 ? `<div style="text-align:center;font-size:11px;color:var(--text-3);margin-top:10px">${t('auditDisplayLimited')} (${filtered.length})</div>` : ''}
      <div style="display:flex;gap:8px;margin-top:14px">
        <button class="btn btn-ghost" style="flex:1" onclick="exportAuditLogCSV()">${t('auditExportCSV')}</button>
        ${hasPermission('all') ? `<button class="btn" style="flex:1;background:#EF4444;color:#fff" onclick="clearAuditLog()">${t('auditPurge')}</button>` : ''}
      </div>
    `}
  </div>`;
}

// Traductions actions/catégories audit (couverture COMPLÈTE)
function _translateAuditAction(action) {
  if (!action) return '';
  const FR = {
    // CRUD génériques
    create:'Créer', update:'Modifier', delete:'Supprimer',
    // Auth
    login:'Connexion', login_success:'Connexion réussie', login_failed:'Connexion échouée',
    logout:'Déconnexion', register:'Inscription',
    '2fa_success':'2FA réussi', '2fa_failed':'2FA échoué',
    google_attempt:'Google OAuth', apple_attempt:'Apple Sign-In',
    biometric_enrolled:'Biométrie activée', biometric_success:'Biométrie réussie', biometric_failed:'Biométrie échouée',
    pin_failed:'PIN incorrect', member_switch:'Changement utilisateur',
    // Ventes
    sale:'Vente', refund:'Remboursement',
    // Stock
    stock_in:'Entrée stock', stock_out:'Sortie stock', transfer:'Transfert',
    delete_article:'Article supprimé',
    // Approbations
    approve:'Approuver', reject:'Rejeter', activate:t('v_activer'), deactivate:'Désactiver',
    // Import/Export
    'export':'Exporter', 'import':'Importer', clear_audit_log:'Purge journal',
    import_shopify:'Import Shopify', import_woocommerce:'Import WooCommerce',
    ecom_update_shopify:'Màj Shopify', ecom_update_woocommerce:'Màj WooCommerce',
    sync_shopify:'Synchro Shopify', sync_woocommerce:'Synchro WooCommerce',
    // Settings / vidéo
    demo_seeded:'Démo chargée', appearance_change:'Apparence modifiée', security_change:'Sécurité modifiée',
    video_saved:'Vidéo enregistrée', video_published:'Vidéo publiée', youtube_upload:'Upload YouTube',
    // Équipe
    meeting_created:'Réunion créée', meeting_updated:'Réunion modifiée', meeting_deleted:'Réunion supprimée',
    task_created:'Tâche créée', announcement_created:'Annonce créée',
  };
  const EN = {
    create:'Create', update:'Update', delete:'Delete',
    login:'Login', login_success:'Login success', login_failed:'Login failed',
    logout:'Logout', register:'Register',
    '2fa_success':'2FA success', '2fa_failed':'2FA failed',
    google_attempt:'Google OAuth', apple_attempt:'Apple Sign-In',
    biometric_enrolled:'Biometric enrolled', biometric_success:'Biometric success', biometric_failed:'Biometric failed',
    pin_failed:'PIN incorrect', member_switch:'User switch',
    sale:'Sale', refund:'Refund',
    stock_in:'Stock in', stock_out:'Stock out', transfer:'Transfer',
    delete_article:'Article deleted',
    approve:'Approve', reject:'Reject', activate:'Activate', deactivate:'Deactivate',
    'export':'Export', 'import':'Import', clear_audit_log:'Purge log',
    import_shopify:'Shopify import', import_woocommerce:'WooCommerce import',
    ecom_update_shopify:'Shopify update', ecom_update_woocommerce:'WooCommerce update',
    sync_shopify:'Shopify sync', sync_woocommerce:'WooCommerce sync',
    demo_seeded:'Demo loaded', appearance_change:'Appearance updated', security_change:'Security updated',
    video_saved:'Video saved', video_published:'Video published', youtube_upload:'YouTube upload',
    meeting_created:'Meeting created', meeting_updated:'Meeting updated', meeting_deleted:'Meeting deleted',
    task_created:'Task created', announcement_created:'Announcement created',
  };
  const map = _lang === 'en' ? EN : FR;
  if (map[action]) return map[action];
  // Fallback : humanise les actions inconnues (snake_case → Capitalized)
  return action.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}
function _translateAuditCategory(cat) {
  if (!cat) return '';
  const FR = { sale:t('zy_ventes'), stock:t('z5_stock'), member:t('u_equipe'), team:t('u_equipe'), auth:t('zz5_authentification'),
               settings:t('zz5_parametres'), product:t('zx_produits'), client:t('zy_clients'),
               plan:t('zzd_abonnement'), promo:'Promo', supplier:t('zzd_fournisseurs'), order:t('w1_lienCommandes'),
               integration:'Intégration', marketing:'Marketing', boutique:'Boutique' };
  const EN = { sale:'Sales', stock:'Stock', member:'Team', team:'Team', auth:'Auth',
               settings:'Settings', product:'Products', client:'Clients',
               plan:'Plan', promo:'Promo', supplier:'Suppliers', order:'Orders',
               integration:'Integration', marketing:'Marketing', boutique:'Shop' };
  const map = _lang === 'en' ? EN : FR;
  if (map[cat]) return map[cat];
  return cat.charAt(0).toUpperCase() + cat.slice(1);
}

// Traduit les clés de details (email, bt, amount, etc.) dans la langue sélectionnée
function _translateAuditDetailKey(key) {
  if (!key) return '';
  const FR = {
    email:'Email', phone:'Téléphone', bt:'Profil', businessType:'Profil', verified:'Vérifié',
    amount:'Montant', total:'Total', client:'Client', method:'Mode', product:'Produit', qty:'Qté',
    name:'Nom', before:'Avant', after:'Après', reason:'Raison', role:'Rôle',
    target:'Cible', vidId:'ID Vidéo', count:'Nombre', ref:'Ref', status:'Statut',
  };
  const EN = {
    email:'Email', phone:'Phone', bt:'Profile', businessType:'Profile', verified:'Verified',
    amount:'Amount', total:'Total', client:'Client', method:'Method', product:'Product', qty:'Qty',
    name:'Name', before:'Before', after:'After', reason:'Reason', role:'Role',
    target:'Target', vidId:'Video ID', count:'Count', ref:'Ref', status:'Status',
  };
  const map = _lang === 'en' ? EN : FR;
  if (map[key]) return map[key];
  return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

function exportAuditLogCSV() {
  const locale = _lang === 'en' ? 'en-US' : 'fr-FR';
  const headers = _lang === 'en'
    ? ['ID','Date','Time','Member','Role','Category','Action','Details']
    : ['ID','Date','Heure','Membre','Rôle','Catégorie','Action','Détails'];
  const rows = [headers];
  (S.auditLog || []).forEach(e => {
    const dt = new Date(e.ts);
    rows.push([
      e.id,
      dt.toLocaleDateString(locale),
      dt.toLocaleTimeString(locale),
      e.memberName || '',
      e.memberRole || '',
      _translateAuditCategory(e.category) || '',
      _translateAuditAction(e.action) || '',
      JSON.stringify(e.details || {}).replace(/"/g, '""'),
    ]);
  });
  const csv = rows.map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `baro_audit_${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
  showToast(t('auditExported'), 'success');
}

function clearAuditLog() {
  if (!confirm(t('auditConfirmPurge'))) return;
  S.auditLog = [];
  localStorage.setItem('stockr_audit_log', JSON.stringify([]));
  logAudit('settings', 'clear_audit_log', { cleared: true });
  showToast(t('auditPurged'), 'info');
  render();
}

// ── APPEARANCE VIEW ────────────────────────────
// Chaque bloc dit à quel forfait il appartient. Un réglage verrouillé
// reste visible et manipulable du regard : on voit ce qu'on aurait,
// on n'est pas devant une porte fermée sans fenêtre.
function _blocRegl(titre, aide, corps, minPlan) {
  const ouvert = !minPlan || _planHasFeature(minPlan === 'enterprise' ? 'whiteLabel' : 'loyalty');
  const badge = ouvert ? '' :
    `<span class="rg-lock" onclick="_showPlanFeatureModal('${minPlan === 'enterprise' ? 'whiteLabel' : 'loyalty'}')">${
      minPlan === 'enterprise' ? t('zv_planEntreprise') : 'Pro'}</span>`;
  return `
    <div class="card rg-card${ouvert ? '' : ' rg-off'}" style="margin-bottom:12px">
      <div class="rg-head">
        <div class="card-title" style="margin:0">${titre}</div>
        ${badge}
      </div>
      ${aide ? `<div class="rg-aide">${aide}</div>` : ''}
      ${corps}
    </div>`;
}

// Un choix parmi n. Le même dessin partout, au lieu de six variantes de
// bouton écrites à la main dans l'ancien écran.
function _choix(setter, cle, actuel, options, cols) {
  return `<div class="rg-grid" style="grid-template-columns:repeat(${cols || options.length},1fr)">` +
    options.map(o => {
      const on = String(actuel) === String(o.v);
      return `<button class="rg-opt${on ? ' on' : ''}" onclick="${setter}('${cle}','${o.v}')">
        ${o.haut || ''}<span class="rg-lbl">${o.l}</span>
      </button>`;
    }).join('') + '</div>';
}

