function addBoutiqueFAQ() {
  const q = prompt('Question :');
  if (!q) return;
  const a = prompt('Réponse :');
  if (!a) return;
  S.boutiqueConfig.faqs = S.boutiqueConfig.faqs || [];
  S.boutiqueConfig.faqs.push({ q, a });
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  showToast('FAQ ajoutée ✓');
  render();
}
function editBoutiqueFAQ(i) {
  const f = S.boutiqueConfig.faqs[i];
  const q = prompt('Question :', f.q);
  if (!q) return;
  const a = prompt('Réponse :', f.a);
  if (!a) return;
  S.boutiqueConfig.faqs[i] = { q, a };
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  showToast('FAQ modifiée ✓');
  render();
}
function deleteBoutiqueFAQ(i) {
  if (!confirm('Supprimer cette FAQ ?')) return;
  S.boutiqueConfig.faqs.splice(i, 1);
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  showToast('FAQ supprimée');
  render();
}
function loadFAQPreset() {
  S.boutiqueConfig.faqs = [
    { q:'Comment passer commande ?', a:'Sélectionnez vos produits puis cliquez sur "Commander" — vous êtes redirigé vers WhatsApp pour finaliser.' },
    { q:'Quels sont les délais de livraison ?', a:`La livraison se fait en ${S.boutiqueConfig.deliveryTime||'24-48h'} selon votre zone.` },
    { q:'Quels moyens de paiement acceptez-vous ?', a:'Wave, Orange Money, MTN MoMo, Moov Money, espèces à la livraison.' },
    { q:'Puis-je retourner un produit ?', a:'Oui, vous disposez de 7 jours après réception pour retourner un produit non utilisé.' },
    { q:'Livrez-vous en dehors d\'Abidjan ?', a:`Oui, nous livrons dans ${(S.boutiqueConfig.deliveryZones||[]).length||'plusieurs'} zones. Contactez-nous pour confirmer.` },
  ];
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  showToast('Pack FAQ chargé ✓');
  render();
}

function addBoutiqueTestimonial() {
  const text = prompt('Témoignage du client :');
  if (!text) return;
  const author = prompt('Nom du client :') || 'Client satisfait';
  const stars = parseInt(prompt('Note (1-5) :', '5') || '5', 10);
  const location = prompt('Ville (optionnel) :') || '';
  S.boutiqueConfig.testimonials = S.boutiqueConfig.testimonials || [];
  S.boutiqueConfig.testimonials.push({ text, author, stars: Math.max(1, Math.min(5, stars)), location, date: new Date().toISOString() });
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  showToast('Témoignage ajouté ✓');
  render();
}
function deleteBoutiqueTestimonial(i) {
  if (!confirm('Supprimer ce témoignage ?')) return;
  S.boutiqueConfig.testimonials.splice(i, 1);
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  showToast('Témoignage supprimé');
  render();
}

function previewBoutiqueSite() {
  // Aperçu fidèle : exactement le même HTML que le site généré
  const html = generateBoutiqueSite({ preview: true });
  if (!html) return; // vitrine vide — toast déjà affiché
  const preview = window.open('', '_blank');
  if (!preview) { showToast('Autorisez les popups pour voir l\'aperçu', 'error'); return; }
  preview.document.write(html);
  preview.document.close();
}
function toggleBoutiqueProduct(id) {
  if (!S.boutiqueConfig.products) S.boutiqueConfig.products = [];
  const idx = S.boutiqueConfig.products.indexOf(id);
  if (idx >= 0) S.boutiqueConfig.products.splice(idx, 1);
  else S.boutiqueConfig.products.push(id);
  localStorage.setItem('baro_boutique', JSON.stringify(S.boutiqueConfig));
  render();
}
function toggleBoutiqueArticle(id) {
  if (!S.boutiqueConfig.articles) S.boutiqueConfig.articles = [];
  const idx = S.boutiqueConfig.articles.indexOf(id);
  if (idx >= 0) S.boutiqueConfig.articles.splice(idx, 1);
  else S.boutiqueConfig.articles.push(id);
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  render();
}
function toggleBoutiquePack(id) {
  if (!S.boutiqueConfig.packs) S.boutiqueConfig.packs = [];
  const idx = S.boutiqueConfig.packs.indexOf(id);
  if (idx >= 0) S.boutiqueConfig.packs.splice(idx, 1);
  else S.boutiqueConfig.packs.push(id);
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  render();
}
function selectAllBoutique(kind) {
  if (!S.boutiqueConfig) return;
  if (kind === 'products') {
    const all = (S.products||[]).map(p => p.id);
    const cur = S.boutiqueConfig.products || [];
    S.boutiqueConfig.products = (cur.length === all.length) ? [] : all;
  } else if (kind === 'packs') {
    const all = (S.packs||[]).filter(pk => pk.active !== false).map(pk => pk.id);
    const cur = S.boutiqueConfig.packs || [];
    S.boutiqueConfig.packs = (cur.length === all.length) ? [] : all;
  } else {
    const all = (S.articles||[]).filter(a => (a.qty||0) > 0).map(a => a.id);
    const cur = S.boutiqueConfig.articles || [];
    S.boutiqueConfig.articles = (cur.length === all.length) ? [] : all;
  }
  localStorage.setItem('stockr_boutique', JSON.stringify(S.boutiqueConfig));
  showToast((S.boutiqueConfig[kind]||[]).length > 0 ? '✓ Tout en vitrine' : '○ Vitrine vidée');
  render();
}
function toggleDeliveryZone(zone) {
  if (!S.boutiqueConfig.deliveryZones) S.boutiqueConfig.deliveryZones = [];
  const idx = S.boutiqueConfig.deliveryZones.indexOf(zone);
  if (idx >= 0) S.boutiqueConfig.deliveryZones.splice(idx, 1);
  else S.boutiqueConfig.deliveryZones.push(zone);
  // Nettoie le tarif spécifique d'une zone retirée
  if (idx >= 0 && S.boutiqueConfig.zoneFees) delete S.boutiqueConfig.zoneFees[zone];
  localStorage.setItem('baro_boutique', JSON.stringify(S.boutiqueConfig));
  render();
}
// Tarif de livraison spécifique à une zone (sans re-render → garde le focus clavier)
function updateBoutiqueZoneFee(zone, val) {
  if (!S.boutiqueConfig.zoneFees) S.boutiqueConfig.zoneFees = {};
  const n = parseFloat(val);
  if (val === '' || isNaN(n)) delete S.boutiqueConfig.zoneFees[zone];
  else S.boutiqueConfig.zoneFees[zone] = n;
  localStorage.setItem('baro_boutique', JSON.stringify(S.boutiqueConfig));
  if (typeof _refreshBoutiqueLivePreview === 'function') _refreshBoutiqueLivePreview();
}
function _getAllVitrineItems() {
  const bc = S.boutiqueConfig || {};
  const prods = (bt_showProducts() ? S.products : []).filter(p => (bc.products||[]).includes(p.id));
  const packs = (bt_showProducts() ? (S.packs||[]) : []).filter(pk => (bc.packs||[]).includes(pk.id) && pk.active !== false);
  const arts  = (bt_showStock()    ? (S.articles||[]) : []).filter(a => (bc.articles||[]).includes(a.id));
  return [
    ...prods.map(p => ({ id:p.id, name:p.name, price:p.price, description:p.description||'', kind:'product' })),
    ...packs.map(pk => ({ id:'pack_'+pk.id, name:'📦 '+pk.name, price:packFinalPrice(pk), description:pk.description||'Pack promo', kind:'pack' })),
    ...arts.map(a => ({ id:a.id, name:a.name, price:a.price||a.salePrice||0, description:a.description||`Stock: ${a.qty||0} ${a.unit||''}`, kind:'article' }))
  ];
}
function shareBoutiqueWhatsApp() {
  const bc = S.boutiqueConfig;
  const items = _getAllVitrineItems();
  const lines = [
    `🛍️ *${bc.name || S.session?.business || t('zz_maBoutique')}*`,
    bc.description || '', '',
    `📦 *Nos ${items.some(i=>i.kind==='product')?'produits':'articles'} :*`,
    ...items.map(p => `▸ ${p.name} — *${fmt(p.price)} ${sym()}*`),
    '', bc.deliveryFees > 0 ? `🚚 Livraison : ${fmt(bc.deliveryFees)} ${sym()}` : '🚚 Livraison gratuite',
    (bc.deliveryZones||[]).length > 0 ? `📍 Zones : ${bc.deliveryZones.join(', ')}` : '',
    '', '📲 Commandez maintenant !', '_Propulsé par BARO_'
  ];
  window.open('https://wa.me/?text=' + encodeURIComponent(lines.join('\n')), '_blank');
}
function copyBoutiqueLink() {
  const text = `${S.boutiqueConfig.name||S.session?.business||t('zz_maBoutique')} — Commandez sur WhatsApp !`;
  navigator.clipboard?.writeText(text).then(() => showToast(t('copied')||'Copie !'));
}
// URL publique de la boutique (domaine perso vérifié sinon sous-domaine .baro.shop)
function _boutiqueUrl() {
  const bc = S.boutiqueConfig || {};
  if (bc.customDomainVerified && bc.customDomain) return 'https://' + bc.customDomain;
  if (bc.domain) return 'https://' + bc.domain + '.baro.shop';
  return null;
}
// QR scannable de la boutique (généré en ligne via api.qrserver.com — URL publique)
function showBoutiqueQR() {
  const url = _boutiqueUrl();
  if (!url) { showToast('Choisissez d\'abord l\'URL de votre boutique', 'info'); nav('boutique-domain'); return; }
  const existing = document.getElementById('bq-qr-modal'); if (existing) existing.remove();
  const qrSrc = 'https://api.qrserver.com/v1/create-qr-code/?size=300x300&margin=12&data=' + encodeURIComponent(url);
  const safeUrl = url.replace(/'/g, "\\'");
  const modal = document.createElement('div');
  modal.id = 'bq-qr-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(6px);animation:fadeIn .2s ease';
  modal.onclick = (e) => { if (e.target === modal) modal.remove(); };
  modal.innerHTML = `<div style="background:var(--surface);border-radius:18px;max-width:340px;width:100%;padding:22px;text-align:center;box-shadow:0 25px 60px rgba(0,0,0,.35);animation:slideUp .25s ease">
    <div style="font-size:17px;font-weight:800;margin-bottom:4px">${IC.qrcode} QR de ma boutique</div>
    <div style="font-size:12px;color:var(--text-3);margin-bottom:14px">Affichez-le en boutique, sur vos flyers ou cartes : vos clients scannent et arrivent direct sur votre boutique en ligne.</div>
    <div style="background:#fff;border-radius:14px;padding:12px;display:inline-block;min-height:120px"><img src="${qrSrc}" alt="QR boutique" width="240" height="240" style="display:block;width:240px;height:240px" onerror="this.parentElement.innerHTML='<div style=\\'padding:40px 20px;color:#999;font-size:12px\\'>QR indisponible (connexion requise)</div>'"></div>
    <div style="font-size:12px;color:var(--accent);font-weight:600;margin:12px 0;word-break:break-all">${url}</div>
    <div style="display:flex;gap:8px">
      <button class="btn btn-ghost" style="flex:1" onclick="navigator.clipboard&&navigator.clipboard.writeText('${safeUrl}');showToast('Lien copié !')">📋 Copier</button>
      <button class="btn btn-primary" style="flex:1" onclick="window.open('${qrSrc}','_blank')">${t('x5_telechargerIcone')}</button>
    </div>
    <button class="btn" style="width:100%;margin-top:8px;background:#25D366;color:#fff" onclick="window.open('https://wa.me/?text='+encodeURIComponent(t('zze_decouvrezBq').replace('{0}','${safeUrl}')),'_blank')">${IC.whatsapp} ${t('zze_partagerLien')}</button>
    <button class="btn btn-ghost" style="width:100%;margin-top:6px;font-size:12px" onclick="document.getElementById('bq-qr-modal').remove()">${t('zg_fermer')}</button>
  </div>`;
  document.body.appendChild(modal);
}
// Partage d'UN produit via WhatsApp (nom, prix, description, lien boutique)
function shareProductLink(itemId) {
  const it = (S.articles||[]).find(x => String(x.id) === String(itemId)) || (S.products||[]).find(x => String(x.id) === String(itemId));
  if (!it) { showToast('Produit introuvable', 'error'); return; }
  const url = _boutiqueUrl();
  const biz = S.session?.business || 'notre boutique';
  const lines = [`*${it.name}* — ${fmt(it.price||0)} ${sym()}`];
  if (it.description) lines.push(it.description);
  lines.push('', `Disponible chez ${biz} 🛍️`);
  if (url) lines.push('🛒 Commander : ' + url);
  window.open('https://wa.me/?text=' + encodeURIComponent(lines.join('\n')), '_blank');
  if (typeof haptic === 'function') haptic('tap');
}

// ══════════════════════════════════════════════════════════════
// OPTIONS BOUTIQUE D'UN PRODUIT — photos supplémentaires + variantes
// ══════════════════════════════════════════════════════════════
function _optItem() {
  const id = S._optId;
  return (S.articles||[]).find(x => String(x.id) === String(id)) || (S.products||[]).find(x => String(x.id) === String(id));
}
function _persistProductObj(a) {
  if ((S.articles||[]).some(x => x.id === a.id)) {
    _saveArticles();
    try { _saveArticles(); } catch(_){}
  } else {
    localStorage.setItem('baro_products', JSON.stringify(S.products));
    try { localStorage.setItem('stockr_products', JSON.stringify(S.products)); } catch(_){}
  }
}
function openProductOptions(id) {
  const a = (S.articles||[]).find(x => String(x.id) === String(id)) || (S.products||[]).find(x => String(x.id) === String(id));
  if (!a) return;
  if (!Array.isArray(a.images)) a.images = [];
  if (!Array.isArray(a.variants)) a.variants = [];
  if (!Array.isArray(a.reviews)) a.reviews = [];
  S._optId = id;
  _renderProductOptions();
}
function _renderProductOptions() {
  const a = _optItem(); if (!a) return;
  const ex = document.getElementById('po-modal'); if (ex) ex.remove();
  const modal = document.createElement('div');
  modal.id = 'po-modal';
  modal.className = 'qs-overlay';
  modal.onclick = (e) => { if (e.target === modal) modal.remove(); };
  modal.innerHTML = `<div class="qs-sheet">${_poBody(a)}</div>`;
  document.body.appendChild(modal);
}
function _poBody(a) {
  const imgs = a.images || [], variants = a.variants || [], reviews = a.reviews || [];
  return `
    <div class="qs-head"><div style="flex:1;min-width:0"><div class="qs-title">🛍️ Options boutique</div><div class="qs-sub">${(a.name||'').replace(/</g,'&lt;')}</div></div><button class="qs-x" onclick="document.getElementById('po-modal').remove()">✕</button></div>
    <div class="qs-label">${t('x5_photosPremiere')}</div>
    <div class="po-imgs">
      ${a.image ? `<div class="po-img" style="background-image:url('${a.image}')"><span class="po-main">Principale</span></div>` : ''}
      ${imgs.map((u,i) => `<div class="po-img" style="background-image:url('${u}')"><button class="po-del" onclick="_poDelImg(${i})">×</button></div>`).join('')}
      <button class="po-add" onclick="_poAddImg()">＋<span style="font-size:10px;display:block">photo</span></button>
    </div>
    <div class="qs-label" style="margin-top:14px">Variantes (taille, couleur…)</div>
    ${variants.map((v,i) => `<div class="po-var">
      <input class="input po-var-name" value="${(v.name||'').replace(/"/g,'&quot;')}" placeholder="Nom (ex: Taille)" oninput="_poVarName(${i},this.value)">
      <input class="input po-var-opts" value="${(v.options||[]).join(', ').replace(/"/g,'&quot;')}" placeholder="S, M, L, XL" oninput="_poVarOpts(${i},this.value)">
      <button class="po-del2" onclick="_poDelVar(${i})">🗑</button>
    </div>`).join('')}
    <button class="btn btn-ghost" style="width:100%;font-size:13px;margin-top:4px" onclick="_poAddVar()">${t('x5_ajouterVariante')}</button>
    <div class="qs-label" style="margin-top:14px">Avis clients ⭐</div>
    ${reviews.map((r,i) => `<div class="po-rev">
      <div style="display:flex;gap:6px;align-items:center">
        <input class="input" value="${(r.author||'').replace(/"/g,'&quot;')}" placeholder="${t('v_nomClient')}" oninput="_poRevField(${i},'author',this.value)" style="flex:1">
        <select class="input" onchange="_poRevField(${i},'rating',this.value)" style="width:64px;flex:0 0 auto">${[5,4,3,2,1].map(n=>`<option value="${n}" ${(+r.rating||5)===n?'selected':''}>${n}★</option>`).join('')}</select>
        <button class="po-del2" onclick="_poDelReview(${i})">🗑</button>
      </div>
      <textarea class="input" rows="2" placeholder="Commentaire (ex: Très bon produit, conforme…)" oninput="_poRevField(${i},'text',this.value)" style="margin-top:6px;font-size:13px;resize:none">${(r.text||'').replace(/</g,'&lt;')}</textarea>
    </div>`).join('')}
    <button class="btn btn-ghost" style="width:100%;font-size:13px;margin-top:4px" onclick="_poAddReview()">${t('x5_ajouterAvisPlus')}</button>
    <button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="_poSave()">✓ ${t('save')}</button>`;
}
function _poAddImg() { pickItemImage(d => { const a = _optItem(); if (!a) return; if (!a.images) a.images = []; a.images.push(d); _renderProductOptions(); }); }
function _poDelImg(i) { const a = _optItem(); if (a && a.images) { a.images.splice(i,1); _renderProductOptions(); } }
function _poAddVar() { const a = _optItem(); if (!a.variants) a.variants = []; a.variants.push({ name:'', options:[] }); _renderProductOptions(); }
function _poDelVar(i) { const a = _optItem(); if (a && a.variants) { a.variants.splice(i,1); _renderProductOptions(); } }
function _poVarName(i, v) { const a = _optItem(); if (a && a.variants[i]) a.variants[i].name = v; }
function _poVarOpts(i, v) { const a = _optItem(); if (a && a.variants[i]) a.variants[i].options = v.split(',').map(s => s.trim()).filter(Boolean); }
function _poAddReview() { const a = _optItem(); if (!a.reviews) a.reviews = []; a.reviews.push({ author:'', rating:5, text:'' }); _renderProductOptions(); }
function _poDelReview(i) { const a = _optItem(); if (a && a.reviews) { a.reviews.splice(i,1); _renderProductOptions(); } }
function _poRevField(i, k, v) { const a = _optItem(); if (a && a.reviews[i]) a.reviews[i][k] = (k === 'rating') ? (parseInt(v)||5) : v; }
function _poSave() {
  const a = _optItem();
  if (a) {
    a.variants = (a.variants||[]).filter(v => v.name && v.options && v.options.length);
    a.reviews = (a.reviews||[]).filter(r => (r.author && r.author.trim()) || (r.text && r.text.trim()));
    _persistProductObj(a);
    _pushArticleMeta(a); // synchro serveur (variantes visibles sur les autres appareils)
  }
  document.getElementById('po-modal')?.remove();
  showToast('Options boutique enregistrées', 'success');
  if (typeof _refreshBoutiqueLivePreview === 'function') _refreshBoutiqueLivePreview();
}
// ── Lot 133 : pousse les métadonnées synchronisées d'un ARTICLE au serveur ──
// Best-effort ; ne concerne que les articles connus du serveur (id serveur),
// jamais les photos. Produits (table à part) : local seulement pour l'instant.
function _pushArticleMeta(a) {
  if (USE_LOCAL || !S.token || !a || a.id == null) return;
  if (Number(a.id) > 1e10) return;                       // id local → sera réconcilié au prochain démarrage
  if (!(S.articles || []).some(x => x.id === a.id)) return; // pas un article (produit/pack)
  try {
    api('PUT', `/api/articles/${a.id}`, {
      variants: Array.isArray(a.variants) ? a.variants : [],
      category: a.category || '', ean: a.ean || '',
      sell_price: a.sellPrice || 0, price: a.price || 0,
      purchase_price: a.purchasePrice || 0,
      in_boutique: !!a.inBoutique, description: a.description || '',
    }).catch(() => {});
  } catch(_){}
}
function vBoutiqueAnalytics() {
  const bc = S.boutiqueConfig || {};
  const orders = S.boutiqueOrders || [];
  const caBoutique = orders.reduce((s,o) => s + (o.total||0), 0);
  const nbOrders = orders.length;
  const panierMoyen = nbOrders ? Math.round(caBoutique / nbOrders) : 0;
  const vitrine = (typeof _getAllVitrineItems === 'function') ? _getAllVitrineItems() : [];
  const pending = orders.filter(o => o.status === 'pending').length;
  const done = orders.filter(o => o.status === 'delivered' || o.status === 'done' || o.status === 'completed').length;
  // Top produits boutique (depuis les lignes de commande)
  const prodStats = {};
  orders.forEach(o => (o.items||[]).forEach(it => { const n = it.name||'?'; if (!prodStats[n]) prodStats[n] = { qty:0, rev:0 }; prodStats[n].qty += (it.qty||1); prodStats[n].rev += (it.price||0)*(it.qty||1); }));
  const topProds = Object.entries(prodStats).map(([name,v]) => ({ name, ...v })).sort((a,b) => b.rev - a.rev).slice(0,5);
  const topMax = topProds.length ? topProds[0].rev : 1;
  // Évolution sur 7 jours (CA + nb commandes par jour)
  const _days7 = (() => { const arr = []; const now = new Date();
    for (let i = 6; i >= 0; i--) { const d = new Date(now); d.setDate(d.getDate() - i); const key = d.toDateString();
      const dayO = orders.filter(o => new Date(o.date).toDateString() === key);
      arr.push({ label: d.toLocaleDateString(_loc(), { weekday:'short' }).replace('.','').slice(0,3), rev: dayO.reduce((s,o)=>s+(o.total||0),0), n: dayO.length }); }
    return arr; })();
  const _d7max = Math.max(1, ..._days7.map(d => d.rev));
  // Pixels de suivi visiteurs (réels, hébergés sur GA/Meta/TikTok)
  const px = bc.pixels || {};
  const trackers = [];
  if (px.googleAnalytics_enabled && px.googleAnalytics) trackers.push(['Google Analytics', px.googleAnalytics, 'https://analytics.google.com']);
  if (px.facebookPixel_enabled && px.facebookPixel) trackers.push(['Meta Pixel', px.facebookPixel, 'https://business.facebook.com/events_manager']);
  if (px.tiktokPixel_enabled && px.tiktokPixel) trackers.push(['TikTok Pixel', px.tiktokPixel, 'https://ads.tiktok.com']);
  const _CC = ['#10B981','#4F46E5','#7C3AED','#EA580C','#0891B2'];

  return `
  <div class="sub-hero">
    <button class="back-btn-dark" style="margin-bottom:14px" onclick="nav('boutique')">${IC.left}</button>
    <div class="sub-hero-title">📈 Analytics & Revenus</div>
    <div class="sub-hero-big"><span data-count="${caBoutique}">${fmt(caBoutique)}</span> <span style="font-size:16px;color:var(--accent-muted)">${sym()}</span></div>
    <div class="sub-hero-sub">${t('zz3_caBoutique')} · ${t(nbOrders>1?'zz3_commandes':'zz3_commande').replace('{0}', nbOrders)}</div>
  </div>
  <div class="container">
    <div class="metric-grid">
      <div class="metric-card"><div class="metric-val">${fmt(caBoutique)}</div><div class="metric-lbl">${t('zz_caBoutique')}</div></div>
      <div class="metric-card"><div class="metric-val">${nbOrders}</div><div class="metric-lbl">${t('w1_lienCommandes')}</div></div>
      <div class="metric-card"><div class="metric-val">${fmt(panierMoyen)}</div><div class="metric-lbl">${t('w4_panierMoyen')}</div></div>
      <div class="metric-card"><div class="metric-val">${vitrine.length}</div><div class="metric-lbl">En vitrine</div></div>
    </div>

    ${nbOrders > 0 ? `
    <div class="card" style="margin-bottom:12px">
      <div class="card-title">${t('x2_evolution7j')}</div>
      <div style="display:flex;align-items:flex-end;gap:6px;height:130px;padding-top:6px">
        ${_days7.map(d => { const h = Math.round((d.rev/_d7max)*100); return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;height:100%;justify-content:flex-end">
          <div style="font-size:9px;color:var(--text-3);font-weight:700;white-space:nowrap">${d.rev?fmt(d.rev):''}</div>
          <div title="${d.n} ${t('w4_commandes')}" style="width:100%;height:${Math.max(2,h)}%;min-height:3px;background:linear-gradient(180deg,var(--accent),color-mix(in srgb,var(--accent) 70%,#fff));border-radius:6px 6px 0 0;transition:height .5s cubic-bezier(.2,0,0,1)"></div>
          <div style="font-size:10px;color:var(--text-3)">${d.label}</div>
        </div>`; }).join('')}
      </div>
    </div>

    <div class="card" style="margin-bottom:12px">
      <div class="card-title">${t('x2_etatCommandes')}</div>
      <div style="display:flex;gap:10px">
        <div style="flex:1;text-align:center;padding:12px;border-radius:12px;background:var(--warning-light,rgba(245,158,11,.1))"><div style="font-size:22px;font-weight:900;color:var(--warning,#D97706)">${pending}</div><div style="font-size:12px;color:var(--text-3)">${t('boutiquePending')}</div></div>
        <div style="flex:1;text-align:center;padding:12px;border-radius:12px;background:var(--success-light,rgba(16,185,129,.1))"><div style="font-size:22px;font-weight:900;color:var(--success,#059669)">${done}</div><div style="font-size:12px;color:var(--text-3)">${t('x2_livrees')}</div></div>
      </div>
    </div>` : ''}

    ${topProds.length > 0 ? `
    <div class="card" style="margin-bottom:12px">
      <div class="card-title">🏆 Top produits boutique</div>
      ${topProds.map((p,i) => { const w = Math.max(4, Math.round((p.rev/topMax)*100)); const col = _CC[i%_CC.length];
        return `<div style="margin-bottom:10px">
          <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px">
            <span style="font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${p.name} <span style="color:var(--text-3);font-weight:500">· ${p.qty} ${t('zz9_vendus')}</span></span>
            <span style="font-size:12px;font-weight:700;color:${col};flex-shrink:0;margin-left:8px">${fmt(p.rev)} ${sym()}</span>
          </div>
          <div style="height:8px;background:var(--gray-2);border-radius:5px;overflow:hidden"><div style="height:100%;width:${w}%;background:linear-gradient(90deg,${col},${col}cc);border-radius:5px"></div></div>
        </div>`; }).join('')}
    </div>` : ''}

    ${(() => {
      const isEnt = _planHasFeature('advancedAnalytics');
      const locs = S.locations || [];
      if (!isEnt) {
        return `
    <div class="card" style="margin-bottom:12px;position:relative;overflow:hidden">
      <div class="card-title">${t('x2_analyticsAvances')}</div>
      <div style="filter:blur(3px);pointer-events:none;user-select:none" aria-hidden="true">
        ${[t('zzg_exBoutique'),t('zzg_exComptoir'),t('u_typeEntrepot')].map((n,i)=>`<div style="display:flex;justify-content:space-between;padding:7px 0;font-size:13px"><span>${n}</span><b>${fmt([84000,52000,31000][i])} ${sym()}</b></div>`).join('')}
      </div>
      <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;background:linear-gradient(180deg,rgba(255,255,255,.55),var(--surface) 78%);padding:14px;text-align:center">
        <div style="font-size:10.5px;font-weight:800;color:#fff;background:linear-gradient(135deg,#8B5CF6,#6366F1);padding:4px 11px;border-radius:999px;letter-spacing:.5px">◆ ENTREPRISE</div>
        <div style="font-size:12.5px;color:var(--text-2);max-width:270px;line-height:1.5">${t('x2_revenusDetailles')} <b>${t('x2_parPointVente')}</b>${t('zzg_compExport')}</div>
        <button class="btn" style="padding:8px 16px;font-size:12px;font-weight:800;background:linear-gradient(135deg,#8B5CF6,#6366F1);color:#fff;border:none" onclick="nav('pricing')">${t('x2_debloquer')}</button>
      </div>
    </div>`;
      }
      // ── Réel : CA par point de vente, calculé sur les vraies ventes ──
      const rows = locs.map(l => {
        const sl = (S.sales||[]).filter(s => String(s.locationId) === String(l.id));
        return { name: l.name, ca: sl.reduce((a,s)=>a+(s.total||0),0), n: sl.length };
      });
      const unassigned = (S.sales||[]).filter(s => !s.locationId);
      if (unassigned.length) rows.push({ name:t('zr_nonAffecte'), ca: unassigned.reduce((a,s)=>a+(s.total||0),0), n: unassigned.length });
      rows.sort((a,b)=>b.ca-a.ca);
      const mx = Math.max(1, ...rows.map(r=>r.ca));
      return `
    <div class="card" style="margin-bottom:12px">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px">
        <div class="card-title" style="margin:0">${t('x2_analyticsAvances')}</div>
        <span style="font-size:9.5px;font-weight:800;color:#fff;background:linear-gradient(135deg,#8B5CF6,#6366F1);padding:3px 9px;border-radius:999px;letter-spacing:.4px">ENTREPRISE</span>
      </div>
      ${rows.length ? rows.map(r => `<div style="margin-bottom:9px">
        <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px">
          <span style="font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${String(r.name).replace(/</g,'&lt;')} <span style="color:var(--text-3);font-weight:500">· ${r.n} ${r.n>1?t('w4_ventesN'):t('w4_venteN')}</span></span>
          <b style="font-size:12px;flex-shrink:0;margin-left:8px;color:#8B5CF6">${fmt(r.ca)} ${sym()}</b>
        </div>
        <div style="height:8px;background:var(--gray-2);border-radius:5px;overflow:hidden"><div style="height:100%;width:${Math.max(4,Math.round(r.ca/mx*100))}%;background:linear-gradient(90deg,#8B5CF6,#6366F1);border-radius:5px"></div></div>
      </div>`).join('')
      : `<div style="font-size:12.5px;color:var(--text-3)">${t('x2_creezPointsVente')}</div>`}
    </div>`;
    })()}

    <div class="card" style="margin-bottom:12px">
      <div class="card-title">${t('x2_visiteursBoutique')}</div>
      ${trackers.length > 0 ? `
        <div style="font-size:13px;color:var(--text-2);line-height:1.6;margin-bottom:10px">${t('x2_suiviVisiteurs')} <b style="color:var(--success)">actif</b> via :</div>
        ${trackers.map(t => `<a href="${t[2]}" target="_blank" rel="noopener" class="card card-tap" style="display:flex;align-items:center;gap:10px;margin-bottom:8px;text-decoration:none">
          <span style="font-size:18px">📊</span>
          <div style="flex:1"><div style="font-weight:700;font-size:13.5px;color:var(--text-1)">${t[0]}</div><div style="font-size:11px;color:var(--text-3)">ID ${t[1]} · voir le tableau de bord →</div></div>
        </a>`).join('')}
        <div style="font-size:11px;color:var(--text-3);line-height:1.5;margin-top:6px">Le nombre exact de visiteurs, sources de trafic et conversions se consultent en temps réel sur la plateforme connectée.</div>
      ` : `
        <div style="font-size:13px;color:var(--text-2);line-height:1.6;margin-bottom:12px">${t('zz_analyticsAide')}</div>
        <button class="btn btn-primary" style="width:100%" onclick="nav('boutique-pixels')">Connecter Google Analytics / Pixel</button>
      `}
    </div>

    <div class="section-hd" id="bq-orders"><span class="section-lbl">${t('x2_commandesRecues')}</span><button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="addBoutiqueOrder()">${t('x5_ajouterPlus2')}</button></div>
    ${nbOrders === 0 ? `
    <div class="empty" style="padding:28px 16px">
      <div class="empty-ico">🧾</div>
      <div class="empty-title">${t('x2_aucuneCommandeEnr')}</div>
      <div class="empty-text">${t('zz_cmdWaAide')}</div>
      <button class="btn btn-primary" style="max-width:240px" onclick="addBoutiqueOrder()">${t('x2_enregistrerCommande')}</button>
    </div>` : orders.slice(0,12).map(o => `
    <div class="card" style="margin-bottom:6px;padding:12px 14px">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:10px">
        <div style="flex:1;min-width:0">
          <div style="font-weight:700;font-size:13.5px">${_wafEsc(o.clientName || t('zwa_client'))}${o.zone?` · <span style="color:var(--text-3);font-weight:500">${_wafEsc(o.zone)}</span>`:''}</div>
          <div style="font-size:11px;color:var(--text-3)">${fmtDate(o.date)} · ${t('zcm_nbArticles').replace('{0}', (o.items||[]).reduce((s,x)=>s+(Number(x && x.qty)||1),0))}</div>
        </div>
        <div style="text-align:right"><div style="font-weight:800;color:var(--accent)">${fmt(o.total||0)} ${sym()}</div><div style="font-size:10px;color:${_cmdStatut(o).couleur}">${_wafEsc(_cmdStatut(o).lib)}</div></div>
      </div>
    </div>`).join('')}
  </div>`;
}
function addBoutiqueOrder() {
  const clientName = prompt('Nom du client :');
  if (!clientName) return;
  const phone = prompt('Telephone du client :') || '';
  const zone = prompt('Zone de livraison :') || '';
  // Select products/articles en vitrine
  const shopProds = _getAllVitrineItems();
  if (shopProds.length === 0) { showToast('Ajoutez des produits/articles en vitrine d\'abord', 'error'); return; }
  const prodIndex = prompt('Article :\n' + shopProds.map((p,i) => `${i+1}. ${p.name} — ${fmt(p.price)} ${sym()}`).join('\n') + '\n\nNumero :');
  if (!prodIndex) return;
  const prod = shopProds[parseInt(prodIndex)-1];
  if (!prod) { showToast('Produit invalide', 'error'); return; }
  const qty = parseInt(prompt('Quantite :', '1')) || 1;
  const total = prod.price * qty + (S.boutiqueConfig.deliveryFees || 0);
  const order = {
    id: Date.now(), clientName, phone, zone, status: 'pending',
    items: [{ id:prod.id, name:prod.name, price:prod.price, qty }],
    total, date: new Date().toISOString()
  };
  S.boutiqueOrders.unshift(order);
  localStorage.setItem('baro_boutique_orders', JSON.stringify(S.boutiqueOrders));
  logActivity('order', `Commande de ${clientName} — ${fmt(total)} ${sym()}`);
  _evtCommande('recue', order);
  showToast('Commande ajoutee !');
  render();
}
function updateOrderStatus(id, status) {
  const order = S.boutiqueOrders.find(o => String(o.id) === String(id));
  if (!order) return;
  order.status = status;
  order.updatedAt = new Date().toISOString();
  localStorage.setItem('baro_boutique_orders', JSON.stringify(S.boutiqueOrders));
  // Chaque changement d'état est un moment où le client attend un mot.
  _evtCommande({ confirmed:'confirmee', shipped:'expediee', delivered:'livree',
                 cancelled:'annulee' }[status], order);
  // Commande venue du serveur → répercuter le statut en ligne
  if (order.serverId && !USE_LOCAL && S.token) { api('PUT', `/api/orders/${order.serverId}`, { status }).catch(() => {}); }
  // If confirmed, record as sale
  if (status === 'confirmed') {
    for (const item of (order.items||[])) {
      const product = S.products.find(p => p.id === item.id);
      if (product) {
        product.composition.forEach(comp => {
          const art = S.articles.find(a => a.id === comp.id);
          if (art) art.stock = Math.round((art.stock - comp.qty * item.qty) * 10) / 10;
        });
        S.sales.unshift({ id:Date.now(), productId:item.id, productName:item.name, qty:item.qty, total:item.price*item.qty, profit:((item.price||0)-(product.purchasePrice||0))*item.qty, date:new Date().toISOString(), paymentMethod:'pending', clientName:order.clientName });
      }
    }
    logActivity('sale', t('zcm_actConfirmee').replace('{0}', order.clientName || ''));
  }
  showToast(t({ confirmed:'zcm_okConfirmee', shipped:'zcm_okRoute', delivered:'zcm_okLivree',
                 cancelled:'zcm_okAnnulee' }[status] || 'zcm_okMaj'));
  render();
}
// Un argument passé à un onclick : JSON le rend sûr pour JavaScript, puis
// l'échappement HTML le rend sûr pour l'attribut. L'un sans l'autre ne
// suffit pas — « &#39; » redevient une apostrophe avant que JS ne lise.
// C'est ce qui manquait : updateOrderStatus(srv_42, …) faisait une
// ReferenceError sur toute commande venue du site.
function _jsArg(v) { return _wafEsc(JSON.stringify(v == null ? '' : v)); }
function _cmdParId(id) { return (S.boutiqueOrders || []).find(o => o && String(o.id) === String(id)); }
// L'état d'une commande, avec sa couleur et son nom. « shipped » et
// « preparing » tombaient dans le cas par défaut et s'affichaient « Annulée ».
function _cmdStatut(o) {
  const cle = (o && o.status) || 'pending';
  const couleurs = { pending:'var(--warning)', confirmed:'var(--accent)', preparing:'#8B5CF6',
                     shipped:'#0EA5E9', delivered:'var(--success)', cancelled:'var(--text-3)' };
  const libs = { pending:t('orderPending'), confirmed:t('orderConfirmed'), preparing:t('zcm_preparation'),
                 shipped:t('zcm_enRoute'), delivered:t('orderDelivered'), cancelled:t('orderCancelled') };
  return { cle, couleur: couleurs[cle] || 'var(--text-3)', lib: libs[cle] || String(cle) };
}

function contactOrderClient(id) {
  const order = _cmdParId(id);
  const phone = order ? _waNormalize(order.phone) : '';
  if (!phone) { showToast(t('zrc_pasNumero'), 'error'); return; }
  const msg = t('zcm_contactMsg')
    .replace('{0}', order.clientName || '')
    .replace('{1}', (S.boutiqueConfig && S.boutiqueConfig.name) || (S.session && S.session.business) || '')
    .replace('{2}', fmt(order.total || 0) + ' ' + sym());
  window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`, '_blank');
}

