// Vérifie qu'un numéro mobile money appartient bien au marchand : envoie un code
// par SMS (passerelle configurée si dispo, sinon webhook, sinon l'app SMS du
// téléphone) puis saisie INLINE du code (UI premium, pas de prompt natif).
async function verifyPaymentNumber(providerId) {
  const num = (document.getElementById('pay-main-inp')?.value || '').trim();
  if (!num) { showToast('Entrez d\'abord le numéro', 'error'); document.getElementById('pay-main-inp')?.focus(); return; }
  const code = String(Math.floor(100000 + Math.random() * 900000));
  const msg = `BARO : code de vérification de votre numéro marchand : ${code}. Ne le partagez avec personne.`;
  let sent = false, channel = 'native';
  const cfg = (typeof _getSmsConfig === 'function') ? _getSmsConfig() : null;
  if (cfg && typeof sendSms === 'function') {
    showToast('Envoi du SMS…', 'info');
    try { sent = await sendSms(num, msg); } catch(_) { sent = false; }
    if (sent) channel = 'gateway';
  }
  if (!sent) {
    const wh = localStorage.getItem('stockr_sms_webhook');
    if (wh && typeof _sendVerificationSMS === 'function') {
      try { const r = await _sendVerificationSMS(num, code, 'Vérif numéro marchand'); sent = !!(r && r.ok); } catch(_) {}
      if (sent) channel = 'webhook';
    }
  }
  if (!sent) {
    // Pas de passerelle : on ouvre l'app SMS du téléphone vers ce numéro.
    try { window.open(`sms:${num.replace(/[^\d+]/g,'')}?body=${encodeURIComponent(msg)}`, '_blank'); } catch(_){}
    channel = 'native';
  }
  window.__payVerifyPending = { providerId, code, num };
  const zone = document.getElementById('pay-verify-zone');
  if (zone) {
    zone.innerHTML = `
      <div class="pay-verify-sent">${sent
        ? `Code envoyé par SMS au <b>${num}</b>`
        : `L'app SMS s'ouvre vers <b>${num}</b> — envoyez le message, puis entrez le code reçu`}</div>
      <div class="pay-code-row">
        <input id="pay-code-inp" class="input pay-code-inp" inputmode="numeric" maxlength="6" placeholder="Code à 6 chiffres" autocomplete="one-time-code">
        <button class="btn btn-primary" style="flex:0 0 auto;width:auto;padding:11px 16px;white-space:nowrap" onclick="confirmPaymentCode('${providerId}')">Valider</button>
      </div>
      <button class="pay-resend" onclick="verifyPaymentNumber('${providerId}')">${t('x1_renvoyerCode2')}</button>`;
    setTimeout(() => document.getElementById('pay-code-inp')?.focus(), 120);
  }
}
function confirmPaymentCode(providerId) {
  const p = window.__payVerifyPending;
  const entered = (document.getElementById('pay-code-inp')?.value || '').trim();
  if (!p || p.providerId !== providerId) { showToast('Relancez la vérification', 'error'); return; }
  if (entered === p.code) {
    window.__payVerified = window.__payVerified || {};
    window.__payVerified[providerId] = p.num;
    const m = (S.paymentMethods || []).find(x => x.provider === providerId);
    if (m && m.phone === p.num) { m.verified = true; m.verifiedPhone = p.num; localStorage.setItem('baro_payments', JSON.stringify(S.paymentMethods)); }
    const zone = document.getElementById('pay-verify-zone');
    if (zone) zone.innerHTML = `<div class="pay-verified-badge">${t('x1_numVerifieSms')}</div>`;
    if (typeof haptic === 'function') haptic('success');
    showToast('✓ Numéro vérifié', 'success');
  } else {
    if (typeof haptic === 'function') haptic('error');
    showToast('Code incorrect — réessayez', 'error');
    const inp = document.getElementById('pay-code-inp'); if (inp) { inp.value=''; inp.focus(); }
  }
}

function __savePaymentSetup(providerId, providerName) {
  const mainV = (document.getElementById('pay-main-inp')?.value || '').trim();
  const keyV  = (document.getElementById('pay-key-inp')?.value || '').trim();
  if (!mainV) { showToast('Champ requis', 'error'); return; }
  const existing = (S.paymentMethods||[]).findIndex(m => m.provider === providerId);
  const _prev = existing >= 0 ? S.paymentMethods[existing] : null;
  const _verifiedNow = (window.__payVerified && window.__payVerified[providerId] === mainV)
    || (_prev && _prev.verified && _prev.verifiedPhone === mainV);
  const method = {
    provider:  providerId,
    name:      providerName,
    phone:     mainV,
    email:     (providerId==='paypal') ? mainV : null,
    merchantId:(providerId==='gpay'||providerId==='applepay') ? mainV : null,
    apiKey:    keyV || null,
    verified:  !!_verifiedNow,
    verifiedPhone: _verifiedNow ? mainV : null,
    active:    true,
    createdAt: new Date().toISOString()
  };
  if (!S.paymentMethods) S.paymentMethods = [];
  if (existing >= 0) S.paymentMethods[existing] = method;
  else S.paymentMethods.push(method);
  localStorage.setItem('baro_payments', JSON.stringify(S.paymentMethods));
  if (typeof logActivity === 'function') logActivity('payment', `${providerName} configuré`);
  document.getElementById('pay-setup-modal')?.remove();
  showToast(`✅ ${providerName} activé — prêt à encaisser`, 'success');
  render();
}

async function __testPayment(providerId) {
  const res = await payWithProvider(providerId, 100, 'Test ' + providerId);
  if (res.success) {
    showToast(`✅ Test ${providerId} OK — 100 ${sym()} simulé`, 'success');
  } else {
    showToast(`⚠ Test ${providerId} : ${res.error}`, 'warning');
  }
}

// Paiements mobile money : génère lien deep/ussd (pas de SDK W3C dispo pour Wave/OM/Moov)
function payWithMobileMoney(providerId, amount, description) {
  const method = (S.paymentMethods||[]).find(m => m.provider === providerId && m.active);
  if (!method) { showToast(`${providerId} non configuré`, 'error'); return { success:false }; }
  const phone = (method.phone || '').replace(/\D/g, '');
  const urls = {
    wave:   `https://pay.wave.com/m/${phone}/c/ci?amount=${amount}`,
    orange: `tel:*144*4*6*${phone}*${amount}#`,
    moov:   `tel:*155*${phone}*${amount}#`,
    mtn:    `tel:*133*1*${phone}*${amount}#`,
  };
  const url = urls[providerId];
  if (!url) { showToast('Provider non supporté', 'error'); return { success:false }; }
  try {
    window.open(url, '_blank');
    S.paymentHistory = S.paymentHistory || [];
    S.paymentHistory.unshift({
      id: Date.now(), provider: providerId, amount, description,
      date: new Date().toISOString(), status: 'initiated',
      phone: method.phone,
    });
    localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
    showToast(`📱 Lien ${providerId} ouvert — confirmez sur votre téléphone`, 'info');
    return { success:true, pending:true };
  } catch(e) {
    showToast(`Erreur ${providerId}: ${e.message}`, 'error');
    return { success:false };
  }
}

// Déclenche un paiement : mobile money (Wave/OM/Moov/MTN) par deep-link,
// Google Pay / Apple Pay / carte par API Payment Request W3C,
// PayPal par redirection.
// Usage : payWithProvider('gpay', 5000, 'Commande #12') → Promise<{success,token}>
async function payWithProvider(providerId, amount, description){
  const method = (S.paymentMethods||[]).find(m => m.provider === providerId && m.active);
  if (!method) {
    showToast(`${providerId} non configuré — configurez dans Paiements`, 'error');
    return { success:false, error:'not_configured' };
  }
  // Mobile money : deep-link / USSD (pas de SDK W3C)
  if (['wave','orange','moov','mtn'].includes(providerId)) {
    return payWithMobileMoney(providerId, amount, description);
  }
  // PayPal : redirection vers PayPal.me ou endpoint marchand
  if (providerId === 'paypal') {
    const email = method.email || method.phone;
    const url = `https://www.paypal.com/paypalme/${encodeURIComponent(email.split('@')[0])}/${amount}XOF`;
    window.open(url, '_blank');
    S.paymentHistory = S.paymentHistory || [];
    S.paymentHistory.unshift({ id:Date.now(), provider:'paypal', amount, description, date:new Date().toISOString(), status:'initiated', email });
    localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
    showToast('💰 PayPal ouvert — confirmez sur PayPal.com', 'info');
    return { success:true, pending:true };
  }
  // API Payment Request (W3C) — supportée par Chrome/Safari
  if (!window.PaymentRequest) {
    showToast('PaymentRequest non supporté sur ce navigateur', 'error');
    return { success:false, error:'not_supported' };
  }
  try {
    const methodsSupported = [];
    if (providerId === 'gpay') {
      methodsSupported.push({
        supportedMethods: 'https://google.com/pay',
        data: {
          environment: 'TEST',
          apiVersion: 2, apiVersionMinor: 0,
          merchantInfo: { merchantId: method.merchantId || '12345', merchantName: 'BARO' },
          allowedPaymentMethods: [{
            type: 'CARD',
            parameters: { allowedAuthMethods: ['PAN_ONLY','CRYPTOGRAM_3DS'], allowedCardNetworks: ['VISA','MASTERCARD'] },
            tokenizationSpecification: {
              type: 'PAYMENT_GATEWAY',
              parameters: method.apiKey ? Object.fromEntries(method.apiKey.split(';').map(p=>p.split('='))) : { gateway:'example', gatewayMerchantId:'example' }
            }
          }]
        }
      });
    } else if (providerId === 'applepay') {
      methodsSupported.push({
        supportedMethods: 'https://apple.com/apple-pay',
        data: {
          version: 3,
          merchantIdentifier: method.phone,
          merchantCapabilities: ['supports3DS'],
          supportedNetworks: ['visa','masterCard','amex'],
          countryCode: 'CI'
        }
      });
    } else {
      methodsSupported.push({ supportedMethods: 'basic-card', data: { supportedNetworks:['visa','mastercard','amex'] } });
    }
    const details = {
      total: { label: description || 'Paiement BARO', amount: { currency: 'XOF', value: String(amount) } },
      displayItems: [{ label: description || 'Total', amount: { currency:'XOF', value: String(amount) } }]
    };
    const req = new PaymentRequest(methodsSupported, details);
    const resp = await req.show();
    await resp.complete('success');
    // Enregistrer la transaction
    S.paymentHistory = S.paymentHistory || [];
    S.paymentHistory.unshift({
      id: Date.now(), provider: providerId, amount, description,
      date: new Date().toISOString(), token: resp.details?.paymentToken || null,
      status: 'completed'
    });
    localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
    showToast(`${method.name} : ${fmt(amount)} ${sym()} encaissé`, 'success');
    return { success:true, token: resp.details?.paymentToken };
  } catch(e) {
    showToast(`Erreur ${providerId} : ${e.message}`, 'error');
    return { success:false, error: e.message };
  }
}
function disconnectPayment(providerId) {
  S.paymentMethods = S.paymentMethods.filter(m => m.provider !== providerId);
  localStorage.setItem('baro_payments', JSON.stringify(S.paymentMethods));
  showToast('Moyen de paiement retire');
  render();
}

// ══════════════════════════════════════════════════════════════
// DEMANDER UN PAIEMENT — génère un lien/instruction et le partage
// ══════════════════════════════════════════════════════════════
// Retourne ce qui est partageable pour une méthode + montant.
function _payShareable(method, amount) {
  const digits = String(method.phone || method.email || '').replace(/\D/g, '');
  const a = Math.max(0, Math.round(amount || 0));
  switch (method.provider) {
    case 'wave':   return { link: `https://pay.wave.com/m/${digits}/c/ci?amount=${a}`, label: 'Lien de paiement Wave' };
    case 'paypal': { const h = (method.email || method.phone || '').split('@')[0]; return { link: `https://www.paypal.com/paypalme/${encodeURIComponent(h)}/${a}`, label: 'Lien PayPal' }; }
    case 'orange': return { instruction: `Pour payer ${fmt(a)} ${sym()} : Orange Money vers ${method.phone}`, ussd: `*144*4*6*${digits}*${a}#` };
    case 'moov':   return { instruction: `Pour payer ${fmt(a)} ${sym()} : Moov Money vers ${method.phone}`, ussd: `*155*${digits}*${a}#` };
    case 'mtn':    return { instruction: `Pour payer ${fmt(a)} ${sym()} : MTN MoMo vers ${method.phone}`, ussd: `*133*1*${digits}*${a}#` };
    default:       return { instruction: `Paiement ${method.name} de ${fmt(a)} ${sym()} (carte / en personne).`, inPerson: true };
  }
}
function _payReqState() {
  if (!S._payReq) {
    const active = (S.paymentMethods || []).filter(m => m.active);
    S._payReq = { amount: '', desc: '', clientId: null, method: active[0]?.provider || null };
  }
  return S._payReq;
}
function requestPaymentModal(clientId) {
  const active = (S.paymentMethods || []).filter(m => m.active);
  S._payReq = null; // repart propre
  if (clientId != null) _payReqState().clientId = clientId;
  const existing = document.getElementById('payreq-modal');
  if (existing) existing.remove();
  const st = _payReqState();
  if (active.length && !active.find(m => m.provider === st.method)) st.method = active[0].provider;
  const modal = document.createElement('div');
  modal.id = 'payreq-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:10000;display:flex;align-items:flex-end;justify-content:center;backdrop-filter:blur(6px);animation:fadeIn .2s ease';
  modal.onclick = (e) => { if (e.target === modal) modal.remove(); };
  if (!active.length) {
    modal.innerHTML = `<div class="payreq-sheet"><div class="payreq-hd"><div style="font-size:17px;font-weight:800">${t('w8_demanderPaiement')}</div><button class="qs-x" onclick="document.getElementById('payreq-modal').remove()">✕</button></div>
      <div style="text-align:center;padding:24px 8px"><div style="font-size:38px;margin-bottom:8px">💳</div><div style="font-weight:700;margin-bottom:4px">${t('x1_aucunMoyenActif')}</div><div style="font-size:12px;color:var(--text-3);margin-bottom:16px">Configurez Wave, Orange Money, PayPal… pour demander des paiements.</div><button class="btn btn-primary" onclick="document.getElementById('payreq-modal').remove()">${t('x1_configurerMoyen')}</button></div></div>`;
    document.body.appendChild(modal);
    return;
  }
  const clientsWithPhone = (S.clients || []).filter(c => c.phone);
  modal.innerHTML = `
    <div class="payreq-sheet">
      <div class="payreq-hd"><div style="font-size:17px;font-weight:800">${t('w8_demanderPaiement')}</div><button class="qs-x" onclick="document.getElementById('payreq-modal').remove()">✕</button></div>
      <label class="qs-label">Montant (${sym()})</label>
      <input id="payreq-amount" class="input" type="number" inputmode="numeric" placeholder="5000" value="${st.amount}" oninput="S._payReq.amount=this.value;_payReqPreview()" style="font-size:18px;font-weight:800">
      <label class="qs-label">Description (optionnel)</label>
      <input id="payreq-desc" class="input" placeholder="Ex : Commande riz" value="${(st.desc||'').replace(/"/g,'&quot;')}" oninput="S._payReq.desc=this.value">
      ${clientsWithPhone.length ? `<label class="qs-label">${t('x1_clientPourWa')}</label>
      <select id="payreq-client" class="input" onchange="S._payReq.clientId=this.value?parseInt(this.value):null">
        <option value="">${t('x1_aucunPartage')}</option>
        ${clientsWithPhone.map(c=>`<option value="${c.id}" ${st.clientId===c.id?'selected':''}>${(c.name||'Client').replace(/</g,'&lt;')}</option>`).join('')}
      </select>` : ''}
      <label class="qs-label">Encaisser via</label>
      <div class="payreq-methods">
        ${active.map(m => `<button class="payreq-m ${st.method===m.provider?'on':''}" onclick="S._payReq.method='${m.provider}';_payReqPreview();document.querySelectorAll('.payreq-m').forEach(b=>b.classList.remove('on'));this.classList.add('on')">${m.name}</button>`).join('')}
      </div>
      <div id="payreq-preview" class="payreq-preview"></div>
      <div style="display:flex;gap:8px;margin-top:14px">
        <button class="btn btn-ghost" style="flex:1" onclick="_payReqCopy()">📋 Copier</button>
        <button class="btn btn-primary" style="flex:2;background:#25D366" onclick="_payReqShare()">${IC.whatsapp} Envoyer au client</button>
      </div>
    </div>`;
  document.body.appendChild(modal);
  _payReqPreview();
  setTimeout(()=>document.getElementById('payreq-amount')?.focus(), 150);
}
function _payReqBuild() {
  const st = _payReqState();
  const method = (S.paymentMethods || []).find(m => m.provider === st.method && m.active);
  const amount = parseFloat(st.amount) || 0;
  if (!method || amount <= 0) return null;
  const sh = _payShareable(method, amount);
  const biz = S.session?.business || 'notre boutique';
  const descPart = st.desc ? ` (${st.desc})` : '';
  let msg;
  if (sh.link) msg = `Bonjour 👋\nVoici votre lien de paiement ${method.name} pour ${fmt(amount)} ${sym()}${descPart} chez ${biz} :\n${sh.link}\n\nMerci !`;
  else msg = `Bonjour 👋\n${sh.instruction}${descPart}.${sh.ussd?`\nCode : ${sh.ussd}`:''}\n\nMerci de votre confiance — ${biz}`;
  return { method, amount, sh, msg };
}
function _payReqPreview() {
  const el = document.getElementById('payreq-preview');
  if (!el) return;
  const b = _payReqBuild();
  if (!b) { el.innerHTML = `<div class="payreq-hint">${t('x1_entrezMontant')}</div>`; return; }
  if (b.sh.link) {
    el.innerHTML = `<div class="payreq-link-box"><div class="payreq-link-lbl">${b.sh.label}</div><a href="${b.sh.link}" target="_blank" rel="noopener noreferrer" class="payreq-link">${b.sh.link}</a></div>`;
  } else if (b.sh.inPerson) {
    el.innerHTML = `<div class="payreq-hint">${b.method.name} : encaissement carte/en personne (pas de lien à distance).</div>`;
  } else {
    el.innerHTML = `<div class="payreq-link-box"><div class="payreq-link-lbl">Instruction client</div><div style="font-size:13px;font-weight:600">${b.sh.instruction}</div>${b.sh.ussd?`<div style="font-size:12px;color:var(--text-3);margin-top:4px">USSD : <b>${b.sh.ussd}</b></div>`:''}</div>`;
  }
}
function _payReqRecord(b) {
  S.paymentHistory = S.paymentHistory || [];
  const cl = b && _payReqState().clientId ? (S.clients||[]).find(c=>c.id===_payReqState().clientId) : null;
  S.paymentHistory.unshift({ id: Date.now(), provider: b.method.provider, amount: b.amount, description: _payReqState().desc || 'Demande de paiement', date: new Date().toISOString(), status: 'requested', clientName: cl?.name || null });
  localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
}
function _payReqShare() {
  const b = _payReqBuild();
  if (!b) { showToast('Entrez un montant', 'error'); return; }
  const st = _payReqState();
  const cl = st.clientId ? (S.clients||[]).find(c=>c.id===st.clientId) : null;
  const phone = cl?.phone ? cl.phone.replace(/\D/g,'') : '';
  window.open(`https://wa.me/${phone}?text=${encodeURIComponent(b.msg)}`, '_blank');
  _payReqRecord(b);
  if (typeof logActivity === 'function') logActivity('payment', `Demande de paiement ${b.method.name} — ${fmt(b.amount)} ${sym()}`);
  document.getElementById('payreq-modal')?.remove();
  showToast('Demande envoyée sur WhatsApp', 'success');
  render();
}
function _payReqCopy() {
  const b = _payReqBuild();
  if (!b) { showToast('Entrez un montant', 'error'); return; }
  const txt = b.sh.link || (b.sh.instruction + (b.sh.ussd ? ` (${b.sh.ussd})` : ''));
  navigator.clipboard?.writeText(txt).then(() => showToast('Copié dans le presse-papier', 'success'), () => showToast('Copie impossible', 'error'));
  _payReqRecord(b);
}

