// ── L'éditeur : quatre choix, et un aperçu qui parle vrai ───────────
function vAutomatisationEdit() {
  if (!_planHasFeature('advancedAnalytics')) return vAutomatisations();
  const d = S.regleEdit;
  if (!d) return vAutomatisations();
  const e = _wafEsc;
  if (!BARO_REGLE_DECL.includes(d.decl)) d.decl = 'cmd_livree';
  const conds = _regleConds(d.decl);
  if (!conds.includes(d.cond)) d.cond = 'aucune';
  const acts = _regleActs(d.decl);
  if (!acts.includes(d.act)) d.act = acts[0];
  const avecValeur = ['montant_min', 'montant_max', 'zone', 'fidele', 'palier'].includes(d.cond);
  const opt = (v, lib, sel) => `<option value="${e(v)}"${sel ? ' selected' : ''}>${e(lib)}</option>`;
  const condLib = cc => (cc === 'montant_min' && d.decl === 'client_silence') ? t('zau_co_montant_mois') : t('zau_co_' + cc);
  const libValeur = d.cond === 'zone' ? t('zau_fValZone')
    : (d.cond === 'fidele' || d.cond === 'palier') ? t('zau_fValNb')
    : t('zau_fValMontant').replace('{0}', sym());
  const jetons = _regleJetonsAvert(d);
  return `
  <div class="sub-hero sh-teinte" style="--sh-c1:#7C3AED;--sh-c2:#4F46E5">
    <div class="page-header-row">
      <button class="back-btn-dark" onclick="regleAnnuler()">${IC.left}</button>
      <div style="flex:1">
        <div class="sub-hero-title">${t(d.id ? 'zau_editT' : 'zau_nouvelleT')}</div>
        <div class="sub-hero-sub">${t('zau_editSous')}</div>
      </div>
    </div>
  </div>
  <div class="container">
    <div class="card au-ed">
      <div class="bq-fld">
        <label>${t('zau_fNom')}</label>
        <input class="input" type="text" maxlength="60" value="${e(d.nom || '')}"
               placeholder="${e(t('zau_fNomPh'))}" oninput="regleChamp('nom', this.value)">
      </div>

      <div class="au-etape"><span class="au-etape-n">1</span>${t('zau_quand')}</div>
      <div class="bq-fld">
        <label>${t('zau_fDecl')}</label>
        <select class="input" onchange="regleChamp('decl', this.value, true)">
          ${BARO_REGLE_DECL.map(k => opt(k, BARO_REGLE_ICONE[k] + ' ' + t('zau_do_' + k), d.decl === k)).join('')}
        </select>
      </div>
      ${d.decl === 'cmd_attente' ? `
      <div class="bq-fld">
        <label>${t('zau_fHeures')}</label>
        <input class="input" type="number" min="1" max="168" step="1" value="${Math.max(1, Number(d.attenteH) || 2)}"
               oninput="regleChamp('attenteH', this.value)">
      </div>` : ''}
      ${d.decl === 'client_silence' ? `<div class="au-aide">${t('zau_aideSilence')}</div>` : ''}

      <div class="au-etape"><span class="au-etape-n">2</span>${t('zau_si')}</div>
      <div class="bq-fld">
        <label>${t('zau_fCond')}</label>
        <select class="input" onchange="regleChamp('cond', this.value, true)">
          ${conds.map(cc => opt(cc, condLib(cc), d.cond === cc)).join('')}
        </select>
      </div>
      ${avecValeur ? `
      <div class="bq-fld">
        <label>${e(libValeur)}</label>
        <input class="input" type="${d.cond === 'zone' ? 'text' : 'number'}"
               ${d.cond === 'zone' ? 'maxlength="40"' : 'min="1" step="1"'}
               value="${e(d.val == null ? '' : d.val)}" oninput="regleChamp('val', this.value)">
      </div>` : ''}

      <div class="au-etape"><span class="au-etape-n">3</span>${t('zau_alors')}</div>
      <div class="bq-fld">
        <label>${t('zau_fAct')}</label>
        <select class="input" onchange="regleChamp('act', this.value, true)">
          ${acts.map(a => opt(a, t('zau_a_' + a), d.act === a)).join('')}
        </select>
      </div>
      ${_regleActAvert(d.act)}
      ${d.decl === 'cmd_attente' ? `<div class="au-aide">${t('zau_aideAttenteDelai')}</div>` : `
      <div class="bq-fld">
        <label>${t('zau_fDelai')}</label>
        <select class="input" onchange="regleChamp('delai', this.value, true)">
          ${BARO_REGLE_DELAIS.map(ms => opt(String(ms), t(BARO_REGLE_DELAI_CLE[ms]), (Number(d.delai) || 0) === ms)).join('')}
        </select>
      </div>`}

      <div class="au-etape"><span class="au-etape-n">4</span>${t('zau_message')}</div>
      <div class="bq-fld">
        <textarea class="input" id="au-texte" rows="5" maxlength="900"
                  oninput="regleChamp('texte', this.value)">${e(d.texte || '')}</textarea>
        <div class="au-vars">
          ${_regleVarsDe(d.decl).map(v => `<button type="button" class="au-var" onclick="regleInsereVar(${_jsArg(v)})">{{${v}}}</button>`).join('')}
        </div>
        <div class="au-avert" id="au-jetons"${jetons ? '' : ' hidden'}>${e(jetons)}</div>
      </div>
      <div class="au-apercu">
        <div class="au-apercu-t">${t('zau_apercuT')}</div>
        <div class="au-apercu-tx" id="au-apercu">${e(_regleApercuTexte(d))}</div>
      </div>
    </div>
    <div class="au-pied" style="margin-top:10px">${t(_REGLE_TEMPS.includes(d.decl) ? 'zau_notePartir' : 'zau_noteFutur')}</div>
    <div style="display:flex;gap:8px;margin:12px 0 26px">
      <button class="btn btn-ghost" style="flex:1" onclick="regleAnnuler()">${t('zau_annuler')}</button>
      <button class="btn btn-primary" style="flex:1" onclick="regleEnregistrer()">${t('zau_enregistrer')}</button>
    </div>
  </div>`;
}

// ── Les gestes ──────────────────────────────────────────────────────
function _regleModele() {
  return { id: null, nom: '', actif: true, decl: 'cmd_livree', cond: 'aucune', val: '',
           act: 'wa_client', delai: 0, attenteH: 2, texte: t('zau_texteDefaut') };
}
function regleNouvelle() {
  if (!_planHasFeature('advancedAnalytics')) { _showPlanFeatureModal('advancedAnalytics'); return; }
  S.regleEdit = _regleModele();
  nav('automatisation-edit');
}
// Une recette s'ouvre dans l'éditeur : le commerçant voit exactement ce
// qu'elle fera avant de l'enregistrer. Rien ne s'arme dans son dos.
function regleRecette(id) {
  if (!_planHasFeature('advancedAnalytics')) { _showPlanFeatureModal('advancedAnalytics'); return; }
  const rc = BARO_REGLE_RECETTES().find(x => x.id === id);
  if (!rc) return;
  S.regleEdit = { ..._regleModele(), nom: rc.nom, decl: rc.decl, cond: rc.cond,
                  val: rc.val == null ? '' : rc.val, act: rc.act, delai: rc.delai,
                  attenteH: rc.attenteH || 2, texte: rc.texte };
  nav('automatisation-edit');
}
function regleModifier(id) {
  const r = _reglesCharge().find(x => x && x.id === id);
  if (!r) return;
  S.regleEdit = JSON.parse(JSON.stringify(r));
  nav('automatisation-edit');
}
function regleChamp(k, v, redessine) {
  if (!S.regleEdit) return;
  S.regleEdit[k] = v;
  if (redessine) { render(); return; }
  const ap = document.getElementById('au-apercu');
  if (ap) ap.textContent = _regleApercuTexte(S.regleEdit);
  const jt = document.getElementById('au-jetons');
  if (jt) { const m = _regleJetonsAvert(S.regleEdit); jt.textContent = m; jt.hidden = !m; }
}
function regleInsereVar(v) {
  const ta = document.getElementById('au-texte');
  if (!ta || !S.regleEdit) return;
  const tag = '{{' + v + '}}';
  const a = ta.selectionStart == null ? ta.value.length : ta.selectionStart;
  const b = ta.selectionEnd == null ? a : ta.selectionEnd;
  ta.value = ta.value.slice(0, a) + tag + ta.value.slice(b);
  ta.focus();
  ta.selectionStart = ta.selectionEnd = a + tag.length;
  regleChamp('texte', ta.value);
}
function regleAnnuler() { S.regleEdit = null; nav('automatisations'); }
function regleEnregistrer() {
  const d = S.regleEdit;
  if (!d) return;
  if (!_planHasFeature('advancedAnalytics')) { _showPlanFeatureModal('advancedAnalytics'); return; }
  const nom = String(d.nom || '').trim();
  if (!nom) { showToast(t('zau_errNom'), 'error'); return; }
  if (!String(d.texte || '').trim()) { showToast(t('zau_errTexte'), 'error'); return; }
  const decl = BARO_REGLE_DECL.includes(d.decl) ? d.decl : 'cmd_livree';
  const conds = _regleConds(decl);
  const cond = conds.includes(d.cond) ? d.cond : 'aucune';
  if (['montant_min', 'montant_max', 'fidele', 'palier'].includes(cond)) {
    const n = Number(d.val);
    if (!isFinite(n) || n <= 0) { showToast(t('zau_errValeur'), 'error'); return; }
  }
  if (cond === 'zone' && !String(d.val || '').trim()) { showToast(t('zau_errValeur'), 'error'); return; }
  const acts = _regleActs(decl);
  const regles = _reglesCharge();
  const i = d.id ? regles.findIndex(x => x && x.id === d.id) : -1;
  // Les compteurs viennent de la règle VIVANTE, pas de la copie ouverte dans
  // l'éditeur : pendant qu'on rédige, la règle a pu s'exécuter ; reprendre
  // la copie remettrait le plafond du jour à zéro.
  const vivant = i >= 0 ? regles[i] : null;
  const propre = {
    id: d.id || ('rg_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6)),
    nom: nom.slice(0, 60),
    actif: d.actif !== false,
    decl, cond,
    val: cond === 'aucune' || cond === 'premiere' ? '' : String(d.val == null ? '' : d.val).trim().slice(0, 40),
    act: acts.includes(d.act) ? d.act : acts[0],
    delai: decl === 'cmd_attente' ? 0 : (BARO_REGLE_DELAIS.includes(Number(d.delai)) ? Number(d.delai) : 0),
    attenteH: Math.min(168, Math.max(1, Math.round(Number(d.attenteH) || 2))),
    texte: String(d.texte).slice(0, 900),
    nb: vivant ? (vivant.nb || 0) : 0,
    dernier: vivant ? (vivant.dernier || null) : null,
    jour: vivant ? (vivant.jour || null) : null,
    nbJour: vivant ? (vivant.nbJour || 0) : 0,
    jourIgnores: vivant ? (vivant.jourIgnores || null) : null,
    ignoresJour: vivant ? (vivant.ignoresJour || 0) : 0,
    plafondVu: vivant ? (vivant.plafondVu || null) : null,
    cree: vivant ? (vivant.cree || new Date().toISOString()) : new Date().toISOString(),
  };
  // Un déclencheur, une condition ou un seuil changé : pour ce qui est déjà
  // en cours, la règle repart de maintenant.
  const cle = x => ['decl', 'cond', 'val', 'attenteH'].map(k => String(x[k] == null ? '' : x[k])).join('|');
  const change = !vivant || cle(vivant) !== cle(propre);
  if (i >= 0) regles[i] = propre; else regles.push(propre);
  if (!_reglesSauve()) return;
  const n = (change && propre.actif) ? _regleBaseline(propre) : 0;
  try { logAudit('automatisations', i >= 0 ? 'regle_modifiee' : 'regle_creee', { regle: propre.nom }); } catch (_) {}
  S.regleEdit = null;
  haptic('success');
  showToast(n ? t(n > 1 ? 'zau_okBaseline' : 'zau_okBaseline1').replace('{0}', n) : t(i >= 0 ? 'zau_okModif' : 'zau_okCree'));
  nav('automatisations');
}
function regleBascule(id) {
  const r = _reglesCharge().find(x => x && x.id === id);
  if (!r) return;
  r.actif = !r.actif;
  if (r.actif) _regleBaseline(r);
  // Éteinte, une règle ne garde rien en réserve : rallumée dans un mois,
  // elle n'enverrait pas d'un coup ce qu'elle avait programmé.
  else _reglesPlanifSauve(_reglesPlanif().filter(x => x && x.regle !== id));
  _reglesSauve();
  haptic('tap');
  render();
}
function regleSupprimer(id) {
  const r = _reglesCharge().find(x => x && x.id === id);
  if (!r) return;
  if (!confirm(t('zau_confirmSuppr').replace('{0}', r.nom || ''))) return;
  S.regles = _reglesCharge().filter(x => x && x.id !== id);
  _reglesSauve();
  // Ce qui était programmé au nom de cette règle ne partira pas.
  _reglesPlanifSauve(_reglesPlanif().filter(x => x && x.regle !== id));
  const vus = _reglesVus(); delete vus[id]; _reglesVusSauve(vus);
  try { logAudit('automatisations', 'regle_supprimee', { regle: r.nom }); } catch (_) {}
  if (S.regleApercu === id) S.regleApercu = null;
  haptic('tap');
  render();
}
function regleApercu(id) { S.regleApercu = S.regleApercu === id ? null : id; render(); }

// Trigger auto WhatsApp on sale/ship (appelé depuis les hooks de vente / livraison)
function triggerWhatsAppAuto(kind, data) {
  const cfg = _getWhatsAppConfig();
  if (!cfg) return;
  const map = { sale:'autoSale', ship:'autoShip', stock:'autoStock', delivered:'autoShip', payment:'autoSale' };
  if (!cfg[map[kind]]) return;
  const tplMap = { sale:'order_confirm', ship:'order_shipped', delivered:'order_delivered', stock:'low_stock_alert', payment:'payment_request' };
  const tpl = (cfg.templates||[]).find(t => t.id === tplMap[kind] && t.enabled);
  if (!tpl) return;
  const phone = data?.phone || cfg.phone;
  if (!phone) return;
  const body = _fillTemplate(tpl.body, {
    client: data.client || 'Client',
    ref: data.ref || '',
    total: fmt(data.total || 0),
    sym: sym(),
    business: cfg.signature || S.session?.business || 'BARO',
    tracking: data.tracking || '—',
    eta: data.eta || '—',
    payment_link: data.paymentLink || '',
    delivery: data.delivery || '—',
    article: data.article || '',
    stock: data.stock || '',
    unit: data.unit || '',
    promo_text: data.promo || '',
    expires: data.expires || '',
    gift: data.gift || '',
  });
  _sendWhatsAppMessage(phone, body, cfg);
}

// ══════════════════════════════════════════════════════════════
// SMS API multi-providers (Twilio, Vonage, Africa's Talking, Orange CI)
// ══════════════════════════════════════════════════════════════
const SMS_PROVIDERS = [
  { id:'twilio',    name:'Twilio',           fields:['accountSid','authToken','from'], sendFn:'_sendSmsTwilio',  url:'https://console.twilio.com/' },
  { id:'vonage',    name:'Vonage (Nexmo)',   fields:['apiKey','apiSecret','from'],     sendFn:'_sendSmsVonage',  url:'https://dashboard.nexmo.com/' },
  { id:'africatalking', name:"Africa's Talking", fields:['username','apiKey','from'],  sendFn:'_sendSmsAfrica',  url:'https://africastalking.com/' },
  { id:'orange-ci', name:'Orange CI SMS Pro', fields:['clientId','clientSecret','from'], sendFn:'_sendSmsOrange', url:'https://developer.orange.com/' },
  { id:'custom',    name:'API HTTP custom',  fields:['endpoint','authHeader','from'],  sendFn:'_sendSmsCustom',  url:'' },
];

let _smsTplCache = null, _smsTplLang = null;
function SMS_DEFAULT_TEMPLATES_() {
  if (_smsTplCache && _smsTplLang === _lang) return _smsTplCache;
  _smsTplLang = _lang;
  _smsTplCache = [
  { id:'order_confirm',   label:t('w1_lblConfirm'), enabled:true,  body:"{{business}}: Cmd {{ref}} confirmee. Total {{total}} {{sym}}. Merci!" },
  { id:'payment_request', label:t('w1_lblPaiement'),      enabled:true,  body:t('u_sFacture') },
  { id:'otp_code',        label:t('u_sCodeLbl'),  enabled:true,  body:t('u_sCode') },
  { id:'promo_push',      label:'Promo flash',           enabled:false, body:t('zz5_smsPromo') },
  ];
  return _smsTplCache;
}

function _getSmsConfig() {
  const cfg = (S.integrationsConfig || []).find(c => c.id === 'sms-api');
  return cfg && cfg.detail ? cfg.detail : null;
}

function vSmsSetup() {
  const cfg = (S.integrationsConfig || []).find(c => c.id === 'sms-api') || {};
  const d = cfg.detail || {};
  const connected = !!cfg.connected;
  const provider = SMS_PROVIDERS.find(p => p.id === d.provider) || SMS_PROVIDERS[0];
  const tpls = Array.isArray(d.templates) && d.templates.length ? d.templates : SMS_DEFAULT_TEMPLATES_();
  return `
  <div class="sub-hero sh-teinte" style="--sh-c1:#F59E0B;--sh-c2:#D97706">
    <div class="page-header-row" style="margin-bottom:10px">
      <button class="back-btn-dark" onclick="nav('integrations')">${IC.left}</button>
      <div style="flex:1">
        <div class="sub-hero-title">📨 SMS API</div>
        <div class="sub-hero-sub">${connected ? `✓ ${t('zwg_connecte')} — ${provider.name}` : t('v_smsEnvoyez')}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px">
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${connected?'✓':'—'}</div><div class="hero-stat-lbl">${t('orderStatus')}</div></div>
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${provider.name.split(' ')[0]}</div><div class="hero-stat-lbl">${t('z2_fournisseur')}</div></div>
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${tpls.filter(t=>t.enabled).length}</div><div class="hero-stat-lbl">${t('x1_modeles')}</div></div>
    </div>
  </div>
  <div class="container">
    <div class="card" style="margin-bottom:10px;background:#F59E0B08;border-color:#F59E0B40">
      <div style="display:flex;gap:10px;align-items:flex-start">
        <div style="font-size:24px">💡</div>
        <div style="flex:1;font-size:12px;color:var(--text-1);line-height:1.5">
          <strong style="color:#D97706">${t('x1_choisissezPasserelle')}</strong><br>
          BARO supporte <b>Twilio</b>, <b>Vonage</b>, <b>Africa's Talking</b> ${t('y5_tarifsBas')} <b>Orange CI Pro</b>${t('v_smsCompte')}
        </div>
      </div>
      ${provider.url ? `<div style="margin-top:10px"><button class="btn btn-ghost" style="width:100%;font-size:11px;padding:7px" onclick="window.open('${provider.url}','_blank')">🌐 Ouvrir console ${provider.name}</button></div>`:''}
    </div>

    <div class="card" style="margin-bottom:10px">
      <div class="card-title">📡 ${t('z2_fournisseur')}</div>
      <select id="sms-provider" class="input" onchange="S.smsSetupProvider=this.value;render()">
        ${SMS_PROVIDERS.map(p => `<option value="${p.id}" ${(d.provider||SMS_PROVIDERS[0].id)===p.id?'selected':''}>${p.name}</option>`).join('')}
      </select>
    </div>

    <div class="card" style="margin-bottom:10px">
      <div class="card-title">🔐 Identifiants ${provider.name}</div>
      ${provider.fields.map(f => {
        const labels = { accountSid:'Account SID', authToken:'Auth Token', apiKey:'API Key', apiSecret:'API Secret', username:'Username', from:t('v_smsSender'), clientId:'Client ID', clientSecret:'Client Secret', endpoint:'URL endpoint HTTP', authHeader:'Header Authorization' };
        const placeholders = { accountSid:'ACxxxxx', authToken:'xxxxx', apiKey:'xxxxx', apiSecret:'xxxxx', username:'sandbox', from:'+225 07 XX XX XX XX ou BARO', clientId:'xxxxx', clientSecret:'xxxxx', endpoint:'https://sms.provider.com/send', authHeader:'Bearer xxxxx' };
        const secret = ['authToken','apiSecret','apiKey','clientSecret','authHeader'].includes(f);
        return `
        <div style="margin-bottom:10px">
          <label style="font-size:11px;color:var(--text-3);display:block;margin-bottom:3px">${labels[f]||f}</label>
          <input id="sms-${f}" class="input" type="${secret?'password':'text'}" value="${(d[f]||'').replace(/"/g,'&quot;')}" placeholder="${placeholders[f]||''}">
        </div>`;
      }).join('')}
    </div>

    <div class="card" style="margin-bottom:10px">
      <div class="card-title">${t('x1_modelesSms')}</div>
      ${tpls.map(tpl => `
        <div class="card" style="margin-bottom:8px;padding:10px;background:var(--gray-1);border-radius:8px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
            <label style="display:flex;align-items:center;gap:6px;font-size:12px;font-weight:700;cursor:pointer">
              <input type="checkbox" class="sms-tpl-enabled" data-id="${tpl.id}" ${tpl.enabled?'checked':''}>
              ${tpl.label}
            </label>
            <button class="btn btn-ghost" style="padding:3px 8px;font-size:10px" onclick="testSmsTemplate('${tpl.id}')">🧪 Test</button>
          </div>
          <textarea class="input sms-tpl-body" data-id="${tpl.id}" rows="2" style="font-size:12px;font-family:monospace" maxlength="280">${tpl.body.replace(/</g,'&lt;')}</textarea>
          <div style="font-size:10px;color:var(--text-3);margin-top:4px">${tpl.body.length} car.</div>
        </div>
      `).join('')}
    </div>

    <div class="card" style="margin-bottom:10px">
      <div class="card-title">${t('x1_declencheursAuto')}</div>
      <label style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--border)">
        <div><div style="font-weight:700;font-size:13px">${t('x1_smsAutoVente')}</div><div style="font-size:11px;color:var(--text-3)">${t('x1_confirmationApres')}</div></div>
        <input type="checkbox" id="sms-auto-sale" ${d.autoSale?'checked':''}>
      </label>
      <label style="display:flex;justify-content:space-between;align-items:center;padding:10px 0">
        <div><div style="font-weight:700;font-size:13px">${t('x1_campagnesSms')}</div><div style="font-size:11px;color:var(--text-3)">${t('x1_permetPlusieurs')}</div></div>
        <input type="checkbox" id="sms-auto-campaign" ${d.autoCampaign!==false?'checked':''}>
      </label>
    </div>

    <div style="display:flex;gap:8px;margin-bottom:12px">
      <button class="btn btn-ghost" style="flex:1" onclick="testSmsConnection()">${t('x1_envoyerSmsTest')}</button>
      <button class="btn btn-primary" style="flex:1" onclick="saveSmsSetup()">${t('w7_enregistrer')}</button>
    </div>
    ${connected ? `<button class="btn" style="width:100%;color:var(--danger);border:1px solid var(--danger);background:transparent" onclick="disconnectIntegration('sms-api','SMS API')">${t('x1_deconnecterSms')}</button>` : ''}
  </div>`;
}

function saveSmsSetup() {
  const provId = document.getElementById('sms-provider')?.value || SMS_PROVIDERS[0].id;
  const provider = SMS_PROVIDERS.find(p => p.id === provId) || SMS_PROVIDERS[0];
  const detail = { provider: provId, updatedAt:new Date().toISOString() };
  provider.fields.forEach(f => { detail[f] = document.getElementById(`sms-${f}`)?.value.trim() || ''; });
  if (!detail.from) { showToast('Numéro / Sender ID émetteur obligatoire', 'error'); return; }
  detail.autoSale     = document.getElementById('sms-auto-sale')?.checked || false;
  detail.autoCampaign = document.getElementById('sms-auto-campaign')?.checked !== false;
  detail.templates = SMS_DEFAULT_TEMPLATES_().map(def => {
    const en = document.querySelector(`.sms-tpl-enabled[data-id="${def.id}"]`);
    const body = document.querySelector(`.sms-tpl-body[data-id="${def.id}"]`);
    return { ...def, enabled: en ? en.checked : def.enabled, body: body ? body.value : def.body };
  });
  const existing = S.integrationsConfig.findIndex(c => c.id === 'sms-api');
  const entry = { id:'sms-api', name:'SMS API ('+provider.name+')', connected:true, value: detail.from, date:new Date().toISOString(), detail };
  if (existing >= 0) S.integrationsConfig[existing] = entry;
  else S.integrationsConfig.push(entry);
  _sauveIntegrations();
  logActivity('integration', `SMS ${provider.name} configuré`);
  showToast('✓ Passerelle SMS configurée', 'success');
  nav('integrations');
}

function testSmsConnection() {
  const cfg = _getSmsConfig();
  if (!cfg) { showToast('Enregistrez d\'abord', 'error'); return; }
  const to = prompt('Numéro destinataire pour test (format international) :', cfg.from || '+225');
  if (!to) return;
  const msg = `[TEST BARO] Votre passerelle SMS est opérationnelle ✓ Provider: ${cfg.provider}`;
  sendSms(to, msg).then(ok => showToast(ok ? '✓ SMS envoyé' : '⚠ Échec — vérifiez clés/quota', ok?'success':'error'));
}

function testSmsTemplate(tplId) {
  const cfg = _getSmsConfig();
  if (!cfg) { showToast('Configurez SMS d\'abord', 'error'); return; }
  const body = document.querySelector(`.sms-tpl-body[data-id="${tplId}"]`)?.value || '';
  const to = prompt('Numéro test :', cfg.from || '+225');
  if (!to) return;
  const filled = _fillTemplate(body, {
    client:'Awa', ref:'INV-0042', total:fmt(25000), sym:sym(),
    business: S.session?.business || 'BARO',
    payment_link:'https://pay.example/xyz',
    code:'123456', promo_text:'-20%', expires:'31/12'
  });
  sendSms(to, filled);
}

async function sendSms(to, text) {
  const cfg = _getSmsConfig();
  if (!cfg) return false;
  const provider = SMS_PROVIDERS.find(p => p.id === cfg.provider);
  if (!provider) return false;
  const fn = window[provider.sendFn];
  try {
    const ok = fn ? await fn(to, text, cfg) : false;
    _logSmsSend(to, text, ok ? 'sent' : 'failed', cfg.provider);
    return ok;
  } catch(e) {
    _logSmsSend(to, text, 'error', cfg.provider, e.message);
    return false;
  }
}

async function _sendSmsTwilio(to, text, cfg) {
  const endpoint = `https://api.twilio.com/2010-04-01/Accounts/${cfg.accountSid}/Messages.json`;
  const auth = btoa(`${cfg.accountSid}:${cfg.authToken}`);
  const body = new URLSearchParams({ To: to, From: cfg.from, Body: text });
  const res = await fetch(endpoint, { method:'POST', mode:'cors', headers:{ 'Authorization':`Basic ${auth}`, 'Content-Type':'application/x-www-form-urlencoded' }, body });
  return res.ok;
}
async function _sendSmsVonage(to, text, cfg) {
  const endpoint = 'https://rest.nexmo.com/sms/json';
  const body = new URLSearchParams({ api_key:cfg.apiKey, api_secret:cfg.apiSecret, to:to.replace(/\+/g,''), from:cfg.from, text });
  const res = await fetch(endpoint, { method:'POST', mode:'cors', headers:{'Content-Type':'application/x-www-form-urlencoded'}, body });
  if (!res.ok) return false;
  const j = await res.json().catch(() => ({}));
  return (j.messages || [{}])[0].status === '0';
}
async function _sendSmsAfrica(to, text, cfg) {
  const endpoint = 'https://api.africastalking.com/version1/messaging';
  const body = new URLSearchParams({ username:cfg.username, to, message:text, from:cfg.from });
  const res = await fetch(endpoint, { method:'POST', mode:'cors', headers:{'apiKey':cfg.apiKey, 'Content-Type':'application/x-www-form-urlencoded', 'Accept':'application/json'}, body });
  return res.ok;
}
async function _sendSmsOrange(to, text, cfg) {
  // Orange CI SMS Pro requires OAuth token first
  const tokenRes = await fetch('https://api.orange.com/oauth/v3/token', {
    method:'POST', mode:'cors',
    headers:{ 'Authorization':`Basic ${btoa(cfg.clientId+':'+cfg.clientSecret)}`, 'Content-Type':'application/x-www-form-urlencoded' },
    body: 'grant_type=client_credentials'
  });
  if (!tokenRes.ok) return false;
  const { access_token } = await tokenRes.json();
  const endpoint = `https://api.orange.com/smsmessaging/v1/outbound/tel%3A%2B${String(cfg.from).replace(/\D/g,'')}/requests`;
  const res = await fetch(endpoint, {
    method:'POST', mode:'cors',
    headers:{ 'Authorization':`Bearer ${access_token}`, 'Content-Type':'application/json' },
    body: JSON.stringify({ outboundSMSMessageRequest:{ address:`tel:${to}`, senderAddress:`tel:+${String(cfg.from).replace(/\D/g,'')}`, outboundSMSTextMessage:{ message:text } } })
  });
  return res.ok;
}
async function _sendSmsCustom(to, text, cfg) {
  if (!cfg.endpoint) return false;
  const res = await fetch(cfg.endpoint, {
    method:'POST', mode:'cors',
    headers:{ 'Authorization': cfg.authHeader || '', 'Content-Type':'application/json' },
    body: JSON.stringify({ to, text, from:cfg.from })
  });
  return res.ok;
}

function _logSmsSend(to, text, status, provider, error) {
  const key = 'stockr_sms_log';
  const log = JSON.parse(localStorage.getItem(key) || '[]');
  log.unshift({ id:'sms_'+Date.now().toString(36), to, preview:text.slice(0,80), status, provider, error:error||null, date:new Date().toISOString() });
  localStorage.setItem(key, JSON.stringify(log.slice(0, 200)));
}

// ══════════════════════════════════════════════════════════════
// BROADCAST — Envoi de masse WhatsApp + SMS (réel, depuis les clients)
// ══════════════════════════════════════════════════════════════
// Remplace les variables {nom} / {business} / {ville} dans un message.
function _personalizeMsg(tpl, cl) {
  return String(tpl || '')
    .replace(/\{nom\}/gi, (cl && cl.name) || 'client')
    .replace(/\{business\}/gi, (S.session && S.session.business) || 'notre boutique')
    .replace(/\{ville\}/gi, (cl && cl.city) || '');
}
// Normalise un numéro pour wa.me (international sans +, CI par défaut).
function _waNormalize(p) {
  let d = String(p || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.length <= 10 && !d.startsWith('225')) d = '225' + d;
  return d;
}

function _waBcastState() {
  if (!S._waBcast) {
    const biz = (S.session && S.session.business) || 'notre boutique';
    S._waBcast = { msg: t('zz8_waDefaut').replace('{0}', biz), sent: {} };
  }
  return S._waBcast;
}

// ══════════════════════════════════════════════════════════════
// MESSAGES EN ATTENTE
// Un envoi automatique sans API Cloud est impossible : le navigateur
// bloque toute fenêtre ouverte hors d'un geste. Les messages sont donc
// écrits, rangés ici, et partent d'un tap. Ce qui est parti reste visible
// en dessous : sans trace, un envoi automatique est invérifiable.
// ══════════════════════════════════════════════════════════════
function _wafEsc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function vWhatsappFile() {
  const f = _waFileCharge();
  // Tri par l'heure de l'événement, pas par l'ordre d'arrivée dans la
  // file : deux envois lancés à 900 ms d'écart peuvent échouer dans
  // l'ordre inverse selon la lenteur du réseau.
  const parDate = (a, b) => new Date(b.date || 0) - new Date(a.date || 0);
  const attente = f.filter(x => x && x.etat === 'attente').sort(parDate);
  const partis  = f.filter(x => x && x.etat !== 'attente').sort(parDate).slice(0, 20);
  const cfg = _getWhatsAppConfig();
  const MOM = {};
  BARO_MOMENTS_CMD.forEach(m => { MOM[m.cle] = m.icone + ' ' + t('zwf_m_' + m.cle); });
  MOM.stock = '⚠️ ' + t('zwf_m_stock');

  const carte = (x, enAttente) => `
    <div class="waf-c${enAttente ? '' : ' partie'}">
      <div class="waf-h">
        <span class="waf-q">${_wafEsc(x.moment === 'regle' ? '⚙️ ' + (x.regleNom || t('zau_titre')) : (MOM[x.moment] || x.moment || ''))}</span>
        <span class="waf-d">${fmtTimeAgo(x.date)}</span>
      </div>
      <div class="waf-qui">${_wafEsc(x.client || '')} · ${_wafEsc(x.phone || '')}</div>
      <div class="waf-tx">${_wafEsc(x.texte || '')}</div>
      ${x.detail ? `<div class="waf-pq">${_wafEsc(x.detail)}</div>` : ''}
      ${enAttente ? `
      <div class="waf-act">
        <button class="btn btn-primary" onclick="waFileEnvoyer('${_wafEsc(x.id)}')">${t('zwf_envoyer')}</button>
        <button class="btn btn-ghost" onclick="waFileSupprimer('${_wafEsc(x.id)}')">${t('zwf_jeter')}</button>
      </div>` : `<div class="waf-etat">${t(x.etat === 'envoye' ? 'zwf_parti' : 'zwf_jete')}</div>`}
    </div>`;

  return `
  <div class="sub-hero sh-teinte" style="--sh-c1:#25D366;--sh-c2:#128C7E">
    <div class="page-header-row" style="margin-bottom:10px">
      <button class="back-btn-dark" onclick="nav('whatsapp-setup')">${IC.left}</button>
      <div style="flex:1">
        <div class="sub-hero-title">${t('zwf_titre')}</div>
        <div class="sub-hero-sub">${t('zwf_sousTitre')}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px">
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${attente.length}</div><div class="hero-stat-lbl">${t('zwf_enAttente')}</div></div>
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${cfg && cfg.mode === 'business' ? 'META' : 'wa.me'}</div><div class="hero-stat-lbl">Mode</div></div>
    </div>
  </div>
  <div class="container">
    ${(cfg && cfg.mode === 'business') ? '' : `
    <div class="card" style="margin-bottom:10px;background:var(--warning-bg,#F59E0B12);border-color:#F59E0B40">
      <div style="font-size:12px;line-height:1.55;color:var(--text-1)">${t('zwf_pourquoi')}</div>
      <button class="btn btn-ghost" style="width:100%;margin-top:9px" onclick="nav('whatsapp-setup')">${t('zwf_brancher')}</button>
    </div>`}

    ${(() => { let n = 0; try { n = Number(localStorage.getItem('baro_wa_file_perdus')) || 0; } catch (_) {}
      return n ? `
    <div class="au-avert" style="margin-bottom:10px">${t('zwf_fileSaturee').replace('{0}', n)}
      <button class="int-journal-x" style="margin-left:6px" onclick="waFileComprisPerdus()">${t('zwf_compris')}</button></div>` : ''; })()}
    ${attente.length === 0 && partis.length === 0 ? `
    <div class="empty">
      <div class="empty-ico">${IC.inbox}</div>
      <div class="empty-title">${t('zwf_videT')}</div>
      <div class="empty-text">${t('zwf_videD')}</div>
      <button class="btn btn-primary" style="width:auto;padding:11px 24px" onclick="nav('whatsapp-setup')">${t('zwf_reglages')}</button>
    </div>` : ''}

    ${attente.length ? `
    <div class="section-title" style="margin:2px 0 8px">${t('zwf_enAttente')} (${attente.length})</div>
    ${attente.map(x => carte(x, true)).join('')}` : ''}

    ${partis.length ? `
    <div class="section-title" style="margin:16px 0 8px;display:flex;justify-content:space-between;align-items:center">
      <span>${t('zwf_dejaPartis')}</span>
      <button class="int-journal-x" onclick="waFileViderPartis()">${t('zi_vider')}</button>
    </div>
    ${partis.map(x => carte(x, false)).join('')}` : ''}
  </div>`;
}

// Un tap du commerçant : c'est le geste que le navigateur exige pour
// ouvrir WhatsApp. C'est pour cela que l'envoi ne peut pas être
// automatique sans l'API Cloud, et l'écran le dit.
function waFileEnvoyer(id) {
  const f = _waFileCharge();
  const x = f.find(y => y && y.id === id);
  if (!x) return;
  window.open('https://wa.me/' + _waNormalize(x.phone) + '?text=' + encodeURIComponent(x.texte), '_blank');
  x.etat = 'envoye';
  x.envoyeLe = new Date().toISOString();
  _waFileSauve();
  try { _logWhatsAppSend(x.phone, x.texte, 'opened'); } catch (_) {}
  haptic('success');
  showToast(t('zwf_ouvert'));
  render();
}

function waFileSupprimer(id) {
  const f = _waFileCharge();
  const x = f.find(y => y && y.id === id);
  if (!x) return;
  x.etat = 'jete';
  _waFileSauve();
  haptic('tap');
  render();
}

function waFileViderPartis() {
  S.waFile = _waFileCharge().filter(x => x && x.etat === 'attente');
  _waFileSauve();
  haptic('tap');
  render();
}

function vWhatsappBroadcast() {
  const st = _waBcastState();
  const clients = (S.clients || []).filter(c => c.phone);
  const promos = (S.promotions || []).filter(p => p.active);
  const sentCount = clients.filter(c => st.sent[c.id]).length;
  const pct = clients.length ? Math.round(sentCount / clients.length * 100) : 0;
  return `
  <div class="sub-hero sh-teinte" style="--sh-c1:#25D366;--sh-c2:#128C7E">
    <div class="page-header-row" style="margin-bottom:10px">
      <button class="back-btn-dark" onclick="nav('integrations')">${IC.left}</button>
      <div style="flex:1">
        <div class="sub-hero-title">${IC.whatsapp} Broadcast WhatsApp</div>
        <div class="sub-hero-sub">${t('w9_envoyezUnParUn')}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px">
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${clients.length}</div><div class="hero-stat-lbl">${t('zy_clients')}</div></div>
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${sentCount}</div><div class="hero-stat-lbl">${t('w9_envoyes')}</div></div>
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${pct}%</div><div class="hero-stat-lbl">Progression</div></div>
    </div>
  </div>
  <div class="container">
    ${clients.length === 0 ? `
      <div class="card" style="text-align:center;padding:30px 18px">
        <div style="font-size:34px;margin-bottom:8px">📇</div>
        <div style="font-weight:800;margin-bottom:4px">${t('w9_aucunClientNum')}</div>
        <div style="font-size:12px;color:var(--text-3);margin-bottom:14px">${t('v_waGroupe')}</div>
        <button class="btn btn-primary" onclick="nav('add-client')">${t('w9_ajouterClient')}</button>
      </div>` : `
      <div class="card" style="margin-bottom:10px">
        <div class="card-title">${t('w9_votreMessage')}</div>
        <textarea id="wa-bcast-msg" class="input" rows="5" style="font-size:13px;line-height:1.5" oninput="S._waBcast.msg=this.value">${st.msg.replace(/</g,'&lt;')}</textarea>
        <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
          <button class="btn btn-ghost" style="font-size:11px;padding:5px 10px" onclick="_waBcastInsert('{nom}')">+ {nom}</button>
          <button class="btn btn-ghost" style="font-size:11px;padding:5px 10px" onclick="_waBcastInsert('{business}')">+ {business}</button>
          ${promos.length ? `<button class="btn btn-ghost" style="font-size:11px;padding:5px 10px" onclick="_waBcastAddPromo()">+ Promo en cours</button>` : ''}
        </div>
        <div style="font-size:11px;color:var(--text-3);margin-top:8px;line-height:1.4">💡 <b>{nom}</b> ${t('zq_nomRemplace')}. ${t('zr_waConv')}</div>
      </div>
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <button class="btn btn-primary" style="flex:1;background:#25D366" onclick="_waBcastNext()">${IC.whatsapp} ${t('zq_ouvrirSuivant').replace('{0}', clients.length - sentCount)})</button>
        ${sentCount ? `<button class="btn btn-ghost" onclick="_waBcastReset()">${t('w9_reinit')}</button>` : ''}
      </div>
      <div class="card" style="padding:6px 0">
        ${clients.map(c => {
          const done = !!st.sent[c.id];
          return `<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--border)">
            <div style="width:34px;height:34px;border-radius:50%;background:${done?'#25D36620':'var(--gray-1)'};display:flex;align-items:center;justify-content:center;font-weight:800;color:${done?'#128C7E':'var(--text-2)'}">${done?'✓':(c.name||'?').charAt(0).toUpperCase()}</div>
            <div style="flex:1;min-width:0">
              <div style="font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${(c.name||'Client').replace(/</g,'&lt;')}</div>
              <div style="font-size:11px;color:var(--text-3)">${c.phone}</div>
            </div>
            <button class="btn ${done?'btn-ghost':'btn-secondary'}" style="padding:6px 12px;font-size:12px" onclick="_waBcastSendOne('${c.id}')">${done?t('zzf_renvoyer'):t('campaignSend')}</button>
          </div>`;
        }).join('')}
      </div>`}
  </div>`;
}
function _waBcastInsert(token) {
  const ta = document.getElementById('wa-bcast-msg');
  const st = _waBcastState();
  if (ta) {
    const s = ta.selectionStart || ta.value.length;
    ta.value = ta.value.slice(0, s) + token + ta.value.slice(ta.selectionEnd || s);
    st.msg = ta.value; ta.focus();
  } else { st.msg += token; render(); }
}
function _waBcastAddPromo() {
  const promos = (S.promotions || []).filter(p => p.active);
  if (!promos.length) return;
  const txt = '\n\n🎁 Offres en cours :\n' + promos.map(p => `• ${p.name} (-${p.discount}%)`).join('\n');
  const st = _waBcastState();
  st.msg += txt;
  render();
}
function _waBcastSendOne(id) {
  const st = _waBcastState();
  const cl = (S.clients || []).find(c => String(c.id) === String(id));
  if (!cl) return;
  const phone = _waNormalize(cl.phone);
  const msg = _personalizeMsg(st.msg, cl);
  window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  st.sent[id] = true;
  _waBcastSyncCampaign();
  if (typeof haptic === 'function') haptic('tap');
  render();
}
// Historise/maj la campagne WhatsApp au fil des envois (la même session = 1 campagne)
function _waBcastSyncCampaign() {
  const st = _waBcastState();
  const clients = (S.clients||[]).filter(c=>c.phone);
  const sentCount = clients.filter(c=>st.sent[c.id]).length;
  if (!Array.isArray(S.campaigns)) S.campaigns = [];
  if (!st.campaignId) {
    st.campaignId = Date.now();
    S.campaigns.unshift({ id: st.campaignId, name:'Broadcast WhatsApp', type:'whatsapp', message:String(st.msg||'').slice(0,280), recipients: clients.length, sent:true, sentCount, date:new Date().toISOString(), sentDate:new Date().toISOString() });
    if (S.campaigns.length > 100) S.campaigns = S.campaigns.slice(0,100);
  } else {
    const c = S.campaigns.find(x=>x.id===st.campaignId);
    if (c) { c.sentCount = sentCount; c.sentDate = new Date().toISOString(); }
  }
  localStorage.setItem('baro_campaigns', JSON.stringify(S.campaigns));
}
function _waBcastNext() {
  const st = _waBcastState();
  const clients = (S.clients || []).filter(c => c.phone);
  const next = clients.find(c => !st.sent[c.id]);
  if (!next) { showToast('Tous les clients ont été contactés ✓', 'success'); return; }
  _waBcastSendOne(next.id);
}
function _waBcastReset() {
  const st = _waBcastState();
  st.sent = {};
  st.campaignId = null;
  showToast('Progression réinitialisée');
  render();
}

function _smsBcastState() {
  if (!S._smsBcast) {
    const biz = (S.session && S.session.business) || 'Notre boutique';
    S._smsBcast = { msg: t('zz8_smsDefaut').replace('{0}', biz), running: false, results: {} };
  }
  return S._smsBcast;
}

function vSmsBroadcast() {
  const st = _smsBcastState();
  const cfg = _getSmsConfig();
  const clients = (S.clients || []).filter(c => c.phone);
  const okCount = clients.filter(c => st.results[c.id] === 'sent').length;
  const failCount = clients.filter(c => st.results[c.id] === 'failed').length;
  return `
  <div class="sub-hero sh-teinte" style="--sh-c1:#4F46E5;--sh-c2:#4338CA">
    <div class="page-header-row" style="margin-bottom:10px">
      <button class="back-btn-dark" onclick="nav('integrations')">${IC.left}</button>
      <div style="flex:1">
        <div class="sub-hero-title">${t('w9_smsGroupe')}</div>
        <div class="sub-hero-sub">${cfg ? 'Envoi automatique via votre passerelle' : t('v_smsPasserelle')}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px">
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${clients.length}</div><div class="hero-stat-lbl">${t('zy_clients')}</div></div>
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${okCount}</div><div class="hero-stat-lbl">${t('w9_envoyes')}</div></div>
      <div class="hero-stat" style="flex:1"><div class="hero-stat-val">${failCount}</div><div class="hero-stat-lbl">${t('w9_echecs')}</div></div>
    </div>
  </div>
  <div class="container">
    ${!cfg ? `
      <div class="card" style="margin-bottom:10px;background:#4F46E508;border-color:#4F46E540">
        <div style="display:flex;gap:10px;align-items:flex-start">
          <div style="font-size:24px">⚙️</div>
          <div style="flex:1;font-size:12px;color:var(--text-1);line-height:1.5">
            <strong style="color:#4338CA">${t('w9_configPasserelle')}</strong><br>
            ${t('v_smsPourEnvoi')} <b>automatique</b> ${t('v_smsMasse')}
          </div>
        </div>
        <button class="btn btn-primary" style="width:100%;margin-top:10px" onclick="nav('sms-setup')">${t('w9_configurerSms')}</button>
      </div>` : ''}
    ${clients.length === 0 ? `
      <div class="card" style="text-align:center;padding:30px 18px">
        <div style="font-size:34px;margin-bottom:8px">📇</div>
        <div style="font-weight:800;margin-bottom:4px">${t('w9_aucunClientNum')}</div>
        <div style="font-size:12px;color:var(--text-3);margin-bottom:14px">${t('y3_ajoutezClientsTel')}</div>
        <button class="btn btn-primary" onclick="nav('add-client')">${t('w9_ajouterClient')}</button>
      </div>` : `
      <div class="card" style="margin-bottom:10px">
        <div class="card-title">${t('w9_votreMessage')} <span style="font-weight:500;color:var(--text-3);font-size:11px">(${st.msg.length} car.)</span></div>
        <textarea id="sms-bcast-msg" class="input" rows="4" maxlength="320" style="font-size:13px;line-height:1.5" oninput="S._smsBcast.msg=this.value;render()">${st.msg.replace(/</g,'&lt;')}</textarea>
        <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
          <button class="btn btn-ghost" style="font-size:11px;padding:5px 10px" onclick="_smsBcastInsert('{nom}')">+ {nom}</button>
          <button class="btn btn-ghost" style="font-size:11px;padding:5px 10px" onclick="_smsBcastInsert('{business}')">+ {business}</button>
        </div>
        <div style="font-size:11px;color:var(--text-3);margin-top:8px;line-height:1.4">${t('w9_gardezSmsCourt')} ${t('y3_personnaliseParClient').replace('{0}','<b>{nom}</b>')}</div>
      </div>
      ${cfg ? `
      <button class="btn btn-primary" style="width:100%;margin-bottom:10px;background:#4F46E5" onclick="sendSmsBroadcast()" ${st.running?'disabled':''}>
        ${st.running ? '⏳ Envoi en cours…' : `📨 Envoyer à ${clients.length} client${clients.length>1?'s':''}`}
      </button>` : `
      <button class="btn btn-primary" style="width:100%;margin-bottom:10px" onclick="_smsBcastNative()">${t('zq_ouvrirSms').replace('{0}', clients.length)}</button>`}
      <div class="card" style="padding:6px 0">
        ${clients.map(c => {
          const r = st.results[c.id];
          const color = r === 'sent' ? '#16A34A' : r === 'failed' ? 'var(--danger)' : 'var(--text-3)';
          const icon = r === 'sent' ? '✓' : r === 'failed' ? '✕' : '·';
          return `<div style="display:flex;align-items:center;gap:10px;padding:9px 14px;border-bottom:1px solid var(--border)">
            <div style="width:22px;text-align:center;font-weight:800;color:${color}">${icon}</div>
            <div style="flex:1;min-width:0">
              <div style="font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${(c.name||'Client').replace(/</g,'&lt;')}</div>
              <div style="font-size:11px;color:var(--text-3)">${c.phone}</div>
            </div>
            ${r==='failed'?`<span style="font-size:10px;color:var(--danger)">${t('y3_echec')}</span>`:r==='sent'?`<span style="font-size:10px;color:#16A34A">${t('y3_envoye')}</span>`:''}
          </div>`;
        }).join('')}
      </div>`}
  </div>`;
}
function _smsBcastInsert(token) {
  const ta = document.getElementById('sms-bcast-msg');
  const st = _smsBcastState();
  if (ta) {
    const s = ta.selectionStart || ta.value.length;
    ta.value = ta.value.slice(0, s) + token + ta.value.slice(ta.selectionEnd || s);
    st.msg = ta.value; ta.focus();
  } else { st.msg += token; }
  render();
}
function _smsBcastNative() {
  const clients = (S.clients || []).filter(c => c.phone);
  if (!clients.length) return;
  const st = _smsBcastState();
  const phones = clients.map(c => c.phone.replace(/\s/g, '')).join(',');
  // Message non personnalisé (l'app SMS native ne gère pas {nom})
  const msg = st.msg.replace(/\{nom\}/gi, '').replace(/\s{2,}/g, ' ').trim();
  window.location.href = `sms:${phones}?body=${encodeURIComponent(msg)}`;
}
async function sendSmsBroadcast() {
  const st = _smsBcastState();
  const cfg = _getSmsConfig();
  if (!cfg) { showToast('Configurez d\'abord la passerelle SMS', 'error'); nav('sms-setup'); return; }
  const clients = (S.clients || []).filter(c => c.phone);
  if (!clients.length) return;
  if (st.running) return;
  st.running = true; st.results = {}; render();
  let ok = 0, fail = 0;
  for (const cl of clients) {
    const text = _personalizeMsg(st.msg, cl);
    let sent = false;
    try { sent = await sendSms(cl.phone, text); } catch (_) { sent = false; }
    st.results[cl.id] = sent ? 'sent' : 'failed';
    sent ? ok++ : fail++;
    render();
  }
  st.running = false;
  logActivity('campaign', `SMS groupé — ${ok} envoyés, ${fail} échecs`);
  _logCampaign('sms', st.msg, clients.length, ok);
  showToast(fail ? `Terminé : ${ok} envoyés, ${fail} échecs` : `✓ ${ok} SMS envoyés !`, fail ? 'info' : 'success');
  render();
}

// Historise un envoi de masse dans S.campaigns (vue Campagnes unifiée)
function _logCampaign(type, message, recipients, sentCount) {
  if (!Array.isArray(S.campaigns)) S.campaigns = [];
  const names = { whatsapp:'Broadcast WhatsApp', sms:'SMS groupé', email:'Email groupé' };
  S.campaigns.unshift({
    id: Date.now(),
    name: names[type] || 'Campagne',
    type,
    message: String(message||'').slice(0, 280),
    recipients: recipients||0,
    sent: true,
    sentCount: sentCount||0,
    date: new Date().toISOString(),
    sentDate: new Date().toISOString(),
  });
  if (S.campaigns.length > 100) S.campaigns = S.campaigns.slice(0, 100);
  localStorage.setItem('baro_campaigns', JSON.stringify(S.campaigns));
}

// ── BROADCAST EMAIL (mailto groupé en BCC — réel, sans backend) ──
